#------------------Helper Functions--------------------------------------------

# Generate random invitation code with dashes
generate_random_code <- function() {
  chars <- c(0:9, LETTERS)
  part1 <- paste0(sample(chars, 4, replace = TRUE), collapse = "")
  part2 <- paste0(sample(chars, 4, replace = TRUE), collapse = "")
  part3 <- paste0(sample(chars, 4, replace = TRUE), collapse = "")
  paste(part1, part2, part3, sep = "-")
}

#----------------------FMSB RADAR CHART FUNCTIONS-------------------------------

make_radar_df_from_inputs_fmsb <- function(input,
                                           questions,
                                           group_name = "Aktueller Stand",
                                           binary_qnums = integer()) {
  vals <- sapply(questions, function(q) {
    qid <- q$id
    qnum <- suppressWarnings(as.numeric(sub("^[A-Za-z]+", "", qid)))
    v <- input[[paste0("Freitext", qid)]]
    
    if (is.null(v) ||
        v == "" || v == "N/A" || is.na(v))
      return(NA_real_)
    
    if (!is.na(qnum) && qnum %in% binary_qnums) {
      if (v == "Ja")
        return(1)
      if (v == "Nein")
        return(0)
      return(NA_real_)
    }
    
    as.numeric(v)
  })
  
  vals[is.na(vals)] <- 0
  
  axis_names <- sapply(questions, function(q)
    sprintf("%d", as.numeric(gsub("\\D", "", q$label))))
  
  max_min <- data.frame(matrix(c(5, 0), nrow = 2, ncol = length(vals)))
  colnames(max_min) <- axis_names
  rownames(max_min) <- c("Max", "Min")
  
  data_row <- data.frame(t(vals))
  colnames(data_row) <- axis_names
  rownames(data_row) <- group_name
  
  df <- rbind(max_min, data_row)
  
  return(df)
}


#-------------------Create beautiful radar chart (fmsb style)-------------------

create_beautiful_radarchart <- function(data,
                                        color = "#00AFBB",
                                        vlabels = colnames(data),
                                        vlcex = 1.0,
                                        caxislabels = NULL,
                                        title = NULL,
                                        ...) {
  # Set up plot parameters
  op <- par(mar = c(1, 1, 2, 1))
  
  radarchart(
    data,
    axistype = 1,
    
    # Customize the polygon
    pcol = color,
    # Line color
    pfcol = scales::alpha(color, 0.5),
    # Fill color (semi-transparent)
    plwd = 2,
    # Line width
    plty = 1,
    # Line type (solid)
    
    # Customize the grid
    cglcol = "grey",
    # Grid color
    cglty = 1,
    # Grid line type
    cglwd = 0.8,
    # Grid line width
    
    # Customize the axis
    axislabcol = "grey",
    # Axis label color
    
    # Variable labels
    vlcex = vlcex,
    # Label size
    vlabels = vlabels,
    # Label text
    
    # Axis labels
    caxislabels = caxislabels,
    # Custom axis labels
    
    # Title
    title = title,
    
    ...
  )
  
  par(op)
}

#----------------Wrapper function for radar charts-----------------------------
make_fmsb_radar_plot <- function(radar_df, title, colour = "#003B73") {
  # Defensive checks
  if (is.null(radar_df) || nrow(radar_df) == 0) {
    plot.new()
    text(0.5, 0.5, "Keine Daten vorhanden", cex = 1.5)
    return(invisible(NULL))
  }
  
  # Check if we have the required Max/Min rows
  if (!all(c("Max", "Min") %in% rownames(radar_df))) {
    plot.new()
    text(0.5, 0.5, "UngÃ¼ltiges Datenformat", cex = 1.5)
    return(invisible(NULL))
  }
  
  # Get the data (skip Max/Min rows)
  data_rows <- radar_df[!rownames(radar_df) %in% c("Max", "Min"), , drop = FALSE]
  
  # Check if all values are zero
  if (nrow(data_rows) > 0 && all(data_rows == 0, na.rm = TRUE)) {
    plot.new()
    text(0.5, 0.5, "Keine Daten vorhanden", cex = 1.5)
    return(invisible(NULL))
  }
  
  # Create the plot
  create_beautiful_radarchart(
    data = radar_df,
    color = colour,
    vlabels = colnames(radar_df),
    vlcex = 1.0,
    caxislabels = c("0", "1", "2", "3", "4", "5"),
    title = title
  )
}

