#-------------------------self-service password reset (security question)-----
# Replaces the old hardcoded "which year did you start at this lab?" question,
# which made no sense for external peer reviewers (leading_peer/co_peer) who
# don't work at any specific lab - this is why Apet's reset failed. A flexible,
# universally-answerable question set instead, matching the Wartungsplan app.

# Not available via any package already loaded here - defining it directly.
`%||%` <- function(a, b) if (is.null(a) || (length(a) == 1 && is.na(a))) b else a

SECURITY_QUESTIONS <- c(
  "Wann (Jahr) haben Sie in diesem Labor angefangen?" = "lab_start_year",
  "Wie hieÃŸ Ihr erstes Haustier?"             = "first_pet",
  "In welcher Stadt sind Sie geboren?"        = "birth_city",
  "Was ist der MÃ¤dchenname Ihrer Mutter?"     = "mother_maiden",
  "Wie hieÃŸ Ihre Grundschule?"                = "primary_school",
  "Wie hieÃŸ Ihr erster Arbeitgeber?"          = "first_employer",
  "Eigene Frage definieren â€¦"                 = "__custom__"
)

# Normalize a security answer before hashing/checking - lowercase, trim,
# collapse internal whitespace - so casing/spacing never causes a false
# mismatch (the exact-string comparison in the old system had no tolerance
# for this at all).
normalize_security_answer <- function(x) {
  x <- tolower(trimws(x %||% ""))
  gsub("\\s+", " ", x)
}

#-------------------------rich text formatting toolbar--------------------------
# Adds basic Bold / Underline / Bullet / Special-character buttons to any
# textAreaInput, using plain Markdown-lite syntax (**bold**, ++underline++,
# "- " bullets) - no external JS library or CDN dependency required.

richtext_js <- tags$script(HTML("

  // ======================== Auto-resizing textareas ========================
  // Applies to EVERY textarea in the app, not just ones with the formatting
  // toolbar. Grows the box to fit content, so nobody has to manually drag-
  // resize or scroll within a small fixed-height box.

  function autoResizeTextarea(el) {
    if (!el || el.tagName !== 'TEXTAREA') return;
    el.style.height = 'auto';
    el.style.height = (el.scrollHeight + 2) + 'px';
  }

  // Catches the user typing (works for every textarea, including ones
  // created after page load, since this listens at the document level
  // rather than on each individual element)
  document.addEventListener('input', function(e) {
    if (e.target && e.target.tagName === 'TEXTAREA') {
      autoResizeTextarea(e.target);
    }
  });

  // Catches Shiny's updateTextAreaInput() (e.g. restoring a saved draft) -
  // Shiny fires this event on the element whenever an update*Input() call
  // changes it, separately from a native 'input' event.
  $(document).on('shiny:updateinput', function(event) {
    if (event.target && event.target.tagName === 'TEXTAREA') {
      setTimeout(function() { autoResizeTextarea(event.target); }, 0);
    }
  });

  // Catches textareas that render already containing text (e.g. Lab Info
  // fields pre-filled from the database) - resizes them once as soon as
  // they appear in the DOM, including ones added later by Shiny's renderUI.
  var textareaResizeObserver = new MutationObserver(function(mutations) {
    mutations.forEach(function(mutation) {
      mutation.addedNodes.forEach(function(node) {
        if (node.nodeType !== 1) return;
        if (node.tagName === 'TEXTAREA') {
          autoResizeTextarea(node);
        }
        if (node.querySelectorAll) {
          node.querySelectorAll('textarea').forEach(autoResizeTextarea);
        }
      });
    });
  });
  textareaResizeObserver.observe(document.body, { childList: true, subtree: true });

  // âœ… FIXED: resize anything already on the page at load time. The old
  // version only listened for 'DOMContentLoaded', but by the time Shiny
  // injects this script that event has often ALREADY fired - meaning the
  // listener never runs at all. Check readyState first and run immediately
  // if the DOM is already loaded, only falling back to the event listener
  // if it's genuinely still loading.
  function resizeAllTextareas() {
    document.querySelectorAll('textarea').forEach(autoResizeTextarea);
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', resizeAllTextareas);
  } else {
    resizeAllTextareas();
  }

  // âœ… ADDED: textareas inside a tab that ISN'T currently active/visible
  // report an inaccurate scrollHeight while hidden (browsers can't measure
  // hidden elements correctly) - so they never get sized properly until
  // that tab is actually shown. Watch for a tab pane gaining the 'active'
  // class (how shinydashboard/Bootstrap tabs mark the visible one) and
  // re-resize every textarea inside it at that moment.
  var tabActiveObserver = new MutationObserver(function(mutations) {
    mutations.forEach(function(mutation) {
      if (mutation.attributeName === 'class' &&
          mutation.target.classList &&
          mutation.target.classList.contains('active')) {
        setTimeout(function() {
          mutation.target.querySelectorAll('textarea').forEach(autoResizeTextarea);
        }, 50);
      }
    });
  });
  tabActiveObserver.observe(document.body, {
    attributes: true,
    attributeFilter: ['class'],
    subtree: true
  });

  function wrapSelection(textareaId, before, after) {
    var ta = document.getElementById(textareaId);
    if (!ta) return;
    var start = ta.selectionStart;
    var end = ta.selectionEnd;
    var text = ta.value;
    var selected = text.substring(start, end);
    var newText = text.substring(0, start) + before + selected + after + text.substring(end);
    ta.value = newText;
    ta.focus();
    ta.selectionStart = start + before.length;
    ta.selectionEnd = start + before.length + selected.length;
    ta.dispatchEvent(new Event('input', { bubbles: true }));
  }

  function insertBulletLine(textareaId) {
    var ta = document.getElementById(textareaId);
    if (!ta) return;
    var start = ta.selectionStart;
    var end = ta.selectionEnd;
    var text = ta.value;
    
    if (start === end) {
      // No selection - just toggle bullet on the current line (original behavior)
      var lineStart = text.lastIndexOf('\\n', start - 1) + 1;
      var alreadyBullet = text.substring(lineStart, lineStart + 2) === '- ';
      var insertion = alreadyBullet ? '' : '- ';
      var newText = text.substring(0, lineStart) + insertion + text.substring(lineStart);
      ta.value = newText;
      var newPos = start + insertion.length;
      ta.focus();
      ta.selectionStart = newPos;
      ta.selectionEnd = newPos;
    } else {
      // âœ… FIXED: text is selected, possibly spanning multiple lines - turn
      // EACH selected line into its own bullet point, not just the first.
      var blockStart = text.lastIndexOf('\\n', start - 1) + 1;
      var blockEndIdx = text.indexOf('\\n', end);
      var blockEnd = blockEndIdx === -1 ? text.length : blockEndIdx;
      
      var block = text.substring(blockStart, blockEnd);
      var lines = block.split('\\n');
      
      // If EVERY non-empty line already starts with '- ', remove the bullets
      // (toggle off); otherwise add '- ' to every line that doesn't have it.
      var nonEmptyLines = lines.filter(function(l) { return l.length > 0; });
      var allBulleted = nonEmptyLines.length > 0 && nonEmptyLines.every(function(l) { return l.indexOf('- ') === 0; });
      
      var newLines = lines.map(function(l) {
        if (l.length === 0) return l;
        if (allBulleted) {
          return l.indexOf('- ') === 0 ? l.substring(2) : l;
        } else {
          return l.indexOf('- ') === 0 ? l : '- ' + l;
        }
      });
      
      var newBlock = newLines.join('\\n');
      var newText = text.substring(0, blockStart) + newBlock + text.substring(blockEnd);
      ta.value = newText;
      ta.focus();
      ta.selectionStart = blockStart;
      ta.selectionEnd = blockStart + newBlock.length;
    }
    
    ta.dispatchEvent(new Event('input', { bubbles: true }));
  }

  function insertAtCursor(textareaId, chr) {
    var ta = document.getElementById(textareaId);
    if (!ta) return;
    var start = ta.selectionStart;
    var end = ta.selectionEnd;
    var text = ta.value;
    var newText = text.substring(0, start) + chr + text.substring(end);
    ta.value = newText;
    var newPos = start + chr.length;
    ta.focus();
    ta.selectionStart = newPos;
    ta.selectionEnd = newPos;
    ta.dispatchEvent(new Event('input', { bubbles: true }));
  }

  function toggleCharPicker(pickerId) {
    var el = document.getElementById(pickerId);
    if (!el) return;
    el.style.display = (el.style.display === 'none' || el.style.display === '') ? 'flex' : 'none';
  }
"))

richtext_toolbar <- function(textarea_id) {
  picker_id <- paste0(textarea_id, "_charpicker")
  
  special_chars <- c(
    "%", "/", "-", "#", "_", "&", "@", "*", "+", "=",
    "Âµ", "Â°", "Â±", "â‰¤", "â‰¥", "â†’", "Ã—", "Â§",
    "Â²", "Â³", "Î±", "Î²", "Î³", "Î”",
    "Ã¤", "Ã¶", "Ã¼", "ÃŸ", "Ã„", "Ã–", "Ãœ",
    "â€ž", "\u201c", "â€¦"
  )
  
  # âœ… Blue, matching the app's existing #003B73 theme color, instead of
  # Bootstrap's default grey.
  btn_style <- "background-color: #003B73; color: white; border: 1px solid #003B73; padding: 2px 10px;"
  
  tagList(
    tags$div(
      style = "margin-bottom: 4px; display: flex; gap: 4px; align-items: center;",
      tags$button(
        type = "button",
        class = "btn btn-xs",
        style = paste0(btn_style, " font-weight: bold;"),
        title = "Fett (Bold)",
        onclick = sprintf("wrapSelection('%s', '**', '**')", textarea_id),
        "B"
      ),
      tags$button(
        type = "button",
        class = "btn btn-xs",
        style = paste0(btn_style, " text-decoration: underline;"),
        title = "Unterstrichen (Underline)",
        onclick = sprintf("wrapSelection('%s', '++', '++')", textarea_id),
        "U"
      ),
      tags$button(
        type = "button",
        class = "btn btn-xs",
        style = btn_style,
        title = "AufzÃ¤hlungspunkt (Bullet point)",
        onclick = sprintf("insertBulletLine('%s')", textarea_id),
        "â€¢  Liste"
      ),
      tags$button(
        type = "button",
        class = "btn btn-xs",
        style = btn_style,
        title = "Sonderzeichen (Special characters)",
        onclick = sprintf("toggleCharPicker('%s')", picker_id),
        "Î©  Zeichen"
      )
    ),
    tags$div(
      id = picker_id,
      style = "display: none; flex-wrap: wrap; gap: 3px; margin-bottom: 8px; padding: 6px; background: #e8f0f8; border: 1px solid #003B73; border-radius: 4px; max-width: 320px;",
      lapply(special_chars, function(ch) {
        tags$button(
          type = "button",
          class = "btn btn-xs",
          style = paste0(btn_style, " min-width: 28px;"),
          onclick = sprintf("insertAtCursor('%s', '%s')", textarea_id, ch),
          ch
        )
      })
    )
  )
}

#-------------------------rich text -> LaTeX conversion (for PDF reports)-------
# Converts the Markdown-lite syntax from richtext_toolbar() (**bold**,
# ++underline++, "- " bullets, and the special character picker) into safe
# LaTeX. Use this in place of manual gsub()-based escaping anywhere a
# free-text answer gets written into a PDF report - source this file (or
# copy this function) into each .Rmd template's setup chunk.
# NOTE: requires \usepackage{textcomp} in the Rmd's header-includes for
# \textmu{}, \textdegree{}, \textpm{}, \texttimes{} to compile.

format_richtext <- function(text) {
  if (is.null(text) || is.na(text) || !nzchar(trimws(text))) return("")
  
  special_char_map <- c(
    "Âµ" = "\\textmu{}",
    "Â°" = "\\textdegree{}",
    "Â±" = "\\textpm{}",
    "â‰¤" = "$\\leq$",
    "â‰¥" = "$\\geq$",
    "â†’" = "$\\rightarrow$",
    "Ã—" = "\\texttimes{}",
    "Â§" = "\\S{}",
    "Â²" = "\\textsuperscript{2}",
    "Â³" = "\\textsuperscript{3}"
  )
  
  escape_plain <- function(s) {
    special_placeholders <- character(0)
    for (i in seq_along(special_char_map)) {
      ch <- names(special_char_map)[i]
      placeholder <- paste0("\u0002SPEC", i, "\u0002")
      if (grepl(ch, s, fixed = TRUE)) {
        s <- gsub(ch, placeholder, s, fixed = TRUE)
        special_placeholders[placeholder] <- special_char_map[[ch]]
      }
    }
    s <- gsub("\\\\", "\\\\textbackslash{}", s)
    s <- gsub("([&%$#_{}])", "\\\\\\1", s)
    s <- gsub("~", "\\\\textasciitilde{}", s)
    s <- gsub("\\^", "\\\\textasciicircum{}", s)
    for (placeholder in names(special_placeholders)) {
      s <- gsub(placeholder, special_placeholders[[placeholder]], s, fixed = TRUE)
    }
    s
  }
  
  # âœ… FIXED: **bold** and ++underline++ spans that cross line breaks (e.g. a
  # span opened on line 1 and closed on line 5) used to silently fail, since
  # each line was checked in isolation for a matching pair of markers - a
  # line with only an opening or only a closing marker never matched.
  # This now tracks open/close state ACROSS lines: a span left open at the
  # end of a line is closed for that line and reopened at the start of the
  # next, so \textbf{}/\underline{} always stays validly balanced per line
  # (safe inside itemize/table contexts) while still visually continuing
  # the formatting across the whole span the user selected.
  bold_open <- FALSE
  underline_open <- FALSE
  
  process_line <- function(line) {
    out <- ""
    if (bold_open) out <- paste0(out, "\\textbf{")
    if (underline_open) out <- paste0(out, "\\underline{")
    
    remaining <- line
    repeat {
      pb <- regexpr("\\*\\*", remaining, fixed = FALSE)
      pu <- regexpr("\\+\\+", remaining, fixed = FALSE)
      pb_val <- if (pb > 0) pb else Inf
      pu_val <- if (pu > 0) pu else Inf
      
      if (is.infinite(pb_val) && is.infinite(pu_val)) {
        out <- paste0(out, escape_plain(remaining))
        break
      }
      
      if (pb_val <= pu_val) {
        out <- paste0(out, escape_plain(substr(remaining, 1, pb_val - 1)))
        if (!bold_open) {
          out <- paste0(out, "\\textbf{")
          bold_open <<- TRUE
        } else {
          out <- paste0(out, "}")
          bold_open <<- FALSE
        }
        remaining <- substring(remaining, pb_val + 2)
      } else {
        out <- paste0(out, escape_plain(substr(remaining, 1, pu_val - 1)))
        if (!underline_open) {
          out <- paste0(out, "\\underline{")
          underline_open <<- TRUE
        } else {
          out <- paste0(out, "}")
          underline_open <<- FALSE
        }
        remaining <- substring(remaining, pu_val + 2)
      }
    }
    
    if (underline_open) out <- paste0(out, "}")
    if (bold_open) out <- paste0(out, "}")
    
    out
  }
  
  lines <- strsplit(text, "\n")[[1]]
  out <- character(0)
  in_list <- FALSE
  for (ln in lines) {
    is_bullet <- grepl("^- ", ln)
    if (is_bullet && !in_list) {
      out <- c(out, "\\begin{itemize}")
      in_list <- TRUE
    }
    if (!is_bullet && in_list) {
      out <- c(out, "\\end{itemize}")
      in_list <- FALSE
    }
    if (is_bullet) {
      content <- sub("^- ", "", ln)
      out <- c(out, paste0("\\item ", process_line(content)))
    } else if (nzchar(trimws(ln))) {
      out <- c(out, process_line(ln))
    } else {
      out <- c(out, "")
    }
  }
  if (in_list) out <- c(out, "\\end{itemize}")
  
  paste(out, collapse = "\n\n")
}

