# richTextInput HELPER FUNCTION
richTextInput <- function(inputId,
                          label = NULL,
                          placeholder = "",
                          height = "300px") {
  div(
    if (!is.null(label)) {
      tags$label(label, style = "display: block; margin-bottom: 8px; font-weight: bold;")
    },
    
    # Just the editor - NO instructions here
    div(
      id = inputId,
      class = "summernote",
      style = sprintf(
        "
        min-height: %s;
        width: 100%%;
        border: 1px solid #ddd;
        border-radius: 4px;
        background-color: #ffffff;
      ",
        height
      ),
      placeholder
    ),
    
    # Simple initialization
    tags$script(
      sprintf(
        "
        console.log('Initializing: %s');

        // Wait for dependencies
        var maxAttempts = 50;
        var attempts = 0;

        function tryInit() {
          attempts++;

          if (typeof jQuery === 'undefined') {
            if (attempts < maxAttempts) {
              setTimeout(tryInit, 100);
            }
            return;
          }

          if (typeof jQuery.summernote === 'undefined') {
            if (attempts < maxAttempts) {
              setTimeout(tryInit, 100);
            }
            return;
          }

          try {
            var $editor = jQuery('#%s');

            // Check if already initialized
            if ($editor.data('summernote')) {
              console.log('âœ… Already initialized: %s');
              return;
            }

            $editor.summernote({
              height: %s,
              minHeight: 120,
              maxHeight: 400,
              focus: false,
              placeholder: '%s',
              tabsize: 2,
              toolbar: [
                ['style', ['style']],
                ['font', ['bold', 'italic', 'underline', 'strikethrough', 'clear']],
                ['fontsize', ['fontsize']],
                ['color', ['color']],
                ['para', ['ul', 'ol', 'paragraph']],
                ['table', ['table']],
                ['insert', ['link']],
                ['view', ['fullscreen', 'codeview']]
              ],
              callbacks: {
                onChange: function(contents, $editable) {
                  Shiny.setInputValue('%s', contents, {priority: 'event'});
                },
                onInit: function() {
                  console.log('âœ… Summernote ready: %s');
                  // Enable the editor
                  jQuery('#%s').summernote('enable');
                }
              }
            });

            console.log('âœ… Initialized successfully: %s');

          } catch(e) {
            console.error('âŒ Error initializing %s:', e);
          }
        }

        // Start trying to initialize
        if (document.readyState === 'loading') {
          document.addEventListener('DOMContentLoaded', tryInit);
        } else {
          tryInit();
        }
      ",
        inputId,
        inputId,
        inputId,
        height,
        placeholder,
        inputId,
        inputId,
        inputId,
        inputId
      )
    )
  )
}

#----------------------------------make_ui------------------------------------
make_ui <- function(question_list,
                    score_prefix = "Freitext",
                    text_prefix = "Freitext_text") {
  ui_elements <- lapply(question_list, function(q) {
    btn_id <- paste0("info_", q$id)
    text_input_id <- paste0(text_prefix, q$id)
    
    list(
      div(
        style = "margin-bottom: 25px;",
        tags$h5(
          style = "text-align: left; margin-bottom: 10px;",
          strong(paste0(q$number, ". ", q$label)),
          " ",
          bsButton(
            btn_id,
            label = "",
            icon = icon("info-circle"),
            style = "info",
            size = "extra-small"
          )
        ),
        radioButtons(
          paste0(score_prefix, q$id),
          label = NULL,
          choices = c("N/A", 1:5),
          selected = "N/A",
          inline = TRUE
        ),
        richtext_toolbar(text_input_id),
        textAreaInput(
          paste0(text_prefix, q$id),
          label = NULL,
          placeholder = "Text eingeben...",
          height = "300px",
          width = "100%"
        )
      ),
      bsPopover(
        id = btn_id,
        title = paste("Info zu Frage", q$number),
        content = q$info,
        placement = "right",
        trigger = "hover",
        options = list(container = "body")
      )
    )
  })
  
  do.call(tagList, unlist(ui_elements, recursive = FALSE))
}




