}

#--------------------------- Main UI Definition --------------------------------
ui <- dashboardPage(
  title = "Dashboard",
  header = dashboardHeader(title = "Peer Review", tags$li(
    class = "dropdown", actionLink("logout_button", "Logout", icon = icon("sign-out-alt"))
  )),
  sidebar = dashboardSidebar(
    minified = FALSE,
    collapsed = FALSE,
    uiOutput("sidebar_menu_ui")
  ),
  body = dashboardBody(
    shinyjs::useShinyjs(),
    
    use_theme(apptheme),
    
    richtext_js,
    
    # Global loading overlay - shows whenever Shiny is computing something,
    # including the delay between the sidebar appearing and the main
    # dashboard content finishing its (heavier) database queries right
    # after login. Uses Shiny's own built-in shiny:busy/shiny:idle events,
    # no extra package needed.
    tags$div(
      id = "global-loading-overlay",
      style = "display: none; position: fixed; top: 0; left: 0; width: 100%; height: 100%; background: rgba(255,255,255,0.7); z-index: 99999; align-items: center; justify-content: center;",
      tags$div(
        style = "text-align: center;",
        tags$div(
          style = "border: 6px solid #e0e0e0; border-top: 6px solid #003B73; border-radius: 50%; width: 50px; height: 50px; margin: 0 auto 12px auto; animation: global-spin 0.8s linear infinite;"
        ),
        tags$div(style = "color: #003B73; font-weight: 600;", "LÃ¤dt...")
      )
    ),
    tags$style(HTML("
      @keyframes global-spin { 0% { transform: rotate(0deg); } 100% { transform: rotate(360deg); } }
    ")),
    tags$script(HTML("
      // Debounced: only show the overlay if Shiny stays busy for more than
      // 400ms - this app has frequent background auto-save observers
      // running, which are quick and shouldn't trigger a full-page
      // overlay flash. Genuinely longer operations (like the dashboard's
      // queries right after login) will still show it.
      var globalLoadingTimer = null;
      $(document).on('shiny:busy', function() {
        globalLoadingTimer = setTimeout(function() {
          document.getElementById('global-loading-overlay').style.display = 'flex';
        }, 400);
      });
      $(document).on('shiny:idle', function() {
        clearTimeout(globalLoadingTimer);
        document.getElementById('global-loading-overlay').style.display = 'none';
      });
    ")),
    
    tags$head(tags$style(
      HTML(
        "
        h1, h2, h3, h4, h5, h6, .question-title, .section-title, strong {
