  /* Plot column styling */
  .dashboard-col-plot {
    text-align: center;
    padding: 5px !important;
    padding-top: 40px !important;
  }

  .plot-container {
    width: 100%;
    height: auto;
    margin-top: 30px;
  }

  /* Tables container */
  .berufsgruppe-tables-container {
    margin-bottom: 40px;
  }

  /* Dashboard wrapper */
  .dashboard-wrapper {
    background: white;
    border-radius: 6px;
    box-shadow: 0 1px 3px rgba(0,59,115,0.1);
    padding: 16px;
    margin: 16px 0;
    overflow-x: auto;
  }

  /* Table styling */
  .dashboard-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 13px;
  }

  .dashboard-table thead {
    background: #003B73;
    color: white;
    position: sticky;
    top: 0;
    z-index: 10;
  }

  .dashboard-table th {
    padding: 10px 8px;
    font-weight: 600;
    text-align: left;
    font-size: 13px;
    border: 1px solid #0056a6;
    color: white;
  }

  /* Column widths - UPDATED for 3 columns */
  .dashboard-col-question {
    width: 45%;
    min-width: 250px;
  }

  .dashboard-col-selbst {
    width: 25%;
    min-width: 150px;
  }

  .dashboard-col-plot {
    width: 30%;
    min-width: 200px;
  }

  /* Row styling */
  .dashboard-row {
    border-bottom: 1px solid #e9ecef;
    transition: background-color 0.15s;
  }

  .dashboard-row:hover {
    background-color: #f8f9fa;
  }

  .dashboard-table td {
    padding: 10px 8px;
    vertical-align: top;
    border: 1px solid #dee2e6;
  }

  /* Question column */
  .dashboard-col-question {
    font-size: 13px;
    line-height: 1.4;
    color: #212529;
  }

  .dashboard-col-question strong {
    color: #003B73;
    font-size: 13px;
  }

  /* Rating badges */
  .rating-inline {
    display: inline-flex;
    gap: 4px;
    align-items: center;
    flex-wrap: wrap;
  }

  .rating-active {
    background: #003B73;
    color: white;
    font-weight: 600;
    padding: 4px 7px;
    border-radius: 4px;
    font-size: 11px;
    display: inline-block;
    min-width: 28px;
    text-align: center;
    position: relative;
  }

  .rating-with-count {
    padding-right: 16px;
  }

  .rating-count {
    position: absolute;
    top: -6px;
    right: -2px;
    font-size: 9px;
    color: #003B73;
    font-weight: 700;
    background: #c6dbef;
    padding: 1px 3px;
    border-radius: 6px;
    line-height: 1;
  }

  /* Text responses */
  .selbst-text-container {
    margin-top: 8px;
  }

  .selbst-text-item {
    padding: 6px 10px;
    margin-bottom: 6px;
    background: #f8f9fa;
    border-left: 3px solid #003B73;
    border-radius: 0 4px 4px 0;
    font-size: 12px;
    line-height: 1.5;
    color: #495057;
    word-wrap: break-word;
  }

  .selbst-text-item .fa {
    color: #003B73;
    margin-right: 6px;
    font-size: 10px;
  }

  .no-data {
    color: #adb5bd;
    font-style: italic;
    font-size: 12px;
  }

  /* Tab styling */
  .nav-tabs {
    border-bottom: 2px solid #dee2e6;
    margin-bottom: 0;
  }

  .nav-tabs > li > a {
    color: #495057;
    font-weight: 500;
    border: none;
    border-bottom: 3px solid transparent;
    padding: 10px 20px;
    font-size: 14px;
    transition: all 0.15s;
  }

  .nav-tabs > li > a:hover {
    background-color: #f8f9fa;
    border-bottom-color: #003B73;
  }

  .nav-tabs > li.active > a {
    color: #003B73;
    border-bottom-color: #003B73;
    background-color: white;
    font-weight: 600;
  }
"
