#---------------------------- Server Logic -----------------------------------

server <- function(input, output, session) {
  
  options(
    shiny.error = function() {
      cat(rlang::last_trace())
    }
  )
  
  UPLOAD_DIR <- if (dir.exists("/home/shiny/uploads/organigramm")) {
    "/home/shiny/uploads/organigramm"  # server
  } else {
    file.path(getwd(), "uploads", "organigramm")               # local
  }
  
  if (!dir.exists(UPLOAD_DIR))
    dir.create(UPLOAD_DIR, recursive = TRUE)
  message("UPLOAD_DIR set to: ", UPLOAD_DIR)
  
  
  # In your server function, limit upload size to 10MB
  options(shiny.maxRequestSize = 10 * 1024^2)
  
  # NOTE: must_reset_trigger is defined once, later in this file (as
  # reactiveVal(0)) - removed a dead, earlier duplicate definition that
  # used to sit here (reactiveVal(FALSE)) and was silently overridden by
  # the later one anyway, same class of duplicate-definition issue found
  # several other places in this file.
  
  # Core session state (define ONCE, at the top!)
  user_logged_in <- reactiveVal(FALSE)
  user_id <- reactiveVal(NULL)
  user_role <- reactiveVal(NULL)
  current_username <- reactiveVal(NULL)
  current_project_id <- reactiveVal(NULL)
  current_project_name <- reactiveVal(NULL)
  current_submission_id <- reactiveVal(NULL)
  redeemed_code_info <- reactiveVal(NULL)
  project_data_changed <- reactiveVal(0)
  responses_data_changed <- reactiveVal(0)
  invitation_data_changed <- reactiveVal(0)
  project_title_val <- reactiveVal("")
  consent_given <- reactiveVal(FALSE)
  
  draft_loaded <- reactiveVal(FALSE)
  fragebogen_ui_ready <- reactiveVal(FALSE)
  last_tab <- reactiveVal(NULL)
  
  
  loading_active <- reactiveVal(FALSE)
  
  labinfo_answers_changed           <- reactiveVal(FALSE)
  labinfo_answers_changed_debounced <- debounce(labinfo_answers_changed, 3000)
  labinfo_auto_save_status          <- reactiveVal("Unsaved changes")
  
  qn_answers_changed           <- reactiveVal(FALSE)
  qn_answers_changed_debounced <- debounce(qn_answers_changed, 3000)
  qn_auto_save_status          <- reactiveVal("Unsaved changes")
  
  # âœ… ADDED: server-side-only marker, set TRUE the instant labinfo_form_ui
  # genuinely renders in this session - see the note at that renderUI for why.
  labinfo_ui_rendered <- reactiveVal(FALSE)
  
  labinfo_field_ids <- c(
    "name", "Internetadresse", "Trag", "Zug", "Ansprechpartner",
    "Email", "Telefonnummer", "Ã–ffnungzeiten",
    "versorgung", "sonstiges_versorgung",
    "laborbereiche", "sonstiges_laborbereiche",
    "leistungsspektrum", "sonstiges_leistungsspektrum",
    "ausstattung", "hauptlieferanten",
    "question_binary_1", "farbcodesystem", "question_binary_2",
    "auftragsgenerierung", "prÃ¤analytik", "befundÃ¼bermittlung",
    "beratungsleistungen", "question_binary_3",
    "Anzahl_total", "Anzahl_mit", "davon_Fachaerzte", "davon_weiterbildung",
    "Anzahl_Planstellen", "davon_unbesetzt",
    "Anzahl_tech", "Anzahl_TPlanstellen", "davon_Tunbesetzt",
    "Anzahl_natur", "Anzahl_NPlanstellen", "davon_Nunbesetzt",
    "Anzahl_IT", "Anzahl_IPlanstellen", "davon_Iunbesetzt",
    "Beschreibung", "WeitereInfo",
    "AnbieterInfo", "AnbieterOrder", "AnbieterMiddleware", "WeitereIT",
    "laufendenJahres", "Vorjahres", "Kompetenzschwerpunkte", "ErgÃ¤nzung"
  )
  
  
  observe({
    req(!loading_active())               # don't fire while the draft is still being restored
    req(!is.null(input$Berufsgruppe))    # only proceed once the questionnaire UI has rendered
    
    ids <- tryCatch(get_all_question_ids(), error = function(e) character(0))
    for (id in ids) {
      input[[id]]
    }
    
    isolate({
      if (!isTRUE(loading_active())) {
        qn_answers_changed(TRUE)
      }
    })
  }, priority = 1000)
  
  observe({
    qn_answers_changed_debounced()
    
    req(user_logged_in())
    req(current_project_id())
    req(isTRUE(qn_answers_changed()))   # âœ… FIXED: same bug as Lab Info's Observer 2 - this ran unconditionally on its own first flush, regardless of whether anything actually changed.
    
    if (is_demo_mode()) {
      qn_answers_changed(FALSE)
      return()
    }
    
    tryCatch({
      message("â†’ Auto-saving Questionnaire (Selbstbewertung) responses...")
      qn_auto_save_status("Saving...")
      
      success <- save_draft_to_db(status = "paused", show_notification = FALSE)
      
      qn_answers_changed(FALSE)
      
      if (isTRUE(success)) {
        qn_auto_save_status(paste("Gespeichert um", format(Sys.time(), "%H:%M:%S")))
      }
      
    }, error = function(e) {
      message("Questionnaire auto-save error: ", e$message)
      qn_answers_changed(FALSE)
    })
    
  }, priority = 900)
  
  output$qn_auto_save_status_ui <- renderUI({
    status <- qn_auto_save_status()
    if (grepl("Gespeichert um", status)) {
      div(style = "position: fixed; bottom: 20px; right: 20px; padding: 10px 15px; background-color: #d4edda; color: #155724; border: 1px solid #c3e6cb; border-radius: 4px; font-size: 12px; z-index: 999;",
          icon("check-circle", style = "margin-right: 5px;"), status)
    } else if (grepl("Saving", status)) {
      div(style = "position: fixed; bottom: 20px; right: 20px; padding: 10px 15px; background-color: #fff3cd; color: #856404; border: 1px solid #ffeaa7; border-radius: 4px; font-size: 12px; z-index: 999;",
          icon("hourglass", style = "margin-right: 5px;"), "Speichere...")
    }
  })
  
  
  
  observe({
    req(isTRUE(labinfo_ui_rendered()))   
    for (id in labinfo_field_ids) {
      input[[id]]
    }
    if (!is.null(anmerkungen$counter)) {
      for (i in seq_len(anmerkungen$counter)) {
        input[[paste0("Beschreibung", i)]]
        input[[paste0("Anmerkung", i)]]
      }
    }
    
    isolate({
      labinfo_answers_changed(TRUE)
    })
  }, priority = 1000)
  
  observe({
    labinfo_answers_changed_debounced()
    
    req(user_logged_in())
    req(current_project_id())
    req(isTRUE(labinfo_answers_changed()))   # âœ… FIXED: this observer previously ran unconditionally on its own first flush (a standard Shiny observe() behavior) regardless of whether anything actually changed - firing at login, before the Lab Info tab was ever visited, and saving blank input values over real data. Now it only proceeds when a real change was actually marked.
    
    if (is_demo_mode()) {
      labinfo_answers_changed(FALSE)
      return()
    }
    
    tryCatch({
      message("â†’ Auto-saving Lab Info data...")
      labinfo_auto_save_status("Saving...")
      
      success <- save_lab_info_data()
      
      labinfo_answers_changed(FALSE)
      
      if (isTRUE(success)) {
        labinfo_auto_save_status(paste("Gespeichert um", format(Sys.time(), "%H:%M:%S")))
      }
      
    }, error = function(e) {
      message("Lab Info auto-save error: ", e$message)
      labinfo_answers_changed(FALSE)
    })
    
  }, priority = 900)
  
  output$labinfo_auto_save_status_ui <- renderUI({
    status <- labinfo_auto_save_status()
    if (grepl("Gespeichert um", status)) {
      div(style = "position: fixed; bottom: 20px; right: 20px; padding: 10px 15px; background-color: #d4edda; color: #155724; border: 1px solid #c3e6cb; border-radius: 4px; font-size: 12px; z-index: 999;",
          icon("check-circle", style = "margin-right: 5px;"), status)
    } else if (grepl("Saving", status)) {
      div(style = "position: fixed; bottom: 20px; right: 20px; padding: 10px 15px; background-color: #fff3cd; color: #856404; border: 1px solid #ffeaa7; border-radius: 4px; font-size: 12px; z-index: 999;",
          icon("hourglass", style = "margin-right: 5px;"), "Speichere...")
    }
  })
  
  output$userRole <- reactive({
    user_role()
  })
  outputOptions(output, "userRole", suspendWhenHidden = FALSE)
  output$isAdmin <- reactive({
    user_role() == "admin"
  })
  output$isLeiter <- reactive({
    user_role() == "laborleitung"
  })
  output$isLeadingPeer <- reactive({
    user_role() == "leading_peer"
  })
  output$isColleague <- reactive({
    user_role() == "colleague"
  })
  output$isCoPeer <- reactive({
    user_role() == "co_peer"
  })
  outputOptions(output, "isAdmin", suspendWhenHidden = FALSE)
  outputOptions(output, "isLeiter", suspendWhenHidden = FALSE)
  outputOptions(output, "isLeadingPeer", suspendWhenHidden = FALSE)
  outputOptions(output, "isColleague", suspendWhenHidden = FALSE)
  outputOptions(output, "isCoPeer", suspendWhenHidden = FALSE)
  
  is_co_peer <- reactive({
    user_role() == "co_peer"
  })
  
  is_leading_peer <- function() {
    !is.null(user_role()) && user_role() == "leading_peer"
  }
  
  # Logout function 
  do_logout <- function() {
    if (isTRUE(user_logged_in()) && !is.null(current_username())) {
      tryCatch({
        con <- get_db_con()
        on.exit(DBI::dbDisconnect(con), add = TRUE)
        log_event(con, "abmeldung", entity_type = "benutzer", entity_id = current_username(),
                  who = current_username(), role = user_role(), session_id = session$token)
      }, error = function(e) NULL)
    }

    user_logged_in(FALSE)
    user_id(NULL)
    user_role(NULL)
    current_username(NULL)
    current_project_id(NULL)
    current_submission_id(NULL)
    redeemed_code_info(NULL)
    session$userData$user_id <- NULL
    session$userData$username <- NULL
    session$userData$invitation_code <- NULL
    
    draft_loaded(FALSE)
    loading_active(FALSE)
    labinfo_answers_changed(FALSE)
    labinfo_ui_rendered(FALSE)
    
    
    showNotification("Erfolgreich abgemeldet.", type = "message")
    updateTabItems(session, "sidebar_menu", selected = "start")
  }
  
  
  
  # Helper functions
  safe_equal <- function(a, b) {
    if (is.na(a) || is.na(b))
      return(FALSE)
    isTRUE(a == b)
  }
  
  force_reset_db <- function(con, username) {
    DBI::dbExecute(con,
                   "UPDATE users SET must_reset = TRUE WHERE username = $1",
                   params = list(username))
  }
  
  # demo-mode reactive flag
  is_demo_mode <- reactive({
    user_logged_in() &&
      identical(user_role(), "power_user") &&
      identical(input$poweruser_tabs, "Demo-Selbstbewertung")
  })
  
  
  #------------------------ FREMDBEWERTUNG ADMIN -------------------------------
  
  # Load projects for dropdown
  observe({
    req(user_logged_in())
    req(user_role() == "admin")
    
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con))
    
    projects <- DBI::dbGetQuery(con,
                                "
    SELECT id, title FROM projects
    WHERE status = 'active'
    ORDER BY created_at DESC
  ")
    
    choices <- setNames(projects$id, projects$title)
    
    updateSelectInput(session, "admin_fremd_project", choices = choices)
  })
  
  # Load reviewers for filter
  observe({
    req(input$admin_fremd_project)
    
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con))
    
    reviewers <- DBI::dbGetQuery(
      con,
      "
    SELECT DISTINCT u.username
    FROM responses r
    JOIN users u ON u.id = r.user_id
    WHERE r.project_id::text = $1::text
      AND r.assessment_type = 'fremdbewertung'
    ORDER BY u.username
  ",
      params = list(as.character(input$admin_fremd_project))
    )
    
    choices <- c("Alle" = "",
                 setNames(reviewers$username, reviewers$username))
    
    updateSelectInput(session, "admin_fremd_filter_user", choices = choices)
  })
  
  # Summary statistics
  output$fremdbewertung_summary <- renderUI({
    req(input$admin_fremd_project)
    
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con))
    
    # Count submissions
    stats <- DBI::dbGetQuery(
      con,
      "
    SELECT
      COUNT(DISTINCT r.user_id) as total_reviewers,
      COUNT(DISTINCT r.submission_id) as total_submissions,
      COUNT(*) as total_responses,
      MIN(r.created_at) as first_submission,
      MAX(r.created_at) as last_submission
    FROM responses r
    WHERE r.project_id::text = $1::text
      AND r.assessment_type = 'fremdbewertung'
  ",
      params = list(as.character(input$admin_fremd_project))
    )
    
    # Get reviewer details
    reviewers <- DBI::dbGetQuery(
      con,
      "
    SELECT DISTINCT
      u.username,
      u.role,
      COUNT(r.question_id) as answer_count,
      MAX(r.created_at) as submitted_at
    FROM responses r
    JOIN users u ON u.id = r.user_id
    WHERE r.project_id::text = $1::text
      AND r.assessment_type = 'fremdbewertung'
    GROUP BY u.username, u.role
    ORDER BY submitted_at DESC
  ",
      params = list(as.character(input$admin_fremd_project))
    )
    
    tagList(fluidRow(
      column(
        3,
        div(
          class = "info-box bg-aqua",
          style = "padding: 15px; border-radius: 5px; color: white; background: #00c0ef;",
          div(style = "font-size: 14px; font-weight: 600;", "Anzahl Reviewer"),
          div(style = "font-size: 32px; font-weight: bold; margin-top: 5px;", stats$total_reviewers)
        )
      ),
      column(
        3,
        div(
          class = "info-box bg-green",
          style = "padding: 15px; border-radius: 5px; color: white; background: #00a65a;",
          div(style = "font-size: 14px; font-weight: 600;", "Eingereichte Bewertungen"),
          div(style = "font-size: 32px; font-weight: bold; margin-top: 5px;", stats$total_submissions)
        )
      ),
      column(
        3,
        div(
          class = "info-box bg-yellow",
          style = "padding: 15px; border-radius: 5px; color: white; background: #f39c12;",
          div(style = "font-size: 14px; font-weight: 600;", "Gesamte Antworten"),
          div(style = "font-size: 32px; font-weight: bold; margin-top: 5px;", stats$total_responses)
        )
      ),
      column(
        3,
        div(
          class = "info-box bg-red",
          style = "padding: 15px; border-radius: 5px; color: white; background: #dd4b39;",
          div(style = "font-size: 14px; font-weight: 600;", "Letzte Einreichung"),
          div(style = "font-size: 16px; font-weight: bold; margin-top: 10px;", if (!is.na(stats$last_submission)) {
            format(as.POSIXct(stats$last_submission), "%d.%m.%Y %H:%M")
          } else {
            "â€”"
          })
        )
      )
    ), br(), if (nrow(reviewers) > 0) {
      tagList(
        h5(icon("users"), " Reviewer Details:"),
        tags$table(
          class = "table table-striped table-condensed",
          style = "font-size: 13px;",
          tags$thead(tags$tr(
            tags$th("Reviewer"),
            tags$th("Rolle"),
            tags$th("Anzahl Antworten"),
            tags$th("Eingereicht am")
          )),
          tags$tbody(lapply(1:nrow(reviewers), function(i) {
            tags$tr(
              tags$td(tags$strong(reviewers$username[i])),
              tags$td(
                tags$span(
                  class = if (reviewers$role[i] == "leading_peer")
                    "label label-primary"
                  else
                    "label label-info",
                  if (reviewers$role[i] == "leading_peer")
                    "Leading Peer"
                  else
                    "Co-Peer"
                )
              ),
              tags$td(reviewers$answer_count[i]),
              tags$td(format(
                as.POSIXct(reviewers$submitted_at[i]),
                "%d.%m.%Y %H:%M"
              ))
            )
          }))
        )
      )
    })
  })
  
  # Detailed table (reactive data)
  fremdbewertung_data <- reactive({
    req(input$admin_fremd_project)
    
    # Trigger refresh
    input$admin_fremd_refresh
    
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con))
    
    # Build query with filters
    query <- "
    SELECT
      u.username as Reviewer,
      u.role as Rolle,
      r.question_id as Frage_ID,
      r.response_value as Bewertung,
      r.text_value as Kommentar,
      r.created_at as Eingereicht_am,
      r.submission_id
    FROM responses r
    JOIN users u ON u.id = r.user_id
    WHERE r.project_id::text = $1::text
      AND r.assessment_type = 'fremdbewertung'
  "
    
    params <- list(as.character(input$admin_fremd_project))
    
    # Add user filter
    if (!is.null(input$admin_fremd_filter_user) &&
        input$admin_fremd_filter_user != "") {
      query <- paste(query, "AND u.username = $2")
      params <- c(params, list(input$admin_fremd_filter_user))
    }
    
    # Add section filter
    if (!is.null(input$admin_fremd_filter_section) &&
        input$admin_fremd_filter_section != "") {
      if (length(params) == 1) {
        query <- paste(query, "AND r.question_id LIKE $2")
        params <- c(params, list(paste0(
          input$admin_fremd_filter_section, "%"
        )))
      } else {
        query <- paste(query, "AND r.question_id LIKE $3")
        params <- c(params, list(paste0(
          input$admin_fremd_filter_section, "%"
        )))
      }
    }
    
    query <- paste(query, "ORDER BY r.created_at DESC, r.question_id")
    
    responses <- DBI::dbGetQuery(con, query, params = params)
    
    if (nrow(responses) > 0) {
      responses$Eingereicht_am <- format(as.POSIXct(responses$Eingereicht_am), "%d.%m.%Y %H:%M")
      
      # Translate roles
      responses$Rolle <- ifelse(responses$Rolle == "leading_peer",
                                "Leading Peer",
                                "Co-Peer")
      
      # Add section column
      responses$Bereich <- substr(responses$Frage_ID, 1, 1)
      responses$Bereich <- factor(
        responses$Bereich,
        levels = c("F", "M", "P", "E", "Q"),
        labels = c(
          "FÃ¼hrung",
          "Mitarbeitende",
          "Patienten",
          "Einsender",
          "QualitÃ¤t"
        )
      )
      
      # Reorder columns
      responses <- responses[, c(
        "Reviewer",
        "Rolle",
        "Bereich",
        "Frage_ID",
        "Bewertung",
        "Kommentar",
        "Eingereicht_am"
      )]
    }
    
    responses
  })
  
  # Render data table
  output$fremdbewertung_table <- DT::renderDataTable({
    data <- fremdbewertung_data()
    
    DT::datatable(
      data,
      options = list(
        pageLength = 25,
        order = list(list(6, 'desc')),
        # Sort by date descending
        scrollX = TRUE,
        columnDefs = list(
          list(width = '120px', targets = 0),
          # Reviewer
          list(width = '100px', targets = 1),
          # Rolle
          list(width = '100px', targets = 2),
          # Bereich
          list(width = '80px', targets = 3),
          # Frage_ID
          list(width = '80px', targets = 4),
          # Bewertung
          list(width = '300px', targets = 5),
          # Kommentar
          list(width = '130px', targets = 6)   # Eingereicht_am
        )
      ),
      rownames = FALSE,
      filter = "top",
      class = 'cell-border stripe compact',
      escape = FALSE
    ) %>%
      DT::formatStyle('Bewertung', backgroundColor = DT::styleInterval(c(2, 3, 4), c(
        '#ffcccc', '#ffffcc', '#ccffcc', '#99ff99'
      )))
  })
  
  # Download CSV
  output$download_fremdbewertung_csv <- downloadHandler(
    filename = function() {
      paste0("Fremdbewertung_",
             input$admin_fremd_project,
             "_",
             Sys.Date(),
             ".csv")
    },
    content = function(file) {
      data <- fremdbewertung_data()
      write.csv(data, file, row.names = FALSE, fileEncoding = "UTF-8")
    }
  )
  
  
  #----------------------------- POWER USER SERVER LOGIC------------------------
  
  # ========== POWER USER DASHBOARD ==========
  
  # Reactive output for user role
  output$user_role <- reactive({
    user_role()
  })
  outputOptions(output, "user_role", suspendWhenHidden = FALSE)
  
  # Power User Server Logic
  observeEvent(user_role(), {
    if (!is.null(user_role()) && user_role() == "power_user") {
      con <- get_db_con()
      
      # Add REFRESH TRIGGER
      projects_refresh <- reactiveVal(0)
      codes_refresh <- reactiveVal(0)
      
      # ========== LOAD DATA ==========
      
      get_all_projects <- reactive({
        projects_refresh()  # Trigger refresh
        
        projects <- DBI::dbGetQuery(
          con,
          "
        SELECT
          id,
          title,
          TO_CHAR(created_at AT TIME ZONE 'Europe/Berlin', 'DD.MM.YYYY HH24:MI') as created_at,
          (SELECT COUNT(*) FROM users WHERE project_id = projects.id) as user_count
        FROM projects
        ORDER BY created_at DESC
      "
        )
        
        return(projects)
      })
      
      get_all_users <- reactive({
        req(input$poweruser_filter_project,
            input$poweruser_filter_role)
        
        query <- "
        SELECT
          u.id,
          'User-' || u.id as user_id,
          u.username,
          u.role,
          p.title as project,
          TO_CHAR(u.registered_at AT TIME ZONE 'Europe/Berlin', 'DD.MM.YYYY HH24:MI') as registered_at,
          CASE
            WHEN r.user_id IS NULL THEN 'Nein'
            ELSE 'Ja'
          END as completed
        FROM users u
        LEFT JOIN projects p ON p.id = u.project_id
        LEFT JOIN (
          SELECT DISTINCT user_id
          FROM responses
          WHERE submission_id IS NOT NULL
        ) r ON r.user_id = u.id
        WHERE u.role NOT IN ('admin', 'power_user')
      "
        
        params <- list()
        
        if (input$poweruser_filter_project != "") {
          query <- paste0(query, " AND u.project_id = $1")
          params <- list(as.integer(input$poweruser_filter_project))
        }
        
        if (input$poweruser_filter_role != "") {
          if (length(params) > 0) {
            query <- paste0(query, " AND u.role = $2")
            params <- c(params, list(input$poweruser_filter_role))
          } else {
            query <- paste0(query, " AND u.role = $1")
            params <- list(input$poweruser_filter_role)
          }
        }
        
        query <- paste0(query, " ORDER BY u.registered_at DESC")
        
        if (length(params) > 0) {
          DBI::dbGetQuery(con, query, params = params)
        } else {
          DBI::dbGetQuery(con, query)
        }
      })
      
      get_invitation_codes <- reactive({
        codes_refresh()
        
        DBI::dbGetQuery(
          con,
          "
    SELECT
      ic.code,
      p.title as project,
      ic.role,
      ic.assessment_type,
      CASE
        WHEN ic.used_at IS NOT NULL THEN 'Ja'
        ELSE 'Nein'
      END as used,
      TO_CHAR(ic.generated_at AT TIME ZONE 'Europe/Berlin', 'DD.MM.YYYY HH24:MI') as created_at,
      TO_CHAR(ic.used_at AT TIME ZONE 'Europe/Berlin', 'DD.MM.YYYY HH24:MI') as used_at
    FROM invitation_codes ic
    LEFT JOIN projects p ON p.id = ic.project_id
    ORDER BY ic.generated_at DESC
  "
        )
      })
      
      # ========== POPULATE DROPDOWNS ==========
      
      observe({
        projects <- get_all_projects()
        
        choices <- setNames(projects$id, projects$title)
        choices_with_all <- c("Alle" = "", choices)
        
        updateSelectInput(session,
                          "poweruser_selbst_summary_project_selector",
                          choices = choices)
        updateSelectInput(session, "poweruser_filter_project", choices = choices_with_all)
        updateSelectInput(session, "poweruser_invite_project", choices = choices)
        updateSelectInput(session, "poweruser_report_project", choices = choices)
      })
      
      # ========== TABLES ==========
      
      output$poweruser_projects_table <- renderDT({
        projects <- get_all_projects()
        
        datatable(
          projects,
          colnames = c("ID", "Projekttitel", "Erstellt am", "Anzahl Benutzer"),
          options = list(pageLength = 25, order = list(list(2, 'desc'))),
          rownames = FALSE
        )
      })
      
      observeEvent(input$poweruser_refresh_projects, {
        projects_refresh(projects_refresh() + 1)
        showNotification("Projekte aktualisiert", type = "message")
      })
      
      output$poweruser_users_table <- renderDT({
        users <- get_all_users()
        
        # Remove username column for privacy (like admin does)
        display_cols <- c("user_id",
                          "role",
                          "project",
                          "completed",
                          "registered_at")
        
        datatable(
          users[, display_cols],
          colnames = c(
            "Benutzer-ID",
            "Rolle",
            "Projekt",
            "Abgeschlossen",
            "Registriert am"
          ),
          options = list(pageLength = 25, order = list(list(4, 'desc'))),
          rownames = FALSE
        )
      })
      
      output$poweruser_codes_table <- renderDT({
        codes <- get_invitation_codes()
        
        datatable(
          codes,
          colnames = c(
            "Code",
            "Projekt",
            "Rolle",
            "Assessment-Typ",
            "Verwendet",
            "Erstellt am",
            "Verwendet am"
          ),
          options = list(pageLength = 25, order = list(list(5, 'desc'))),
          rownames = FALSE
        )
      })
      
      observeEvent(input$poweruser_refresh_codes, {
        codes_refresh(codes_refresh() + 1)
        showNotification("Codes aktualisiert", type = "message")
      })
      
      # ========== CREATE PROJECT ==========
      
      observeEvent(input$poweruser_create_project_button, {
        if (is.null(input$poweruser_project_name) ||
            trimws(input$poweruser_project_name) == "") {
          output$poweruser_project_creation_status <- renderUI({
            div(
              class = "alert alert-danger",
              style = "margin-top: 15px;",
              icon("exclamation-circle"),
              strong(" Fehler: "),
              "Bitte geben Sie einen Projektnamen ein."
            )
          })
          return()
        }
        
        project_title <- trimws(input$poweruser_project_name)
        
        # Show loading
        output$poweruser_project_creation_status <- renderUI({
          div(
            class = "alert alert-info",
            style = "margin-top: 15px;",
            icon("spinner", class = "fa-spin"),
            " Projekt wird erstellt..."
          )
        })
        
        tryCatch({
          new_project <- DBI::dbGetQuery(
            con,
            "INSERT INTO projects (title, einrichtung, description, zeitraum, created_at, owner_id, status)
           VALUES ($1, $2, $3, $4, NOW(), $5, 'active')
           RETURNING id, title",
            params = list(
              project_title,
              if (is.null(input$poweruser_einrichtung_create) ||
                  trimws(input$poweruser_einrichtung_create) == "")
                NA
              else
                trimws(input$poweruser_einrichtung_create),
              if (is.null(input$poweruser_project_description) ||
                  trimws(input$poweruser_project_description) == "")
                NA
              else
                trimws(input$poweruser_project_description),
              if (is.null(input$poweruser_zeitraum) ||
                  trimws(input$poweruser_zeitraum) == "")
                NA
              else
                trimws(input$poweruser_zeitraum),
              user_id()
            )
          )
          
          if (nrow(new_project) > 0) {
            new_id <- as.character(new_project$id[1])
            new_title <- new_project$title[1]
            
            
            projects_refresh(projects_refresh() + 1)
            
            output$poweruser_project_creation_status <- renderUI({
              div(
                class = "alert alert-success",
                style = "margin-top: 15px;",
                icon("check-circle"),
                strong(" Erfolg! "),
                sprintf("Projekt '%s' wurde erstellt.", new_title)
              )
            })
            
            showNotification(
              paste0("âœ“ Projekt '", new_title, "' erstellt!"),
              type = "message",
              duration = 5
            )
            
            # Clear form
            updateTextInput(session, "poweruser_project_name", value = "")
            updateTextInput(session, "poweruser_einrichtung_create", value = "")
            updateTextAreaInput(session, "poweruser_project_description", value = "")
            updateTextInput(session, "poweruser_zeitraum", value = "")
          }
          
        }, error = function(e) {
          output$poweruser_project_creation_status <- renderUI({
            div(
              class = "alert alert-danger",
              style = "margin-top: 15px;",
              icon("exclamation-triangle"),
              strong(" Fehler: "),
              e$message
            )
          })
        })
      })
      
      # ========== AUTO-SELECT ASSESSMENT TYPE BASED ON ROLE ==========
      
      observeEvent(input$poweruser_invite_role, {
        # Auto-select assessment type based on role
        if (input$poweruser_invite_role %in% c("laborleitung", "colleague")) {
          updateSelectInput(session, "poweruser_code_type", selected = "selbstbewertung")
        } else if (input$poweruser_invite_role %in% c("leading_peer", "co_peer")) {
          updateSelectInput(session, "poweruser_code_type", selected = "fremdbewertung")
        }
      })
      
      # ========== GENERATE CODES ==========
      
      observeEvent(input$poweruser_generate_codes, {
        req(
          input$poweruser_invite_project,
          input$poweruser_invite_role,
          input$poweruser_invite_count,
          input$poweruser_code_type
        )
        
        num_codes <- input$poweruser_invite_count
        code_type <- input$poweruser_code_type
        invite_role <- input$poweruser_invite_role
        project_id <- as.integer(input$poweruser_invite_project)
        
        if (num_codes <= 0) {
          output$poweruser_code_generation_status <- renderUI(
            div(
              style = "padding: 10px; background-color: #f8d7da; border: 1px solid #f5c6cb; border-radius: 4px; margin-top: 15px;",
              icon("exclamation-triangle", style = "color: #721c24;"),
              tags$span(style = "margin-left: 8px; color: #721c24;", "Bitte geben Sie eine positive Anzahl ein.")
            )
          )
          return()
        }
        
        generated_codes_list <- c()
        
        tryCatch({
          for (i in seq_len(num_codes)) {
            code <- generate_random_code()
            
            DBI::dbExecute(
              con,
              "INSERT INTO invitation_codes (code, role, assessment_type, generated_at, project_id, generated_by, expires_at)
         VALUES ($1, $2, $3, NOW(), $4, $5, NOW() + INTERVAL '30 days')",
              params = list(
                code,
                invite_role,
                code_type,
                project_id,
                user_id()
              )
            )
            
            generated_codes_list <- c(generated_codes_list, code)
          }
          
          # Get project name
          proj_name <- DBI::dbGetQuery(con,
                                       "SELECT title FROM projects WHERE id = $1",
                                       params = list(project_id))$title[1]
          
          # âœ… Calculate expiry date (30 days from now)
          expiry_date <- format(Sys.Date() + 30, "%d.%m.%Y")
          
          # âœ… Show success message with expiry info
          output$poweruser_code_generation_status <- renderUI({
            div(style = "padding: 15px; background-color: #d4edda; border: 1px solid #c3e6cb; border-radius: 4px; margin-top: 15px;",
                div(
                  style = "display: flex; align-items: center;",
                  icon("check-circle", style = "color: #155724; font-size: 24px;"),
                  div(
                    style = "margin-left: 15px; color: #155724;",
                    tags$strong(
                      style = "font-size: 16px;",
                      sprintf(
                        "âœ“ %d Einladungscode(s) erfolgreich generiert!",
                        length(generated_codes_list)
                      )
                    ),
                    tags$div(
                      style = "margin-top: 8px; font-size: 14px;",
                      icon("clock"),
                      sprintf(" GÃ¼ltig bis: %s (30 Tage)", expiry_date)
                    ),
                    tags$div(
                      style = "margin-top: 5px; font-size: 14px;",
                      icon("folder"),
                      sprintf(" Projekt: %s", proj_name)
                    )
                  )
                ))
          })
          
          # âœ… Show codes in table with expiry
          output$poweruser_generated_codes_table <- renderDataTable({
            data.frame(
              "Einladungscode" = generated_codes_list,
              "Rolle" = invite_role,
              "Typ" = code_type,
              "Projekt" = proj_name,
              "GÃ¼ltig bis" = expiry_date,
              stringsAsFactors = FALSE,
              check.names = FALSE
            )
          }, options = list(
            pageLength = 50,
            dom = 't',
            # Just show table (no search/pagination for small list)
            columnDefs = list(
              list(width = '300px', targets = 0),
              # Wide code column
              list(className = 'dt-center', targets = 1:4)  # Center other columns
            )
          ))
          
          # âœ… Trigger refresh of all codes table
          codes_refresh(codes_refresh() + 1)
          
          showNotification(
            sprintf(
              "âœ“ %d Einladungscode(s) generiert!",
              length(generated_codes_list)
            ),
            type = "message",
            duration = 5
          )
          
        }, error = function(e) {
          output$poweruser_code_generation_status <- renderUI(
            div(
              style = "padding: 10px; background-color: #f8d7da; border: 1px solid #f5c6cb; border-radius: 4px; margin-top: 15px;",
              icon("exclamation-triangle", style = "color: #721c24;"),
              tags$span(style = "margin-left: 8px; color: #721c24;", paste("Fehler:", e$message))
            )
          )
        })
      })
      
      
      # ========== ALL CODES TABLE ==========
      
      output$poweruser_all_codes_table <- renderDT({
        codes_refresh()  # Trigger on refresh
        
        all_codes <- DBI::dbGetQuery(
          con,
          "
    SELECT
      ic.code,
      p.title as project,
      ic.role,
      ic.assessment_type,
      TO_CHAR(ic.generated_at AT TIME ZONE 'Europe/Berlin', 'DD.MM.YYYY HH24:MI') as created_at,
      CASE
        WHEN ic.used_at IS NOT NULL THEN 'Ja'
        ELSE 'Nein'
      END as used,
      TO_CHAR(ic.expires_at AT TIME ZONE 'Europe/Berlin', 'DD.MM.YYYY') as expires_at
    FROM invitation_codes ic
    LEFT JOIN projects p ON p.id = ic.project_id
    ORDER BY ic.generated_at DESC
  "
        )
        
        datatable(
          all_codes,
          colnames = c(
            "Code",
            "Projekt",
            "Rolle",
            "Typ",
            "Erstellt am",
            "Verwendet",
            "GÃ¼ltig bis"
          ),
          options = list(
            pageLength = 25,
            order = list(list(4, 'desc'))  # Sort by created_at
          ),
          rownames = FALSE
        )
      })
      # ========== DOWNLOAD REPORTS ==========
      
      output$poweruser_download_zusammenfassung <- downloadHandler(
        filename = function() {
          project_id <- input$poweruser_report_project
          project_title <- get_all_projects() %>%
            filter(id == project_id) %>%
            pull(title)
          
          paste0("Zusammenfassung_",
                 gsub(" ", "_", project_title),
                 "_",
                 Sys.Date(),
                 ".pdf")
        },
        content = function(file) {
          generate_zusammenfassung_pdf(file, input$poweruser_report_project)
        }
      )
      
      output$poweruser_download_gesamtbericht <- downloadHandler(
        filename = function() {
          project_id <- input$poweruser_report_project
          project_title <- tryCatch({
            get_all_projects() %>%
              dplyr::filter(id == as.integer(project_id)) %>%
              dplyr::pull(title)
          }, error = function(e)
            "Gesamtbericht")
          project_title <- gsub("[^A-Za-z0-9_-]", "_", project_title)
          paste0("Gesamtbericht_",
                 project_title,
                 "_",
                 format(Sys.Date(), "%Y%m%d"),
                 ".pdf")
        },
        content = function(file) {
          req(input$poweruser_report_project)
          
          project_id <- input$poweruser_report_project
          
          if (is.null(project_id) || project_id == "") {
            showNotification("Kein Projekt ausgewÃ¤hlt.",
                             type = "error",
                             duration = 5)
            writeLines("ERROR: Kein Projekt ausgewÃ¤hlt.", file)
            return(NULL)
          }
          
          generate_gesamtbericht_pdf(file, as.integer(project_id), user_role())
        }
      )
      
      #-------------------download labinfo for power user ---------------------
      
      output$poweruser_download_labinfo <- downloadHandler(
        filename = function() {
          project_id    <- input$poweruser_report_project
          project_title <- tryCatch({
            get_all_projects() %>%
              dplyr::filter(id == as.integer(project_id)) %>%
              dplyr::pull(title)
          }, error = function(e)
            "Labor")
          project_title <- gsub("[^A-Za-z0-9_-]", "_", project_title)
          paste0(
            "Laborinformation_",
            project_title,
            "_",
            format(Sys.Date(), "%Y%m%d"),
            ".pdf"
          )
        },
        content = function(file) {
          req(input$poweruser_report_project)
          project_id <- input$poweruser_report_project
          
          if (is.null(project_id) || project_id == "") {
            showNotification("Kein Projekt ausgewÃ¤hlt.",
                             type = "error",
                             duration = 5)
            writeLines("ERROR: Kein Projekt ausgewÃ¤hlt.", file)
            return(NULL)
          }
          
          template_file <- "labinfo_report.Rmd"
          
          if (!file.exists(template_file)) {
            showNotification("Template nicht gefunden.",
                             type = "error",
                             duration = 10)
            writeLines("Template nicht verfÃ¼gbar.", file)
            return(NULL)
          }
          
          showNotification(
            "PDF wird erstellt... Bitte warten.",
            type = "message",
            duration = NULL,
            id = "pdf_labinfo_pu_progress"
          )
          
          tryCatch({
            template_path <- normalizePath(template_file, mustWork = TRUE)
            tmpdir        <- tempdir()
            owd           <- setwd(tmpdir)
            on.exit({
              setwd(owd)
              removeNotification("pdf_labinfo_pu_progress")
            }, add = TRUE)
            
            file.copy(template_path,
                      file.path(tmpdir, template_file),
                      overwrite = TRUE)
            
            con <- get_db_con()
            on.exit(DBI::dbDisconnect(con), add = TRUE)
            
            # Get project title from DB
            project_query <- DBI::dbGetQuery(con,
                                             "SELECT title FROM projects WHERE id = $1",
                                             params = list(as.integer(project_id)))
            project_title <- if (nrow(project_query) > 0 &&
                                 !is.na(project_query$title[1])) {
              project_query$title[1]
            } else {
              "Labor"
            }
            
            # Get lab info
            labinfo <- DBI::dbGetQuery(con,
                                       "SELECT * FROM lab_info WHERE project_id = $1",
                                       params = list(as.integer(project_id)))
            
            if (nrow(labinfo) == 0) {
              labinfo <- data.frame(
                project_id      = project_id,
                name            = "",
                internetadresse = "",
                stringsAsFactors = FALSE
              )
            }
            
            write.csv(
              labinfo,
              file.path(tmpdir, "labinfo.csv"),
              row.names = FALSE,
              fileEncoding = "UTF-8"
            )
            
            output_pdf <- rmarkdown::render(
              input         = file.path(tmpdir, template_file),
              output_format = "pdf_document",
              output_file   = "labinfo_report.pdf",
              output_dir    = tmpdir,
              params        = list(project_title = project_title, project_id    = project_id),
              envir = new.env(),
              quiet = FALSE
            )
            
            output_pdf <- append_organigramm_if_exists(output_pdf, project_id)
            
            file.copy(output_pdf, file, overwrite = TRUE)
            
            removeNotification("pdf_labinfo_pu_progress")
            showNotification("PDF erfolgreich erstellt!",
                             type = "message",
                             duration = 5)
            
          }, error = function(e) {
            removeNotification("pdf_labinfo_pu_progress")
            showNotification(paste("Fehler:", e$message),
                             type = "error",
                             duration = 15)
            writeLines(paste("Fehler:", e$message), file)
          })
        },
        contentType = "application/pdf"
      )
      
      # ========== FREMDBEWERTUNG TAB ==========
      
      observe({
        projects <- get_all_projects()
        choices  <- setNames(projects$id, projects$title)
        updateSelectInput(session,
                          "poweruser_fremd_project_selector",
                          choices = choices)
      })
      
      get_fremd_data_poweruser <- reactive({
        req(input$poweruser_fremd_project_selector)
        project_id <- as.integer(input$poweruser_fremd_project_selector)
        data <- tryCatch({
          DBI::dbGetQuery(
            con,
            "
      SELECT
        u.username         AS reviewer,
        u.role             AS rolle,
        r.question_id      AS frage_id,
        r.response_value   AS bewertung,
        r.text_value       AS kommentar,
        TO_CHAR(r.created_at AT TIME ZONE 'Europe/Berlin',
                'DD.MM.YYYY HH24:MI') AS eingereicht_am
      FROM responses r
      JOIN users u ON u.id = r.user_id
      WHERE r.project_id::text = $1::text
        AND r.assessment_type  = 'fremdbewertung'
      ORDER BY r.created_at DESC, r.question_id
    ",
            params = list(as.character(project_id))
          )
        }, error = function(e) {
          data.frame(
            reviewer = character(0),
            rolle = character(0),
            frage_id = character(0),
            bewertung = character(0),
            kommentar = character(0),
            eingereicht_am = character(0),
            stringsAsFactors = FALSE
          )
        })
        if (nrow(data) == 0)
          return(data)
        data$rolle    <- ifelse(data$rolle == "leading_peer", "Leading Peer", "Co-Peer")
        reviewers     <- sort(unique(data$reviewer))
        peer_labels   <- setNames(paste0("Peer ", seq_along(reviewers)), reviewers)
        data$reviewer <- peer_labels[data$reviewer]
        data$bereich  <- factor(
          substr(data$frage_id, 1, 1),
          levels = c("F", "M", "P", "E", "Q"),
          labels = c(
            "FÃ¼hrung",
            "Mitarbeitende",
            "Patienten",
            "Einsender",
            "QualitÃ¤t"
          )
        )
        data[, c(
          "reviewer",
          "rolle",
          "bereich",
          "frage_id",
          "bewertung",
          "kommentar",
          "eingereicht_am"
        )]
      })
      
      output$poweruser_fremdbewertung_table <- DT::renderDataTable({
        req(input$poweruser_fremd_project_selector)
        data <- get_fremd_data_poweruser()
        if (is.null(data) || nrow(data) == 0) {
          return(
            data.frame(Hinweis = "Keine Fremdbewertungen fÃ¼r dieses Projekt vorhanden.")
          )
        }
        names(data)[names(data) == "reviewer"]       <- "Reviewer"
        names(data)[names(data) == "rolle"]          <- "Rolle"
        names(data)[names(data) == "bereich"]        <- "Bereich"
        names(data)[names(data) == "frage_id"]       <- "Frage-ID"
        names(data)[names(data) == "bewertung"]      <- "Bewertung"
        names(data)[names(data) == "kommentar"]      <- "Kommentar"
        names(data)[names(data) == "eingereicht_am"] <- "Eingereicht am"
        DT::datatable(
          data,
          options  = list(
            pageLength = 25,
            scrollX = TRUE,
            order = list(list(ncol(data) - 1L, "desc"))
          ),
          rownames = FALSE,
          filter = "top",
          class = "cell-border stripe compact"
        )
      })
      
      # â”€â”€ Fremdbewertung Uebersicht - same tabbed, badge-style dashboard as
      # "Selbstbewertung Uebersicht" (poweruser_summary_fuehrung etc.),
      # reusing create_dashboard_rows_fremd() + get_fremdbewertung_overview_df(). â”€â”€
      render_poweruser_fremd_overview <- function(topic_prefix, questions_list, empty_msg) {
        responses_data_changed()
        req(user_logged_in())
        req(user_role() == "power_user")
        req(input$poweruser_fremd_project_selector)
        
        project_id <- as.character(input$poweruser_fremd_project_selector)
        df <- get_fremdbewertung_overview_df(project_id, topic_prefix)
        
        if (nrow(df) == 0) {
          return(
            div(
              style = "padding: 40px; text-align: center; color: #999;",
              icon("inbox", style = "font-size: 48px;"),
              tags$p(style = "margin-top: 20px; font-size: 16px;", "Keine Daten vorhanden"),
              tags$p(style = "font-size: 14px;", empty_msg)
            )
          )
        }
        
        tags$div(class = "dashboard-wrapper",
                 tags$table(
                   class = "dashboard-table",
                   tags$thead(tags$tr(
                     tags$th(class = "dashboard-col-question", "Fragen"),
                     tags$th(class = "dashboard-col-selbst", "Fremdbewertung")
                   )),
                   tags$tbody(create_dashboard_rows_fremd(df, questions_list))
                 ))
      }
      
      output$poweruser_fremd_summary_fuehrung <- renderUI({
        render_poweruser_fremd_overview("F", fuehrung_questions, "Es wurden noch keine FÃ¼hrung-Fremdbewertungen eingereicht.")
      })
      output$poweruser_fremd_summary_mitarbeitende <- renderUI({
        render_poweruser_fremd_overview("M", mit_questions, "Es wurden noch keine Mitarbeitende-Fremdbewertungen eingereicht.")
      })
      output$poweruser_fremd_summary_patienten <- renderUI({
        render_poweruser_fremd_overview("P", pat_questions, "Es wurden noch keine Patienten-Fremdbewertungen eingereicht.")
      })
      output$poweruser_fremd_summary_einsender <- renderUI({
        render_poweruser_fremd_overview("E", ein_questions, "Es wurden noch keine Einsender-Fremdbewertungen eingereicht.")
      })
      output$poweruser_fremd_summary_qualitaet <- renderUI({
        render_poweruser_fremd_overview("Q", qual_questions, "Es wurden noch keine QualitÃ¤tsindikatoren-Fremdbewertungen eingereicht.")
      })
      
      # â”€â”€ Vergleich Selbst- und Fremdbewertung (live dashboard tab) - the
      # same spider-plot + comparison-table logic the Vergleichstabelle PDF
      # already uses (create_spider_plot_selbst/_overlay,
      # build_comparison_rows_shared), just rendered live instead of into a
      # PDF, and made visible to the power_user role. Each topic gets its
      # own reactive so the (fairly expensive) plot generation only re-runs
      # when the selected project actually changes, not on every render. â”€â”€
      poweruser_cmp_topics <- list(
        list(key = "fuehrung",       prefix = "F",  questions_name = "fuehrung_questions", label = "FÃ¼hrung"),
        list(key = "mitarbeitende",  prefix = "M",  questions_name = "mit_questions",       label = "Mitarbeitende"),
        list(key = "patienten",      prefix = "P",  questions_name = "pat_questions",       label = "Patienten"),
        list(key = "einsender",      prefix = "E",  questions_name = "ein_questions",       label = "Einsender"),
        list(key = "qualitaet",      prefix = "Q",  questions_name = "qual_questions",      label = "QualitÃ¤t")
      )
      
      for (topic in poweruser_cmp_topics) {
        local({
          tp <- topic  # capture this iteration's value, not the loop variable
          
          plot_data <- reactive({
            req(user_logged_in())
            req(user_role() == "power_user")
            req(input$poweruser_fremd_project_selector)
            project_id <- as.character(input$poweruser_fremd_project_selector)
            
            work_dir <- file.path(tempdir(), paste0("pu_cmp_", tp$key, "_", as.integer(Sys.time()), "_", sample.int(1e6, 1)))
            dir.create(work_dir, recursive = TRUE, showWarnings = FALSE)
            owd <- setwd(work_dir)
            on.exit(setwd(owd), add = TRUE)
            
            tryCatch(create_spider_plot_selbst(project_id, tp$key, tp$prefix, tp$label),
                     error = function(e) message("spider_selbst error: ", e$message))
            tryCatch(create_spider_plot_overlay(project_id, tp$key, tp$prefix, tp$label),
                     error = function(e) message("spider_overlay error: ", e$message))
            
            list(
              selbst_png  = file.path(work_dir, paste0("spider_selbst_", tp$key, ".png")),
              overlay_png = file.path(work_dir, paste0("spider_overlay_", tp$key, ".png")),
              project_id  = project_id
            )
          })
          
          # âœ… FIXED: the images are generated at a fixed 900x950px (see
          # create_spider_plot_selbst/_overlay) - returning width="100%"
          # with no height let the browser scale each image to the full
          # column width and grow the height to match, which could make it
          # much taller than the 400px imageOutput() container and spill
          # down over the comparison table below it. Giving both width and
          # height explicitly (matching that ~900:950 aspect ratio) keeps
          # the rendered image inside its container no matter how wide the
          # column is.
          output[[paste0("poweruser_cmp_", tp$key, "_selbst")]] <- renderImage({
            pd <- plot_data()
            if (!file.exists(pd$selbst_png)) return(list(src = "", contentType = "image/png"))
            list(src = pd$selbst_png, contentType = "image/png",
                 width = 370, height = 390, style = "max-width:100%; height:auto;",
                 alt = "Selbstbewertung nach Berufsgruppe")
          }, deleteFile = FALSE)
          
          output[[paste0("poweruser_cmp_", tp$key, "_overlay")]] <- renderImage({
            pd <- plot_data()
            if (!file.exists(pd$overlay_png)) return(list(src = "", contentType = "image/png"))
            list(src = pd$overlay_png, contentType = "image/png",
                 width = 370, height = 390, style = "max-width:100%; height:auto;",
                 alt = "Ã˜ Selbst- vs. Fremdbewertung")
          }, deleteFile = FALSE)
          
          output[[paste0("poweruser_cmp_", tp$key, "_table")]] <- renderUI({
            pd <- plot_data()
            questions_list <- get(tp$questions_name)
            rows <- build_comparison_rows_shared(pd$project_id, questions_list, tp$prefix)
            
            if (is.null(rows) || !nrow(rows))
              return(div(style = "padding: 20px; color: #999;", "Keine Vergleichsdaten vorhanden."))
            
            tags$table(
              class = "dashboard-table",
              tags$thead(tags$tr(
                tags$th(class = "dashboard-col-question", "Frage"),
                tags$th(class = "dashboard-col-selbst", "Selbstbewertung"),
                tags$th(class = "dashboard-col-selbst", "Fremdbewertung")
              )),
              tags$tbody(do.call(tagList, lapply(seq_len(nrow(rows)), function(i) {
                tags$tr(
                  class = "dashboard-row",
                  tags$td(class = "dashboard-col-question", rows$Frage[i]),
                  tags$td(class = "dashboard-col-selbst", HTML(.markup_to_html(rows$Selbstbewertung[i]))),
                  tags$td(class = "dashboard-col-selbst", HTML(.markup_to_html(rows$Fremdbewertung[i])))
                )
              })))
            )
          })
        })
      }
      
      output$poweruser_fremd_project_banner <- renderUI({
        req(input$poweruser_fremd_project_selector)
