        div(
          class = "alert alert-info",
          style = "margin-top: 10px;",
          icon("folder-open"),
          strong(" AusgewÃ¤hltes Projekt: "),
          proj$title[1]
        )
      })
      
      output$poweruser_fremdbewertung_summary_cards <- renderUI({
        req(input$poweruser_fremd_project_selector)
        data <- get_fremd_data_poweruser()
        if (nrow(data) == 0) {
          return(
            div(
              class = "alert alert-warning",
              icon("exclamation-circle"),
              " Keine Fremdbewertungen fÃ¼r dieses Projekt vorhanden."
            )
          )
        }
        fluidRow(column(3, div(
          class = "stat-box",
          tags$h2(length(
            unique(data$Reviewer %||% data$reviewer)
          ), class = "stat-number"),
          tags$p("Reviewer", class = "stat-label")
        )), column(3, div(
