  # -------------ADMIN USER DATA EXPORT - Populate Dropdown---------------------
  
  observe({
    req(user_logged_in(), user_role() == "admin")
    
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con), add = TRUE)
    
    users <- DBI::dbGetQuery(
      con,
      "SELECT
      u.id,
      u.username,
      u.role,
      p.title as project_name,
      COALESCE((SELECT COUNT(*) FROM responses WHERE user_id = u.id), 0) as response_count
    FROM users u
    LEFT JOIN projects p ON u.project_id = p.id
    ORDER BY u.username"
    )
    
    if (nrow(users) == 0) {
      updateSelectInput(session,
                        "admin_export_user",
                        choices = c("Keine Benutzer vorhanden" = ""))
      return()
    }
    
    # âœ… FIX: Ensure response_count is integer
    users$response_count <- as.integer(users$response_count)
    users$response_count[is.na(users$response_count)] <- 0
    
    # âœ… Create descriptive choices with safe formatting
    choices <- setNames(
      as.character(users$id),
      # Ensure ID is character
      sprintf(
        "%s (%s) - %s - %d Antworten",
        users$username,
        users$role,
        ifelse(
          is.na(users$project_name) |
            users$project_name == "",
          "Kein Projekt",
          users$project_name
        ),
        users$response_count  # Now guaranteed to be integer
      )
    )
    
    updateSelectInput(session, "admin_export_user", choices = choices)
    
    message("âœ“ Updated user export dropdown with ",
            length(choices),
            " users")
  })
  
  
  # ============================================
  # LOAD USER DATA PREVIEW - FIXED FOR YOUR SCHEMA
  # ============================================
  
  observeEvent(input$load_user_preview, {
    req(user_role() == "admin")
    req(input$admin_export_user)
    
    uid <- as.integer(input$admin_export_user)
    
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con), add = TRUE)
    
    # Get user info
    user_info <- DBI::dbGetQuery(
      con,
      "SELECT
      u.id,
      u.username,
      u.role,
      u.assessment_type,
      u.registered_at,
      p.title as project_name,
      p.einrichtung
    FROM users u
    LEFT JOIN projects p ON u.project_id = p.id
    WHERE u.id = $1",
      params = list(uid)
    )
    
    # Count answers
    answer_count <- DBI::dbGetQuery(con,
                                    "SELECT COUNT(*) as count FROM responses WHERE user_id = $1",
                                    params = list(uid))$count
    
    # Count drafts (using last_saved instead of updated_at)
    draft_count <- DBI::dbGetQuery(
      con,
      "SELECT COUNT(*) as count FROM questionnaire_drafts WHERE user_id = $1",
      params = list(as.character(uid))
    )$count
    
    # Get answer breakdown by assessment type
    answer_breakdown <- DBI::dbGetQuery(
      con,
      "SELECT
      assessment_type,
      COUNT(*) as count
    FROM responses
    WHERE user_id = $1
    GROUP BY assessment_type
    ORDER BY assessment_type",
      params = list(uid)
    )
    
    # Get sample of recent answers
    sample_answers <- DBI::dbGetQuery(
      con,
      "SELECT
      question_id,
      response_value,
      text_value,
      assessment_type,
      created_at
    FROM responses
    WHERE user_id = $1
    ORDER BY created_at DESC
    LIMIT 5",
      params = list(uid)
    )
    
    # Render preview
    output$user_data_preview <- renderUI({
      if (nrow(user_info) == 0) {
        return(div(
          style = "text-align: center; padding: 40px; color: #999;",
          icon("exclamation-triangle", style = "font-size: 48px;"),
          h4("Benutzer nicht gefunden")
        ))
      }
      
      u <- user_info[1, ]
      
      tagList(
        fluidRow(
          column(
            width = 6,
            h4(icon("user"), " Benutzerprofil"),
            tags$dl(
              tags$dt("ID:"),
              tags$dd(u$id),
              tags$dt("Benutzername:"),
              tags$dd(u$username),
              tags$dt("Rolle:"),
              tags$dd(u$role),
              tags$dt("Bewertungstyp:"),
              tags$dd(u$assessment_type),
              tags$dt("Registriert:"),
              tags$dd(format(
                as.POSIXct(u$registered_at), "%d.%m.%Y %H:%M"
              ))
            )
          ),
          
          column(
            width = 6,
            h4(icon("folder"), " Projekt"),
            tags$dl(
              tags$dt("Projektname:"),
              tags$dd(ifelse(
                is.na(u$project_name), "â€”", u$project_name
              )),
              tags$dt("Einrichtung:"),
              tags$dd(ifelse(
                is.na(u$einrichtung), "â€”", u$einrichtung
              ))
            )
          )
        ),
        
        hr(),
        
        fluidRow(
          column(
            width = 4,
            div(
              style = "text-align: center; padding: 20px; background-color: #d9edf7; border-radius: 6px;",
              h2(style = "margin: 0; color: #31708f;", answer_count),
              p(style = "margin: 5px 0 0 0; color: #31708f;", icon("comments"), " Antworten")
            )
          ),
          
          column(
            width = 4,
            div(
              style = "text-align: center; padding: 20px; background-color: #fcf8e3; border-radius: 6px;",
              h2(style = "margin: 0; color: #8a6d3b;", draft_count),
              p(style = "margin: 5px 0 0 0; color: #8a6d3b;", icon("edit"), " EntwÃ¼rfe")
            )
          ),
          
          column(
            width = 4,
            div(
              style = "text-align: center; padding: 20px; background-color: #dff0d8; border-radius: 6px;",
              h2(style = "margin: 0; color: #3c763d;", nrow(answer_breakdown)),
              p(style = "margin: 5px 0 0 0; color: #3c763d;", icon("list"), " Bewertungstypen")
            )
          )
        ),
        
        hr(),
        
        h4(icon("chart-bar"), " Antworten nach Typ"),
        
        if (nrow(answer_breakdown) > 0) {
          renderTable({
            answer_breakdown
          }, colnames = TRUE)
        } else {
          p(style = "color: #999;", "Keine Daten")
        },
        
        hr(),
        
        h4(icon("eye"), " Letzte 5 Antworten (Vorschau)"),
        
        if (nrow(sample_answers) > 0) {
          tags$div(style = "overflow-x: auto;", renderTable({
            data.frame(
              Frage = sample_answers$question_id,
              Antwort = sample_answers$response_value,
              Typ = sample_answers$assessment_type,
              Datum = format(
                as.POSIXct(sample_answers$created_at),
                "%d.%m.%Y %H:%M"
              )
            )
          }, colnames = TRUE))
        } else {
          p(style = "color: #999;", "Keine Antworten vorhanden.")
        },
        
        hr(),
        
        div(
          style = "background-color: #d9edf7; padding: 15px; border-radius: 6px;",
          icon("info-circle", style = "color: #31708f;"),
          tags$span(
            style = "margin-left: 8px;",
            "Der vollstÃ¤ndige Export enthÃ¤lt alle ",
            strong(answer_count),
            " Antworten des Benutzers."
          )
        )
      )
    })
  })
  
  
