  observeEvent(input$create_project_button, {
    req(user_role() %in% c("admin", "laborleitung"))
    
    role <- user_role()
    
    # âœ… For ADMIN: project_name is REQUIRED
    if (role == "admin") {
      if (is.null(input$project_name) ||
          trimws(input$project_name) == "") {
        output$project_creation_status <- renderUI({
          div(
            class = "alert alert-danger",
            style = "margin-top: 15px;",
            icon("exclamation-circle"),
            strong(" Fehler: "),
            "Bitte geben Sie einen Projektnamen ein."
          )
        })
        return()
      }
      project_title <- trimws(input$project_name)
    }
    
    # âœ… For LABORLEITUNG: Use einrichtung as title
    if (role == "laborleitung") {
      if (is.null(input$einrichtung) || trimws(input$einrichtung) == "") {
        output$project_creation_status <- renderUI({
          div(
            class = "alert alert-danger",
            style = "margin-top: 15px;",
            icon("exclamation-circle"),
            strong(" Fehler: "),
            "Bitte geben Sie die Einrichtung ein."
          )
        })
        return()
      }
      project_title <- trimws(input$einrichtung)
    }
    
    # Show loading
    output$project_creation_status <- renderUI({
      div(
        class = "alert alert-info",
        style = "margin-top: 15px;",
        icon("spinner", class = "fa-spin"),
        " Projekt wird erstellt..."
      )
    })
    
    tryCatch({
      con <- get_db_con()
      on.exit(DBI::dbDisconnect(con), add = TRUE)
      
      new_project <- DBI::dbGetQuery(
        con,
        "INSERT INTO projects (title, einrichtung, description, zeitraum, created_at, owner_id, status)
       VALUES ($1, $2, $3, $4, NOW(), $5, 'active')
       RETURNING id, title",
        params = list(
          project_title,
          if (is.null(input$einrichtung) ||
              trimws(input$einrichtung) == "")
            NA
          else
            trimws(input$einrichtung),
          if (is.null(input$project_description) ||
              trimws(input$project_description) == "")
            NA
          else
            trimws(input$project_description),
          if (is.null(input$zeitraum) ||
              trimws(input$zeitraum) == "")
            NA
          else
            trimws(input$zeitraum),
          user_id()
        )
      )
      
      if (nrow(new_project) > 0) {
        new_id <- as.character(new_project$id[1])
        new_title <- new_project$title[1]
        
        current_project_id(new_id)
        current_project_name(new_title)
        
        output$project_creation_status <- renderUI({
          div(
            class = "alert alert-success",
            style = "margin-top: 15px;",
            icon("check-circle"),
            strong(" Erfolg! "),
            sprintf("Projekt '%s' wurde erstellt.", new_title)
          )
        })
        
        showNotification(
          paste0("âœ“ Projekt '", new_title, "' erstellt!"),
          type = "message",
          duration = 5
        )
        
        # Clear form
        if (role == "admin") {
          updateTextInput(session, "project_name", value = "")
        }
        updateTextInput(session, "einrichtung", value = "")
        updateTextAreaInput(session, "project_description", value = "")
        updateTextInput(session, "zeitraum", value = "")
      }
      
    }, error = function(e) {
      output$project_creation_status <- renderUI({
        div(
          class = "alert alert-danger",
          style = "margin-top: 15px;",
          icon("exclamation-triangle"),
          strong(" Fehler: "),
          e$message
        )
      })
    })
  })
  
