  output$antworten_project_selector_ui <- renderUI({
    message("\n========== PROJECT SELECTOR UI ==========")
    message("Timestamp: ", Sys.time())
    
    # Check login
    if (!user_logged_in()) {
      message("âŒ User not logged in")
      return(NULL)
    }
    
    role <- user_role()
    uid <- user_id()
    
    message("Role: ", role)
    message("User ID: ", uid)
    
    if (is.null(role) || is.null(uid)) {
      message("âŒ Role or UID is NULL")
      return(NULL)
    }
    
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con), add = TRUE)
    
    # ===== FOR LABORLEITUNG =====
    if (role == "laborleitung") {
      message("â†’ Getting assigned project for laborleitung...")
      
      proj <- DBI::dbGetQuery(
        con,
        "SELECT p.id, p.title, p.einrichtung
       FROM projects p
       JOIN users u ON p.id = u.project_id
       WHERE u.id = $1",
        params = list(uid)
      )
      
      message("â†’ Query returned ", nrow(proj), " row(s)")
      
      if (nrow(proj) == 0) {
        message("âŒ No project assigned")
        return(
          div(
            style = "padding: 20px; background-color: #f8d7da; border: 1px solid #f5c6cb; border-radius: 4px; margin-bottom: 20px;",
            icon("exclamation-triangle", style = "color: #721c24; font-size: 24px;"),
            div(
              style = "margin-top: 10px; color: #721c24;",
              tags$strong("Kein Projekt zugewiesen"),
              tags$p(
                "Sie sind noch keinem Projekt zugeordnet. Bitte kontaktieren Sie den Administrator."
              )
            )
          )
        )
      }
      
      project_id <- as.character(proj$id[1])
      project_title <- proj$title[1]
      einrichtung <- if (!is.na(proj$einrichtung[1]))
        proj$einrichtung[1]
      else
        NULL
      
      message("âœ“ Project ID: ", project_id)
      message("âœ“ Project Title: ", project_title)
      message("âœ“ Einrichtung: ", if (is.null(einrichtung))
        "NULL"
        else
          einrichtung)
      
      # Set reactive values
      current_project_id(project_id)
      current_project_name(project_title)
      
      message("âœ“ Returning banner for laborleitung")
      message("=========================================\n")
      
      return(
        div(
          style = "margin-bottom: 20px; padding: 15px; background-color: #e8f4f8; border-left: 4px solid #003B73; border-radius: 4px;",
          div(
            style = "font-weight: bold; color: #003B73; font-size: 16px;",
            icon("folder", style = "font-size: 20px;"),
            tags$span(style = "margin-left: 10px;", "Ihr Projekt: ", project_title)
          ),
          if (!is.null(einrichtung) && nzchar(einrichtung)) {
            tags$div(
              style = "margin-top: 8px; color: #666;",
              icon("hospital"),
              tags$span(style = "margin-left: 5px;", "Einrichtung: "),
              tags$strong(einrichtung)
            )
          },
          tags$small(
            style = "display: block; margin-top: 8px; color: #666;",
            icon("info-circle"),
            " Hier sehen Sie die Selbstbewertungen aller Teilnehmer dieses Projekts."
          )
        )
      )
    }
    
    # ===== FOR ADMIN =====
    if (role == "admin") {
      message("â†’ Getting all projects for admin...")
      
      projs <- DBI::dbGetQuery(con,
                               "SELECT id, title FROM projects ORDER BY created_at DESC")
      
      message("â†’ Found ", nrow(projs), " project(s)")
      
      if (nrow(projs) == 0) {
        return(div(
          style = "padding: 20px; color: #999; text-align: center;",
          icon("info-circle", style = "font-size: 24px;"),
          tags$p(style = "margin-top: 10px;", "Keine Projekte vorhanden.")
        ))
      }
      
      choices <- setNames(as.character(projs$id), projs$title)
      
      selected <- if (!is.null(current_project_id()) &&
                      current_project_id() %in% choices) {
        current_project_id()
      } else {
        choices[1]
      }
      
      message("âœ“ Returning dropdown for admin")
      message("=========================================\n")
      
      return(tagList(
        selectInput(
          "antworten_project_selector",
          label = tags$div(
            icon("folder"),
            tags$span(style = "margin-left: 8px; font-weight: 600;", "Peer Review auswÃ¤hlen:")
          ),
          choices = choices,
          selected = selected
        ),
        tags$small(
          style = "color: #666; margin-top: -10px; display: block; margin-bottom: 15px;",
          icon("info-circle"),
          sprintf(" %d Projekt(e) verfÃ¼gbar", length(choices))
        )
      ))
    }
    
    # ===== FOR OTHER ROLES =====
    if (role %in% c("colleague", "leading_peer", "co_peer")) {
      message("â†’ Getting assigned project for ", role, "...")
      
      proj <- DBI::dbGetQuery(
        con,
        "SELECT p.id, p.title
       FROM projects p
       JOIN users u ON p.id = u.project_id
       WHERE u.id = $1",
        params = list(uid)
      )
      
      if (nrow(proj) == 0) {
        return(
          div(
            style = "padding: 20px; background-color: #f8d7da; border: 1px solid #f5c6cb; border-radius: 4px;",
            icon("exclamation-triangle", style = "color: #721c24;"),
            tags$span(style = "margin-left: 8px; color: #721c24;", "Kein Projekt zugewiesen")
          )
        )
      }
      
      project_id <- as.character(proj$id[1])
      project_title <- proj$title[1]
      
      current_project_id(project_id)
      current_project_name(project_title)
      
      return(
        div(
          style = "margin-bottom: 20px; padding: 15px; background-color: #e8f4f8; border-left: 4px solid #003B73; border-radius: 4px;",
          div(
            style = "font-weight: bold; color: #003B73; font-size: 16px;",
            icon("folder", style = "font-size: 20px;"),
            tags$span(style = "margin-left: 10px;", "Projekt: ", project_title)
          )
        )
      )
    }
    
    # Fallback
    message("â†’ Unrecognized role: ", role)
    return(NULL)
  })
  
  # âœ… CRITICAL: Force rendering
  outputOptions(output,
                "antworten_project_selector_ui",
                suspendWhenHidden = FALSE)
  
  
  # âœ… Admin observer
  observeEvent(input$antworten_project_selector, {
