  #---------------------LABORLEITUNG SUMMARY - TAB OUTPUTS-----------------------
  
  # 1. FÃœHRUNG TAB (Laborleitung)
  output$labor_leiter_summary_fuehrung <- renderUI({
    message("\n========== FÃœHRUNG TAB ==========")
    
    if (is.null(current_project_id())) {
      message("âŒ current_project_id() is NULL")
      return(div("ERROR: No project"))
    }
    
    project_id <- current_project_id()
    
    message("Project ID: ", project_id)
    message("User: ", user_id())
    message("Role: ", user_role())
    
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con))
    
    # âœ… Test query first
    test_count <- DBI::dbGetQuery(
      con,
      "SELECT COUNT(*) as count FROM responses
     WHERE project_id::text = $1::text
     AND assessment_type = 'selbstbewertung'
     AND question_id LIKE 'F%'",
      params = list(as.character(project_id))
    )$count
    
    message("â†’ Test count for F questions: ", test_count)
    
    fuehrung_df <- DBI::dbGetQuery(
      con,
      "
  SELECT
    u.username,
    u.id as user_id,
    r.question_id,
    r.response_value,
    r.text_value,
    COALESCE(r.group_size, 1) as group_size
  FROM (
    SELECT DISTINCT ON (r.user_id, r.question_id)
      r.*
    FROM responses r
    WHERE r.project_id::text = $1::text
      AND r.assessment_type = 'selbstbewertung'
    ORDER BY
      r.user_id,
      r.question_id,
      r.created_at DESC NULLS LAST,
      r.submission_id DESC NULLS LAST
  ) r
  JOIN users u ON u.id = r.user_id
  WHERE r.project_id::text = $1::text
    AND r.assessment_type = 'selbstbewertung'
    AND r.question_id LIKE 'F%'
  ORDER BY r.question_id, u.username
",
      params = list(as.character(project_id))
    )
    
    message("â†’ Rows returned: ", nrow(fuehrung_df))
    
    if (nrow(fuehrung_df) > 0) {
      message("â†’ Sample data (first 3 rows):")
      print(head(fuehrung_df, 3))
    } else {
      message("âŒ No data found!")
    }
    
    message("=====================================\n")
    
    # If no data, show message
    if (nrow(fuehrung_df) == 0) {
      return(
        div(
          style = "padding: 40px; text-align: center; color: #999;",
          icon("inbox", style = "font-size: 48px;"),
          tags$p(style = "margin-top: 20px; font-size: 16px;", "Keine Daten vorhanden"),
          tags$p(
            style = "font-size: 14px;",
            "Es wurden noch keine FÃ¼hrung-Antworten eingereicht."
          ),
          tags$hr(),
          tags$div(
            style = "background: #fff3cd; padding: 15px; border-radius: 4px; margin-top: 20px; text-align: left;",
            tags$strong("ðŸ” DEBUG:"),
            tags$br(),
            "Project ID: ",
            project_id,
            tags$br(),
            "Test count: ",
            test_count
          )
        )
      )
    }
    
    # Calculate stats and render
    fuehrung_stats <- calc_weighted_stats(fuehrung_df, fuehrung_questions, project_id)
    berufsgruppe_breakdown <- get_berufsgruppe_breakdown(project_id)
    
    tags$div(class = "dashboard-wrapper",
             tags$table(
               class = "dashboard-table",
               tags$thead(tags$tr(
                 tags$th(class = "dashboard-col-question", "Fragen"),
                 tags$th(class = "dashboard-col-selbst", "Selbstbewertung"),
                 #tags$th(class = "dashboard-col-stats", "Statistik"),
                 tags$th(class = "dashboard-col-plot", "Durchschnitt nach Berufsgruppe")
               )),
               tags$tbody(
                 create_dashboard_rows(
                   fuehrung_df,
                   fuehrung_questions,
                   "overlay_radar_fuehrung_laborleitung",
                   berufsgruppe_breakdown,
                   project_id
                 )
               )
             ))
  })
  
  # 2. MITARBEITENDE TAB (Laborleitung)
  output$labor_leiter_summary_mitarbeitende <- renderUI({
    if (is.null(current_project_id())) {
      return(div("ERROR: No project"))
    }
    
    project_id <- current_project_id()
    
    message("\n========== MITARBEITENDE TAB ==========")
    message("Project ID: ", project_id)
    
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con))
    
    mit_df <- DBI::dbGetQuery(
      con,
      "
    SELECT
      u.username,
      u.id as user_id,
      r.question_id,
      r.response_value,
      r.text_value,
      CAST(qd.answers::json->>'group_size' AS INTEGER) as group_size
    FROM responses r
    JOIN users u ON u.id = r.user_id
    LEFT JOIN questionnaire_drafts qd
      ON u.id::text = qd.user_id::text
      AND qd.project_id::text = r.project_id::text
      AND qd.questionnaire_id = 'peer_review'
    WHERE r.project_id::text = $1::text
      AND r.assessment_type = 'selbstbewertung'
      AND r.question_id LIKE 'M%'
    ORDER BY r.question_id, u.username
  ",
      params = list(as.character(project_id))
    )
    
    message("â†’ Rows returned: ", nrow(mit_df))
    
    # âœ… ADD THIS CHECK
    if (nrow(mit_df) == 0) {
      message("âŒ No data for Mitarbeitende")
      return(
        div(
          style = "padding: 40px; text-align: center; color: #999;",
          icon("inbox", style = "font-size: 48px;"),
