  `%||%` <- function(a, b)
    if (!is.null(a) && !is.na(a))
      a
  else
    b
  
  #----------------------load draft of answers------------------------------------
  draft_loaded_once <- reactiveVal(FALSE)
  
  observeEvent(user_logged_in(), {
    if (!isTRUE(user_logged_in()))
      return()
    draft_loaded_once(FALSE)   # reset on login
  }, ignoreInit = TRUE)
  
  
  #--------------- MASTER TAB CHANGE HANDLER (ALL TAB LOGIC HERE)----------------
  
  observeEvent(input$sidebar_menu, {
    current_tab <- input$sidebar_menu
    previous_tab <- last_tab()
    
    message("\n========== TAB CHANGED ==========")
    message("New tab: ", current_tab)
    message("Previous tab: ", ifelse(is.null(previous_tab), "NULL", previous_tab))
    message("User logged in: ", user_logged_in())
    message("Draft loaded: ", draft_loaded())
    message("================================\n")
    
    #----------------------- 0. FLUSH ANY PENDING LAB INFO SAVE ----------------
    # âœ… MOVED HERE (before logout handling): if this check only ran AFTER the
    # logout branch, clicking Logout directly while still on the Lab Info tab
    # would return() before ever reaching it - the exact case where losing an
    # unsaved change matters most. Running it first covers BOTH clicking
    # Logout directly from Lab Info AND switching to any other tab.
    
    if (!is.null(previous_tab) &&
        previous_tab == "fill_labinfo" &&
        current_tab != "fill_labinfo" &&
        isTRUE(labinfo_answers_changed())) {
      message("â†’ Leaving Lab Info tab with unsaved changes - flushing save now")
      tryCatch({
        save_lab_info_data()
        labinfo_answers_changed(FALSE)
      }, error = function(e) {
        message("Flush save on Lab Info tab leave failed: ", e$message)
      })
    }
    
    #----------------------- 1. HANDLE LOGOUT-----------------------------------
    
    if (current_tab == "logout") {
      message("â†’ Logout triggered")
      do_logout()
      return()
    }
    
    #------------- 2. LEAVING FRAGEBOGEN TAB - RESET DRAFT FLAG----------------
    
    if (!is.null(previous_tab) &&
        previous_tab %in% c("fill_questionnaire", "fragebogen", "questionnaire") &&
        !current_tab %in% c("fill_questionnaire", "fragebogen", "questionnaire")) {
      message("â†’ Leaving fragebogen tab, resetting draft flag")
      draft_loaded(FALSE)
    }
    
    #----------- 3. ENTERING FRAGEBOGEN TAB - LOAD DRAFT------------------------
    
    if (current_tab %in% c("fill_questionnaire", "fragebogen", "questionnaire")) {
      message("â†’ Fragebogen tab activated")
      
      if (user_logged_in() && !draft_loaded()) {
        message("â†’ Starting draft load process...")
        
        loading_active(TRUE)
        
        shinyjs::delay(1000, {
          attempt_draft_load(retry_count = 0, max_retries = 5)
        })
      } else {
        message("â†’ Skipping draft load (already loaded or not logged in)")
      }
    }
    
    
    
    if (user_logged_in() && user_role() == "admin") {
      if (current_tab == "admin_invitations") {
        message("â†’ Admin invitations tab - refreshing projects")
        project_data_changed(project_data_changed() + 1)
      }
      
      if (current_tab == "admin_user_export") {
        message("â†’ User export tab - refreshing users")
        responses_data_changed(responses_data_changed() + 1)
      }
      
      if (current_tab == "labor_leiter_summary") {
        message("â†’ Summary tab - refreshing data")
        project_data_changed(project_data_changed() + 1)
        responses_data_changed(responses_data_changed() + 1)
      }
      
      if (current_tab == "dashboard") {
        message("â†’ Dashboard tab - refreshing all data")
        project_data_changed(project_data_changed() + 1)
        responses_data_changed(responses_data_changed() + 1)
      }
    }
    
    #------------------------- 5. UPDATE LAST TAB TRACKER----------------------
    
    last_tab(current_tab)
    
  }, ignoreInit = TRUE)
  
  # âœ… REMOVED: duplicate "RESET DRAFT FLAG WHEN LEAVING FRAGEBOGEN" block that
  # used to sit here. It duplicated a second last_tab <- reactiveVal(NULL) and
  # a second observeEvent(input$sidebar_menu, {...}) doing overlapping work
  # with the master handler above - both firing on every tab change, causing
  # duplicate/conflicting draft-load attempts and confusing console output.
  # The master handler above already covers everything this one did.
  
  observe({
    req(input$antworten_project_selector)
    if (!is.null(input$antworten_project_selector) &&
        input$antworten_project_selector != "") {
      shinyjs::enable("downloadZusammenfassung")
    } else {
      shinyjs::disable("downloadZusammenfassung")
    }
  })
  
  
  #--------------Helper: Get Question-Level Statistics for PDF-------------------
  
  get_question_level_statistics <- function(project_id,
                                            questions_list,
                                            section_name) {
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con), add = TRUE)
    
    qids <- sapply(questions_list, function(q)
      q$id)
    qids_quoted <- paste0("'", qids, "'", collapse = ", ")
    
    query <- sprintf(
      "
    SELECT
      r.question_id,
      r.response_value as rating,
      SUM(COALESCE(CAST(qd.answers::json->>'group_size' AS INTEGER), 1)) as count
    FROM responses r
    JOIN users u ON u.id = r.user_id
    LEFT JOIN questionnaire_drafts qd
      ON u.id::text = qd.user_id::text
      AND qd.project_id::text = r.project_id::text
      AND qd.questionnaire_id = 'peer_review'
    WHERE r.project_id::text = '%s'
      AND r.assessment_type = 'selbstbewertung'
      AND r.question_id IN (%s)
      AND r.response_value != ''
      AND r.response_value != 'N/A'
    GROUP BY r.question_id, r.response_value
    ORDER BY r.question_id, r.response_value
  ",
      as.character(project_id),
      qids_quoted
    )
    
    result <- DBI::dbGetQuery(con, query)
    
    # Create full data with question labels
    full_data <- data.frame(
      Section = section_name,
      question_id = qids,
      Frage = sapply(questions_list, function(q)
        q$label),
      stringsAsFactors = FALSE
    )
    
    # Format statistics as readable text
    if (nrow(result) > 0) {
      stats_by_question <- split(result, result$question_id)
      
      full_data$Statistik <- sapply(full_data$question_id, function(qid) {
        stats <- stats_by_question[[qid]]
        if (!is.null(stats) && nrow(stats) > 0) {
          parts <- sapply(1:nrow(stats), function(i) {
            # âœ… FIX: Use %.0f instead of %d
            sprintf("Bewertung %s: %.0f Personen",
                    stats$rating[i],
                    as.numeric(stats$count[i]))
          })
          paste(parts, collapse = ", ")
        } else {
          "â€”"
        }
      })
    } else {
      full_data$Statistik <- "â€”"
    }
    
    return(full_data[, c("Section", "question_id", "Frage", "Statistik")])
  }
  
  #--------------Helper: Get Berufsgruppe Averages for PDF----------------------
  
  get_berufsgruppe_averages <- function(project_id,
                                        questions_list,
                                        section_name) {
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con), add = TRUE)
    
    qids <- sapply(questions_list, function(q)
      q$id)
    qids_quoted <- paste0("'", qids, "'", collapse = ", ")
    
    query <- sprintf(
      "
    SELECT
      r.question_id,
      COALESCE(qd.answers::json->>'Berufsgruppe', 'Nicht angegeben') as berufsgruppe,
      ROUND(
        SUM(CAST(r.response_value AS NUMERIC) * COALESCE(CAST(qd.answers::json->>'group_size' AS INTEGER), 1)) /
        SUM(COALESCE(CAST(qd.answers::json->>'group_size' AS INTEGER), 1)),
        1
      ) as avg_rating,
      SUM(COALESCE(CAST(qd.answers::json->>'group_size' AS INTEGER), 1)) as group_count
    FROM responses r
    JOIN users u ON u.id = r.user_id
    LEFT JOIN questionnaire_drafts qd
      ON u.id::text = qd.user_id::text
      AND qd.project_id::text = r.project_id::text
      AND qd.questionnaire_id = 'peer_review'
    WHERE r.project_id::text = '%s'
      AND r.assessment_type = 'selbstbewertung'
      AND r.question_id IN (%s)
      AND r.response_value != ''
      AND r.response_value != 'N/A'
      AND r.response_value ~ '^[0-9]+$'
    GROUP BY r.question_id, COALESCE(qd.answers::json->>'Berufsgruppe', 'Nicht angegeben')
    ORDER BY r.question_id, berufsgruppe
  ",
      as.character(project_id),
      qids_quoted
    )
    
    result <- DBI::dbGetQuery(con, query)
    
    # Create full data
    full_data <- data.frame(
      Section = section_name,
      question_id = qids,
      Frage = sapply(questions_list, function(q)
        q$label),
      stringsAsFactors = FALSE
    )
    
    # Format group averages
    if (nrow(result) > 0) {
      groups_by_question <- split(result, result$question_id)
      
      full_data$Berufsgruppen <- sapply(full_data$question_id, function(qid) {
        groups <- groups_by_question[[qid]]
        if (!is.null(groups) && nrow(groups) > 0) {
          parts <- sapply(1:nrow(groups), function(i) {
            # âœ… FIX: Use %.0f instead of %d
            sprintf(
              "%s: Ã˜ %.1f (n=%.0f)",
              groups$berufsgruppe[i],
              as.numeric(groups$avg_rating[i]),
              as.numeric(groups$group_count[i])
            )
          })
          paste(parts, collapse = "; ")
        } else {
          "â€”"
        }
      })
    } else {
      full_data$Berufsgruppen <- "â€”"
    }
    
    return(full_data[, c("Section", "question_id", "Frage", "Berufsgruppen")])
  }
  
  
  #--------------Helper: Get Selbstbewertung Text Responses for PDF-----------
  
  get_selbstbewertung_text_responses <- function(project_id,
                                                 questions_list,
                                                 section_name) {
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con), add = TRUE)
    
    qids <- sapply(questions_list, function(q)
      q$id)
    qids_quoted <- paste0("'", qids, "'", collapse = ", ")
    
    # âœ… DISTINCT ON deduplicates at DB level â€” one row per user+question
    query <- sprintf(
      "
    SELECT
      question_id,
      text_value,
      group_size
    FROM (
      SELECT DISTINCT ON (r.user_id, r.question_id)
        r.question_id,
        r.text_value,
        COALESCE(CAST(qd.answers::json->>'group_size' AS INTEGER), 1) as group_size
      FROM responses r
      JOIN users u ON u.id = r.user_id
      LEFT JOIN questionnaire_drafts qd
        ON u.id::text = qd.user_id::text
        AND qd.project_id::text = r.project_id::text
        AND qd.questionnaire_id = 'peer_review'
      WHERE r.project_id::text = '%s'
        AND r.assessment_type = 'selbstbewertung'
        AND r.question_id IN (%s)
        AND r.text_value IS NOT NULL
        AND r.text_value != ''
      ORDER BY r.user_id, r.question_id, r.created_at DESC
    ) deduped
    ORDER BY question_id, text_value
  ",
      as.character(project_id),
      qids_quoted
    )
    
    result <- DBI::dbGetQuery(con, query)
    
    full_data <- data.frame(
      Section = section_name,
      question_id = qids,
      Frage = sapply(questions_list, function(q)
        q$label),
      stringsAsFactors = FALSE
    )
    
    if (nrow(result) > 0) {
      texts_by_question <- split(result, result$question_id)
      
      full_data$Textantworten <- sapply(full_data$question_id, function(qid) {
        texts <- texts_by_question[[qid]]
        if (!is.null(texts) && nrow(texts) > 0) {
          # âœ… aggregate sums group_size across UNIQUE users only (already deduped)
          text_agg <- aggregate(group_size ~ text_value,
                                data = texts,
                                FUN = sum)
          text_agg <- text_agg[order(text_agg$text_value), ]
          
          parts <- sapply(1:nrow(text_agg), function(i) {
            count <- as.numeric(text_agg$group_size[i])
            if (count > 1) {
              sprintf("Ã—%.0f %s", count, text_agg$text_value[i])
            } else {
              sprintf("Ã—1 %s", text_agg$text_value[i])
            }
          })
          paste(parts, collapse = ";")
        } else {
          "â€”"
        }
      })
    } else {
      full_data$Textantworten <- "â€”"
    }
    
    return(full_data[, c("Section", "question_id", "Frage", "Textantworten")])
  }
  
  #-------------------------- SPIDER PLOTS - All Topics----------------------------
  
  
  get_weighted_spider_data_local <- function(project_id,
                                             topic_key,
                                             questionnaires,
                                             binary_qnums = integer()) {
    message(">>> get_weighted_spider_data_local called")
    message("    project_id: ", project_id)
    message("    topic_key: ", topic_key)
    
    question_list <- questionnaires[[topic_key]]
    
    if (is.null(question_list)) {
      message("    ERROR: No question list for topic: ", topic_key)
      return(NULL)
    }
    
    message("    Questions found: ", length(question_list))
    
    # Filter binary questions
    if (length(binary_qnums) > 0) {
      question_list <- Filter(function(q)
        ! (q$number %in% binary_qnums), question_list)
      message("    After binary filter: ", length(question_list))
    }
    
    if (length(question_list) == 0) {
      message("    No questions after filtering")
      return(NULL)
    }
    
    question_ids <- sapply(question_list, function(q)
      q$id)
    message("    Question IDs: ", paste(question_ids, collapse = ", "))
    
    # Get responses
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con))
    
    sql <- sprintf(
      "SELECT user_id, question_id, response_value::numeric, group_size
     FROM responses
     WHERE project_id = $1
       AND assessment_type = 'selbstbewertung'
       AND question_id IN (%s)
       AND response_value IS NOT NULL
       AND response_value != ''",
      paste0("'", question_ids, "'", collapse = ", ")
    )
    
    message("    Executing query...")
    responses <- DBI::dbGetQuery(con, sql, params = list(project_id))
    message("    Raw responses: ", nrow(responses))
    
    if (nrow(responses) == 0) {
      message("    No responses found")
      return(NULL)
    }
    
    # Expand by group size
    message("    Expanding by group_size...")
    expanded_list <- lapply(1:nrow(responses), function(i) {
      row <- responses[i, ]
      gs <- if (is.na(row$group_size) ||
                row$group_size < 1)
        1
      else
        as.integer(row$group_size)
      
      data.frame(
        user_id = rep(row$user_id, gs),
        question_id = rep(row$question_id, gs),
        response_value = rep(as.numeric(row$response_value), gs)
      )
    })
    
    expanded <- do.call(rbind, expanded_list)
    message("    Expanded to: ", nrow(expanded), " rows")
    
    # Calculate means
    means <- expanded %>%
      group_by(question_id) %>%
      summarise(mean_value = mean(response_value, na.rm = TRUE),
                .groups = "drop")
    
    message("    Means calculated for ", nrow(means), " questions")
    
    # Map to question order
    values <- sapply(question_list, function(q) {
      row <- means[means$question_id == q$id, ]
      if (nrow(row) > 0)
        row$mean_value
      else
        0
    })
    
    labels <- sapply(question_list, function(q)
      as.character(q$number))
    
    message("    Values: ", paste(round(values, 2), collapse = ", "))
    message("    Labels: ", paste(labels, collapse = ", "))
    message(">>> get_weighted_spider_data_local END")
    
    return(list(values = values, labels = labels))
  }
  
