  #----------------helper function to generate spider plot images-----------------
  
  # Helper function to create spider plot and save as PNG
  create_spider_plot_image <- function(project_id,
                                       topic_key,
                                       questions_list,
                                       title,
                                       color,
                                       binary_qnums = integer()) {
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con))
    
    # Filter binary questions if needed
    questions_filtered <- if (length(binary_qnums) > 0) {
      Filter(function(q)
        ! (q$number %in% binary_qnums), questions_list)
    } else {
      questions_list
    }
    
    question_ids <- sapply(questions_filtered, function(q)
      q$id)
    
    # Get responses
    responses <- DBI::dbGetQuery(
      con,
      sprintf(
        "SELECT question_id, response_value::numeric as rv
       FROM responses
       WHERE project_id = $1
         AND assessment_type = 'selbstbewertung'
         AND question_id IN (%s)
         AND response_value IS NOT NULL
         AND response_value != ''",
        paste0("'", question_ids, "'", collapse = ", ")
      ),
      params = list(project_id)
    )
    
    if (nrow(responses) == 0) {
      return(NULL)
    }
    
    # Calculate means
    means <- responses %>%
      group_by(question_id) %>%
      summarise(mean_value = mean(rv, na.rm = TRUE),
                .groups = "drop")
    
    # Map to questions
    values <- sapply(questions_filtered, function(q) {
      row <- means[means$question_id == q$id, ]
      if (nrow(row) > 0)
        row$mean_value
      else
        NA
    })
    
    labels <- sapply(questions_filtered, function(q)
      as.character(q$number))
    
    # Remove NAs
    valid_idx <- !is.na(values)
    values <- values[valid_idx]
    labels <- labels[valid_idx]
    
    if (length(values) == 0) {
      return(NULL)
    }
    
    # Create plotly object
    p <- plotly::plot_ly(
      type = 'scatterpolar',
      mode = 'lines+markers',
      r = values,
      theta = labels,
      fill = 'toself',
      fillcolor = paste0(color, ", 0.3)"),
      line = list(color = color, width = 2)
    ) %>%
      plotly::layout(title = title, polar = list(radialaxis = list(
        visible = TRUE, range = c(0, 5)
      )))
    
    return(p)
  }
  
  # Helper to get topic responses as data frame
  get_topic_responses_df <- function(project_id,
                                     topic_prefix,
                                     questions_list) {
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con), add = TRUE)  # âœ… also fixed missing add=TRUE
    
    df <- DBI::dbGetQuery(
      con,
      sprintf(
        "SELECT DISTINCT ON (u.username, r.question_id)
         u.username, r.question_id, r.response_value, r.text_value
       FROM responses r
       JOIN users u ON u.id = r.user_id
       WHERE r.assessment_type = 'selbstbewertung'
         AND r.project_id = $1
         AND r.question_id LIKE '%s%%'
       ORDER BY u.username, r.question_id, r.created_at DESC",
        topic_prefix
      ),
      params = list(project_id)
    )
    
    if (nrow(df) > 0) {
      df$question <- sapply(df$question_id, function(qid) {
        q <- Find(function(x)
          x$id == qid, questions_list)
        if (!is.null(q))
          q$label
        else
          qid
      })
      df <- df[, c("username", "question", "response_value", "text_value")]
      colnames(df) <- c("Nutzer", "Frage", "Bewertung", "Freitext")
    }
    
    return(df)
  }
  
  
