  #--------------LEADING PEER DASHBOARD - CONTENT GENERATION------------------
  
  # Helper to calculate WEIGHTED stats
  calc_weighted_stats <- function(df, questions_list, project_id) {
    if (is.null(df) || nrow(df) == 0) {
      return(list())
    }
    
    stats <- list()
    
    for (q in questions_list) {
      qid <- q$id
      values_df <- df[df$question_id == qid &
                        df$response_value != "" &
                        df$response_value != "N/A", ]
      
      if (nrow(values_df) > 0) {
        if (!"group_size" %in% colnames(values_df)) {
          values_df$group_size <- 1
        }
        values_df$group_size[is.na(values_df$group_size)] <- 1
        
        values_df$response_numeric <- suppressWarnings(as.numeric(values_df$response_value))
        values_df <- values_df[!is.na(values_df$response_numeric), ]
        
        if (nrow(values_df) > 0) {
          weighted_sum <- sum(values_df$response_numeric * values_df$group_size,
                              na.rm = TRUE)
          total_people <- sum(values_df$group_size, na.rm = TRUE)
          
          if (total_people > 0) {
            weighted_mean <- weighted_sum / total_people
            stats[[qid]] <- list(mean = weighted_mean, n = total_people)
          }
        }
      }
    }
    
    return(stats)
  }
  
  # âœ… Get berufsgruppe radar data with weighted stats
  get_berufsgruppe_radar_data_weighted <- function(project_id, questions, binary_qnums = integer()) {
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con), add = TRUE)
    
    qids <- sapply(questions, function(q)
      q$id)
    qids_quoted <- paste0("'", qids, "'", collapse = ", ")
    
    all_possible_bg <- c("Ã„rzte", "IT", "MTL", "Wissenschaftler(-in)", "Sonstiges")
    
    berufsgruppen_in_project <- DBI::dbGetQuery(
      con,
      paste0(
        "
    SELECT DISTINCT COALESCE(qd.answers::json->>'Berufsgruppe', 'Sonstiges') as berufsgruppe
    FROM questionnaire_drafts qd
    WHERE qd.project_id::text = '",
        project_id,
        "'
      AND qd.questionnaire_id = 'peer_review'
  "
      )
    )$berufsgruppe
    
    all_berufsgruppen <- sort(intersect(all_possible_bg, berufsgruppen_in_project))
    if (length(all_berufsgruppen) == 0) {
      all_berufsgruppen <- sort(all_possible_bg)
    }
    
    # Get weighted DATA with DISTINCT ON
    data_query <- paste0(
      "
    SELECT
      COALESCE(qd.answers::json->>'Berufsgruppe', 'Sonstiges') as berufsgruppe,
      r.question_id,
      SUM(
        CASE
          WHEN r.response_value ~ '^[0-9]+$'
          THEN CAST(r.response_value AS NUMERIC) * COALESCE(CAST(qd.answers::json->>'group_size' AS INTEGER), 1)
          ELSE 0
        END
      ) / NULLIF(SUM(COALESCE(CAST(qd.answers::json->>'group_size' AS INTEGER), 1)), 0) as weighted_mean
    FROM (
      SELECT DISTINCT ON (r.user_id, r.question_id)
        r.*
      FROM responses r
      WHERE r.project_id::text = '",
      project_id,
      "'
        AND r.assessment_type = 'selbstbewertung'
        AND r.question_id IN (",
      qids_quoted,
      ")
      ORDER BY r.user_id, r.question_id, r.created_at DESC NULLS LAST
    ) r
    LEFT JOIN questionnaire_drafts qd
      ON r.user_id::text = qd.user_id::text
      AND qd.project_id::text = r.project_id::text
      AND qd.questionnaire_id = 'peer_review'
    WHERE r.response_value != ''
      AND r.response_value != 'N/A'
    GROUP BY COALESCE(qd.answers::json->>'Berufsgruppe', 'Sonstiges'), r.question_id
    ORDER BY berufsgruppe, r.question_id
  "
    )
    
    result <- DBI::dbGetQuery(con, data_query)
    
    # Create wide format with ALL berufsgruppen
    berufsgruppen_ordered <- all_berufsgruppen
    wide_data <- data.frame(berufsgruppe = berufsgruppen_ordered, stringsAsFactors = FALSE)
    
    for (qid in qids) {
      wide_data[[qid]] <- NA_real_
    }
    
    if (nrow(result) > 0) {
      for (i in 1:nrow(result)) {
        bg <- result[i, "berufsgruppe"]
        qid <- result[i, "question_id"]
        val <- result[i, "weighted_mean"]
        
        bg_idx <- which(wide_data$berufsgruppe == bg)
        if (length(bg_idx) > 0) {
          wide_data[bg_idx, qid] <- val
        }
      }
    }
    
    return(wide_data)
  }
  
  #============================================================================
  # CREATE DASHBOARD ROWS
  #============================================================================
  
  create_dashboard_rows <- function(df,
                                    questions_list,
                                    plot_output_id,
                                    berufsgruppe_breakdown,
                                    project_id) {
    question_rows <- lapply(seq_along(questions_list), function(idx) {
      q <- questions_list[[idx]]
      qid <- q$id
      q_num <- q$number
      
      selb_rows <- df[df$question_id == qid &
                        df$response_value != "", ]
      
      selb_display <- if (nrow(selb_rows) > 0) {
        if (!"group_size" %in% colnames(selb_rows)) {
          selb_rows$group_size <- 1
        }
        selb_rows$group_size[is.na(selb_rows$group_size)] <- 1
        
        # âœ… Dedupe to one row per user (a user can have multiple raw rows
        # from resubmission) BEFORE counting, then weight by that row's
        # group_size instead of n_distinct(user_id) - the same "count real
        # people, not raw submissions" fix already applied to the PDF
        # reports' build_side()/get_enhanced_stats(). Reused below for the
        # "Teilnehmer" total and the text-comment counts too, so all three
        # numbers on this row are now consistent with each other.
        unique_users <- selb_rows[!duplicated(selb_rows$user_id), ]
        
        # N/A is counted too (it used to be dropped here, so nobody could
        # see how many people answered "nicht anwendbar"), and the count is
        # always shown - also for a single person (x1) - so a bare number
        # never leaves the reader guessing what it means.
        rating_counts <- unique_users %>%
          dplyr::filter(!is.na(response_value), response_value != "") %>%
          dplyr::group_by(response_value) %>%
          dplyr::summarise(n_users = sum(group_size, na.rm = TRUE), .groups = "drop")

        rating_counts_list <- setNames(rating_counts$n_users, rating_counts$response_value)

        rating_display <- tags$div(class = "rating-inline", lapply(c("N/A", "1", "2", "3", "4", "5"), function(j) {
          count <- rating_counts_list[as.character(j)]
          count <- if (is.na(count)) 0 else as.integer(count)

          if (count > 0) {
            tags$span(class = "rating-active rating-with-count",
                      title = paste0(count, if (count == 1) " Person hat " else " Personen haben ", j, " gewÃ¤hlt"),
                      j,
                      tags$sup(class = "rating-count", paste0("Ã—", count)))
          } else {
            tags$span(class = "rating-inactive", j)
          }
        }))
        
        total_people <- sum(unique_users$group_size, na.rm = TRUE)
        
        # âœ… CHANGED: "Teilnehmer" now means total people represented
        # (group_size-weighted), not the raw submission/login count. Showing
        # both numbers side by side ("2 Teilnehmer (n=3)") was confusing -
        # this is the number that actually matters for a peer review: how
        # many people's input this represents.
        respondent_info <- if (total_people > 0) {
          tags$div(
            class = "respondent-info",
            icon("users"),
            paste0(
              " ",
              total_people,
              " Teilnehmer"
            )
          )
        } else {
          NULL
        }
        
        texts_with_user <- unique_users[unique_users$text_value != "" &
                                          !is.na(unique_users$text_value), c("text_value", "user_id", "group_size")]
        
        text_display <- if (nrow(texts_with_user) > 0) {
          # \u2705 CHANGED: weight by group_size (real people behind that one
          # submission), not n_distinct(user_id) - and always show the
          # "xN" badge (even x1), so every comment clearly shows how many
          # people are behind it, not just the ones with more than one.
          text_counts <- texts_with_user %>%
            dplyr::group_by(text_value) %>%
            dplyr::summarise(n_users = sum(group_size, na.rm = TRUE), .groups = "drop")
          
          tags$div(class = "selbst-text-container", lapply(1:nrow(text_counts), function(i) {
            txt <- text_counts$text_value[i]
            count <- text_counts$n_users[i]
            tags$div(
              class = "selbst-text-item",
              icon("comment"),
              tags$span(class = "text-count-badge", paste0("\u00d7", count)),
              txt
            )
          }))
        } else {
          NULL
        }
        
        tags$div(rating_display, respondent_info, text_display)
      } else {
        tags$span(class = "no-data", "\u2014")
      }
      
      if (idx == 1) {
        topic_prefix <- substr(questions_list[[1]]$id, 1, 1)
        stats_table <- create_berufsgruppe_stats_table_complete(project_id, questions_list, topic_prefix)
        
        tables_container <- tags$div(class = "berufsgruppe-tables-container", stats_table)
        
        tags$tr(
          class = "dashboard-row",
          tags$td(class = "dashboard-col-question", tags$strong(paste0(q_num, ". ")), q$label),
          tags$td(class = "dashboard-col-selbst", selb_display),
          tags$td(
            class = "dashboard-col-plot",
            rowspan = length(questions_list),
            style = "vertical-align: top; padding: 10px 8px;",
            tables_container,
            plotOutput(plot_output_id, height = "600px")
          )
        )
      } else {
        tags$tr(
          class = "dashboard-row",
          tags$td(class = "dashboard-col-question", tags$strong(paste0(q_num, ". ")), q$label),
          tags$td(class = "dashboard-col-selbst", selb_display)
        )
      }
    })
    
    do.call(tagList, question_rows)
  }
  
  # â”€â”€ Fremdbewertung-Uebersicht rows, same visual language (rating badges,
  # comment list) as create_dashboard_rows() above, but WITHOUT any
  # group_size weighting - a Fremdbewertung row is always one individual
  # reviewer (leading_peer/co_peer), never a group submission, so a plain
  # reviewer count is already correct. Each comment is tagged with the
  # reviewer's name instead of a "xN" badge, since there is no group to
  # count - showing *who* said it is the useful equivalent here. â”€â”€
  create_dashboard_rows_fremd <- function(df, questions_list) {
    # âœ… Anonymize reviewers as "Peer 1" / "Peer 2" / ... instead of showing
    # their real username next to each comment. Built once over the WHOLE
    # topic (not per question) so the same reviewer keeps the same number
    # across every question row in this table, ordered by user_id so it's
    # stable across re-renders.
    peer_ids <- sort(unique(df$user_id[!is.na(df$user_id)]))
    peer_label_map <- setNames(paste0("Peer ", seq_along(peer_ids)), as.character(peer_ids))

    question_rows <- lapply(seq_along(questions_list), function(idx) {
      q <- questions_list[[idx]]
      qid <- q$id
      q_num <- q$number
      
      rows <- df[df$question_id == qid & df$response_value != "", ]
      
      fremd_display <- if (nrow(rows) > 0) {
        rating_counts <- rows %>%
          dplyr::filter(response_value != "N/A",
                        !is.na(response_value),
                        response_value != "") %>%
          dplyr::group_by(response_value) %>%
          dplyr::summarise(n_reviewers = dplyr::n_distinct(user_id), .groups = "drop") %>%
          dplyr::arrange(as.numeric(response_value))
        
        rating_counts_list <- setNames(rating_counts$n_reviewers, rating_counts$response_value)
        
        rating_display <- tags$div(class = "rating-inline", lapply(c("N/A", "1", "2", "3", "4", "5"), function(j) {
          count <- rating_counts_list[as.character(j)]
          count <- if (is.na(count)) 0 else as.integer(count)
          if (count > 0) {
            if (count == 1) {
              tags$span(class = "rating-active", j)
            } else {
              tags$span(class = "rating-active rating-with-count",
                        j, tags$sup(class = "rating-count", paste0("Ã—", count)))
            }
          } else {
            tags$span(class = "rating-inactive", j)
          }
        }))
        
        n_reviewers <- length(unique(rows$user_id))
        respondent_info <- if (n_reviewers > 0) {
          tags$div(class = "respondent-info", icon("user-check"), paste0(" ", n_reviewers, " Reviewer"))
        } else {
          NULL
        }
        
        texts <- rows[rows$text_value != "" & !is.na(rows$text_value), c("text_value", "user_id")]
        text_display <- if (nrow(texts) > 0) {
          tags$div(class = "selbst-text-container", lapply(seq_len(nrow(texts)), function(i) {
            peer_label <- peer_label_map[[as.character(texts$user_id[i])]]
            tags$div(
              class = "selbst-text-item",
              icon("comment"),
              if (!is.null(peer_label)) tags$span(class = "text-count-badge", peer_label),
              texts$text_value[i]
            )
          }))
        } else {
          NULL
        }
        
        tags$div(rating_display, respondent_info, text_display)
      } else {
        tags$span(class = "no-data", "â€”")
      }
      
      tags$tr(
        class = "dashboard-row",
        tags$td(class = "dashboard-col-question", tags$strong(paste0(q_num, ". ")), q$label),
        tags$td(class = "dashboard-col-selbst", fremd_display)
      )
    })
    
    do.call(tagList, question_rows)
  }
  
  # Shared query behind every Fremdbewertung-Uebersicht tab: one row per
  # (reviewer, question), deduplicated to each reviewer's latest submission
  # so a resubmission never gets counted twice.
  get_fremdbewertung_overview_df <- function(project_id, topic_prefix) {
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con), add = TRUE)
    DBI::dbGetQuery(
      con,
      "
      SELECT question_id, response_value, text_value, user_id, username
      FROM (
        SELECT DISTINCT ON (r.user_id, r.question_id)
          r.question_id, r.response_value, r.text_value, r.user_id, u.username
        FROM responses r
        JOIN users u ON u.id = r.user_id
        WHERE r.project_id::text = $1::text
          AND r.assessment_type = 'fremdbewertung'
          AND r.question_id ~ $2
        ORDER BY r.user_id, r.question_id, r.created_at DESC
      ) sub
      ORDER BY question_id, username
      ",
      params = list(as.character(project_id), paste0("^", topic_prefix, "[0-9]"))
    )
  }
  
  # Converts the app's own "**bold**" / "- " bullet markup (the same
  # convention .pdfreport_layout_text() parses for the PDF reports) into
  # simple HTML, for showing the same comparison-cell text live in the
  # dashboard instead of a PDF.
  .markup_to_html <- function(text) {
    if (is.null(text) || is.na(text) || !nzchar(text)) return("")
    lines <- strsplit(text, "\n")[[1]]
    html_lines <- vapply(lines, function(ln) {
      bullet <- grepl("^- ", ln)
      if (bullet) ln <- sub("^- ", "â€¢ ", ln)
      ln <- gsub("\\*\\*(.*?)\\*\\*", "<strong>\\1</strong>", ln)
      ln <- gsub("\\+\\+(.*?)\\+\\+", "<u>\\1</u>", ln)
      ln
    }, character(1))
    paste(html_lines, collapse = "<br/>")
  }
  
  # Shared Selbst-vs-Fremd comparison table builder, used by both the
  # Vergleichstabelle PDF (generate_comparison_pdf) and the live
  # "Vergleich Selbst- und Fremdbewertung" dashboard tab, so both stay
  # consistent (including the group_size weighting fix). Returns a
  # data.frame(Frage, Selbstbewertung, Fremdbewertung) with **bold**/"- "
  # markup in the two bewertung columns - the PDF renders that markup
  # itself, the live tab converts it via .markup_to_html().
  build_comparison_rows_shared <- function(project_id, questions, topic_prefix) {
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con), add = TRUE)
    
    selbst_data <- DBI::dbGetQuery(con, "
      SELECT r.question_id, r.response_value AS rating, r.text_value AS comment,
             COALESCE(CAST(qd.answers::json->>'group_size' AS INTEGER), 1) AS group_size
      FROM responses r
      LEFT JOIN questionnaire_drafts qd
        ON r.user_id::text = qd.user_id::text
       AND r.project_id::text = qd.project_id::text
       AND qd.questionnaire_id = 'peer_review'
      WHERE r.project_id = $1
        AND r.assessment_type = 'selbstbewertung'
        AND r.question_id ~ $2
        AND (r.response_value IS NOT NULL OR r.text_value IS NOT NULL)
      ORDER BY r.question_id
    ", params = list(as.character(project_id), paste0("^", topic_prefix, "[0-9]")))
    
    fremd_data <- DBI::dbGetQuery(con, "
      SELECT r.question_id, r.response_value AS rating, r.text_value AS comment
      FROM responses r
      WHERE r.project_id = $1
        AND r.assessment_type = 'fremdbewertung'
        AND r.question_id ~ $2
        AND (r.response_value IS NOT NULL OR r.text_value IS NOT NULL)
      ORDER BY r.question_id
    ", params = list(as.character(project_id), paste0("^", topic_prefix, "[0-9]")))
    
    build_side <- function(rows, who_label) {
      if (!nrow(rows)) return("-")
      gs <- if ("group_size" %in% names(rows)) {
        g <- suppressWarnings(as.numeric(rows$group_size))
        g[is.na(g) | g < 1] <- 1
        g
      } else {
        rep(1, nrow(rows))
      }
      total <- sum(gs)
      
      ratings <- rows$rating
      ratings[is.na(ratings) | !nzchar(ratings)] <- "N/A"
      rtbl <- tapply(gs, ratings, sum)
      rdist <- paste(sapply(names(rtbl), function(r) {
        cnt <- as.integer(rtbl[[r]])
        if (cnt == 1) r else paste0(r, " (x", cnt, ")")
      }), collapse = ", ")
      
      valid_idx <- !is.na(rows$rating) & nzchar(rows$rating) &
        !is.na(suppressWarnings(as.numeric(rows$rating)))
      
      lines <- if (any(valid_idx)) {
        valid_r  <- as.numeric(rows$rating[valid_idx])
        valid_gs <- gs[valid_idx]
        avg <- sum(valid_r * valid_gs) / sum(valid_gs)
        sprintf("**%s: %d | Durchschnitt: %.2f**", who_label, total, avg)
      } else {
        sprintf("**%s: %d**", who_label, total)
      }
      lines <- c(lines, sprintf("**Verteilung: %s**", rdist))
      
      text_idx <- which(!is.na(rows$comment) & nzchar(trimws(rows$comment)))
      for (i in text_idx) {
        lines <- c(lines, paste0("- [x", gs[i], "] ", trimws(rows$comment[i])))
      }
      paste(lines, collapse = "\n")
    }
    
    sorted_questions <- questions[order(sapply(questions, function(q) q$number))]
    rows <- lapply(sorted_questions, function(q) {
      sr <- selbst_data[selbst_data$question_id == q$id, ]
      fr <- fremd_data[fremd_data$question_id == q$id, ]
      data.frame(
        Frage = paste0(q$number, ". ", q$label),
        Selbstbewertung = build_side(sr, "Teilnehmer"),
        Fremdbewertung = build_side(fr, "Reviewer"),
        stringsAsFactors = FALSE
      )
    })
    do.call(rbind, rows)
  }
  
  #============================================================================
  # CREATE STATS TABLE WITH BINARY QUESTIONS
  #============================================================================
  
  create_berufsgruppe_stats_table_complete <- function(project_id,
                                                       questions_list,
                                                       topic_prefix = NULL) {
    if (is.null(topic_prefix)) {
      topic_prefix <- substr(questions_list[[1]]$id, 1, 1)
    }
    
    binary_qnums <- c(10, 20, 24)
    questions_filtered <- Filter(function(q)
      ! (q$number %in% binary_qnums), questions_list)
    
    all_question_ids <- sapply(questions_filtered, function(q)
      q$id)
    qids_quoted <- paste0("'", all_question_ids, "'", collapse = ", ")
    
    data <- get_berufsgruppe_radar_data_weighted(project_id, questions_filtered, integer())
    
    if (is.null(data) || nrow(data) == 0) {
      return(NULL)
    }
    
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con), add = TRUE)
    
    berufsgruppen <- data$berufsgruppe
    numeric_data <- data[, -1, drop = FALSE]
    question_ids_in_data <- colnames(numeric_data)
    
    id_to_number <- setNames(
      sapply(questions_filtered, function(q)
        as.character(q$number)),
      sapply(questions_filtered, function(q)
        q$id)
    )
    
    question_numbers <- sapply(question_ids_in_data, function(qid) {
      if (qid %in% names(id_to_number))
        id_to_number[[qid]]
      else
        qid
    })
    
    topic_averages <- rowMeans(numeric_data, na.rm = TRUE)
    
    # GET TRUE GESAMT N
    # âœ… FIXED: was COUNT(DISTINCT user_id) - a plain login count that
    # ignores group_size entirely, so a respondent who filled the form out
    # on behalf of a group of 2 (group_size=2) was only counted as 1. This
    # deduplicates to one row per user first (DISTINCT ON), THEN sums each
    # user's own group_size exactly once - consistent with the per-question
    # "Teilnehmer (n=...)" weighting used elsewhere.
    gesamt_n_query <- paste0(
      "
  SELECT COALESCE(SUM(gs), 0) as n
  FROM (
    SELECT DISTINCT ON (r.user_id)
      r.user_id,
      COALESCE(CAST(qd.answers::json->>'group_size' AS INTEGER), 1) as gs
    FROM responses r
    LEFT JOIN questionnaire_drafts qd
      ON r.user_id::text = qd.user_id::text
      AND r.project_id::text = qd.project_id::text
      AND qd.questionnaire_id = 'peer_review'
    WHERE r.project_id::text = '",
      project_id,
      "'
      AND r.assessment_type = 'selbstbewertung'
      AND r.question_id LIKE '",
      topic_prefix,
      "%'
      AND r.response_value != ''
  ) sub
"
    )
    
    total_people <- DBI::dbGetQuery(con, gesamt_n_query)$n
    if (is.na(total_people))
      total_people <- 0
    
    # GET N FOR EACH BERUFSGRUPPE
    # âœ… FIXED: same issue - was COUNT(DISTINCT r.user_id), now sums each
    # user's own group_size exactly once via DISTINCT ON.
    get_n_for_berufsgruppe <- function(con, project_id, bg, topic_prefix) {
      result <- DBI::dbGetQuery(
        con,
        "
    SELECT COALESCE(SUM(gs), 0) as n
    FROM (
      SELECT DISTINCT ON (r.user_id)
        r.user_id,
        COALESCE(CAST(qd.answers::json->>'group_size' AS INTEGER), 1) as gs,
        COALESCE(CAST(qd.answers::json->>'Berufsgruppe' AS TEXT), 'Sonstiges') as berufsgruppe
      FROM responses r
      LEFT JOIN questionnaire_drafts qd
        ON r.user_id::text = qd.user_id::text
        AND r.project_id::text = qd.project_id::text
        AND qd.questionnaire_id = 'peer_review'
      WHERE r.project_id::text = $1
        AND r.assessment_type = 'selbstbewertung'
        AND r.question_id LIKE $2
        AND r.response_value != ''
    ) sub
    WHERE berufsgruppe = $3
  ",
        params = list(as.character(project_id), paste0(topic_prefix, "%"), bg)
      )
      
      return(if (nrow(result) > 0 &&
                 !is.na(result$n[1]))
        as.integer(result$n[1])
        else
          0L)
    }
    
    n_values <- sapply(berufsgruppen, function(bg) {
      get_n_for_berufsgruppe(con, project_id, bg, topic_prefix)
    }, USE.NAMES = FALSE)
    
    # CREATE HEADERS
    header_row <- tags$tr(
      tags$th(rowspan = 2, "Berufsgruppe"),
      tags$th(rowspan = 2, "n"),
      tags$th(
        colspan = ncol(numeric_data),
        style = "text-align: center; border-bottom: 1px solid #00508f;",
        "Durchschnitt pro Frage"
      ),
      tags$th(rowspan = 2, HTML("Ã˜ Thema<br/>(x&#772;<sub>w</sub>)"))
    )
    
    question_header_row <- tags$tr(lapply(seq_along(question_numbers), function(i) {
      qnum <- question_numbers[i]
      tags$th(style = "text-align: center; font-size: 11px; padding: 4px 6px;", qnum)
    }))
    
    # Create data rows
    data_rows <- lapply(1:nrow(data), function(i) {
      bg <- berufsgruppen[i]
      n_people <- as.integer(n_values[i])
      
      data_cells <- lapply(1:ncol(numeric_data), function(j) {
        val <- numeric_data[i, j]
        tags$td(class = "stats-question-value",
                style = "text-align: center; font-size: 12px; color: #555;",
                if (!is.na(val))
                  sprintf("%.2f", val)
                else
                  "â€”")
      })
      
      tags$tr(
        tags$td(class = "stats-label", bg),
        tags$td(
          class = "stats-n",
          style = "text-align: center; color: #1976D2; font-weight: 500;",
          tags$strong(n_people)
        ),
        data_cells,
        tags$td(
          class = "stats-topic-avg",
          style = "text-align: center; color: #1976D2; font-weight: 600; font-size: 13px; background: #f0f7ff;",
          if (!is.na(topic_averages[i]))
            sprintf("%.2f", topic_averages[i])
          else
            "â€”"
        )
      )
    })
    
    # Calculate overall averages
    overall_query <- paste0(
      "
  SELECT
    r.question_id,
    SUM(CAST(r.response_value AS NUMERIC) * COALESCE(r.group_size, 1)) /
    NULLIF(SUM(COALESCE(r.group_size, 1)), 0) as weighted_mean
  FROM responses r
  WHERE r.project_id::text = '",
      project_id,
      "'
    AND r.assessment_type = 'selbstbewertung'
    AND r.question_id IN (",
      qids_quoted,
      ")
    AND r.response_value ~ '^[0-9]+$'
  GROUP BY r.question_id
  ORDER BY r.question_id
"
    )
    
    overall_result <- DBI::dbGetQuery(con, overall_query)
    
    overall_avgs_vec <- setNames(overall_result$weighted_mean,
                                 overall_result$question_id)
    
    overall_topic_avg <- mean(overall_result$weighted_mean, na.rm = TRUE)
    
    total_cells <- lapply(question_ids_in_data, function(qid) {
      val <- overall_avgs_vec[qid]
      tags$td(style = "text-align: center; font-size: 12px; font-weight: 600;", if (!is.na(val))
        sprintf("%.2f", val)
        else
          "â€”")
    })
    
    total_row <- tags$tr(
      class = "stats-total",
      tags$td(tags$strong("Gesamt")),
      tags$td(style = "text-align: center; font-weight: 600;", tags$strong(total_people)),
      total_cells,
      tags$td(style = "text-align: center; font-weight: 600; background: #e3f2fd;", tags$strong(sprintf(
        "%.2f", overall_topic_avg
      )))
    )
    
    stats_table <- tags$div(
      class = "berufsgruppe-stats",
      tags$h4("Statistik nach Berufsgruppe - Quantitative Ergebnisse"),
      tags$div(
        style = "overflow-x: auto;",
        tags$table(
          class = "stats-detail-table",
          tags$thead(header_row, question_header_row),
          tags$tbody(data_rows, total_row)
        )
      )
    )
    
    binary_questions_list <- Filter(function(q)
      q$number %in% binary_qnums, questions_list)
    binary_table <- create_binary_table_compact(project_id, binary_questions_list, topic_prefix)
    
    tags$div(stats_table, if (!is.null(binary_table))
      binary_table)
  }
  
  # âœ… FIXED create_binary_table_compact - remove updated_at, id references
  create_binary_table_compact <- function(project_id,
                                          binary_questions_list,
                                          topic_prefix = NULL) {
    if (is.null(binary_questions_list) ||
        length(binary_questions_list) == 0) {
      return(NULL)
    }
    
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con), add = TRUE)
    
    binary_qids <- sapply(binary_questions_list, function(q)
      q$id)
    qids_quoted <- paste0("'", binary_qids, "'", collapse = ", ")
    
    # âœ… FIXED: Use DISTINCT ON to deduplicate, then sum group_size only once per user per question
    binary_query <- paste0(
      "
    SELECT
      r.question_id,
      r.response_value,
      COALESCE(qd.answers::json->>'Berufsgruppe', 'Sonstiges') as berufsgruppe,
      COALESCE(CAST(qd.answers::json->>'group_size' AS INTEGER), 1) as group_size
    FROM (
      SELECT DISTINCT ON (r.user_id, r.question_id)
        r.*
      FROM responses r
      WHERE r.project_id::text = '",
      project_id,
      "'
        AND r.assessment_type = 'selbstbewertung'
        AND r.question_id IN (",
      qids_quoted,
      ")
      ORDER BY r.user_id, r.question_id, r.created_at DESC NULLS LAST
    ) r
    LEFT JOIN questionnaire_drafts qd
      ON r.user_id::text = qd.user_id::text
      AND qd.project_id::text = r.project_id::text
      AND qd.questionnaire_id = 'peer_review'
    WHERE r.response_value IN ('Ja', 'Nein')
    ORDER BY r.question_id, berufsgruppe, r.response_value
  "
    )
    
    binary_data <- DBI::dbGetQuery(con, binary_query)
    
    if (nrow(binary_data) == 0) {
      return(NULL)
    }
    
    # Sum group_size by question, berufsgruppe, response_value
    weighted_summary <- binary_data %>%
      dplyr::group_by(question_id, berufsgruppe, response_value) %>%
      dplyr::summarise(weighted_count = sum(group_size, na.rm = TRUE),
                       .groups = "drop")
    
    # Pivot to get Ja/Nein columns
    wide_summary <- weighted_summary %>%
      tidyr::pivot_wider(
        names_from = response_value,
        values_from = weighted_count,
        values_fill = 0
      )
    
    # Get all berufsgruppen and questions
    all_bg <- c("Ã„rzte", "IT", "MTL", "Wissenschaftler(-in)", "Sonstiges")
    all_questions <- unique(binary_data$question_id)
    
    # Create rows per berufsgruppe
    table_rows <- lapply(all_bg, function(bg) {
      bg_rows <- lapply(all_questions, function(qid) {
        row_data <- wide_summary %>%
          dplyr::filter(berufsgruppe == bg, question_id == qid)
        
        if (nrow(row_data) == 0) {
          ja <- 0
          nein <- 0
        } else {
          ja <- as.integer(row_data$Ja[1] %||% 0)
          nein <- as.integer(row_data$Nein[1] %||% 0)
        }
        
        sigma <- ja + nein
        list(ja = ja,
             nein = nein,
             sigma = sigma)
      })
      
      total_ja <- sum(sapply(bg_rows, function(x)
        x$ja))
      total_nein <- sum(sapply(bg_rows, function(x)
        x$nein))
      total_sigma <- total_ja + total_nein
      
      list(
        bg = bg,
        rows = bg_rows,
        total_ja = total_ja,
        total_nein = total_nein,
        total_sigma = total_sigma
      )
    })
    
    # Calculate totals - sum ALL ja/nein across berufsgruppen
    all_ja <- sum(sapply(table_rows, function(x)
      x$total_ja))
    all_nein <- sum(sapply(table_rows, function(x)
      x$total_nein))
    all_sigma <- all_ja + all_nein
    
    # Get question numbers
    question_numbers <- sapply(binary_questions_list, function(q)
      as.character(q$number))
    
    # Build headers
    header_cols <- lapply(1:length(all_questions), function(i) {
      qnum <- question_numbers[i]
      tags$th(colspan = 3,
              style = "text-align: center; border: 1px solid #ccc; padding: 8px;",
              tags$strong(paste0(qnum, ".")))
    })
    
    subheader_cols <- rep(list(
      tags$th(style = "text-align: center; border: 1px solid #ddd; padding: 4px; font-size: 11px;", "Ja"),
      tags$th(style = "text-align: center; border: 1px solid #ddd; padding: 4px; font-size: 11px;", "Nein"),
      tags$th(style = "text-align: center; border: 1px solid #ddd; padding: 4px; font-size: 11px;", "Î£")
    ), length(all_questions))
    
    header_row <- tags$tr(
      tags$th(rowspan = 2, style = "border: 1px solid #ccc; padding: 8px;", "Berufsgruppe"),
      header_cols
    )
    
    subheader_row <- tags$tr(subheader_cols)
    
    # Data rows
    data_rows <- lapply(table_rows, function(tbl) {
      cells <- lapply(tbl$rows, function(row) {
        list(
          tags$td(style = "text-align: center; border: 1px solid #ddd; padding: 4px;", row$ja),
          tags$td(style = "text-align: center; border: 1px solid #ddd; padding: 4px;", row$nein),
          tags$td(style = "text-align: center; border: 1px solid #ddd; padding: 4px; font-weight: bold;", row$sigma)
        )
      })
      cells <- do.call(c, cells)
      
      tags$tr(
        tags$td(style = "border: 1px solid #ccc; padding: 8px; font-weight: 500;", tbl$bg),
        cells
      )
    })
    
    # Total row - but calculate it from the data, not sum all_ja/all_nein
    # âœ… Total should be sum of individual question totals
    total_ja_per_q <- lapply(1:length(all_questions), function(i) {
      sum(sapply(table_rows, function(x)
        x$rows[[i]]$ja))
    })
    total_nein_per_q <- lapply(1:length(all_questions), function(i) {
      sum(sapply(table_rows, function(x)
        x$rows[[i]]$nein))
    })
    
    total_cells <- lapply(1:length(all_questions), function(i) {
      ja_total <- as.integer(total_ja_per_q[[i]])
      nein_total <- as.integer(total_nein_per_q[[i]])
      sigma_total <- ja_total + nein_total
      
      list(
        tags$td(style = "text-align: center; border: 1px solid #ddd; padding: 4px; background: #f5f5f5; font-weight: bold;", ja_total),
        tags$td(style = "text-align: center; border: 1px solid #ddd; padding: 4px; background: #f5f5f5; font-weight: bold;", nein_total),
        tags$td(style = "text-align: center; border: 1px solid #ddd; padding: 4px; background: #f5f5f5; font-weight: bold;", sigma_total)
      )
    })
    total_cells <- do.call(c, total_cells)
    
    total_row <- tags$tr(
      tags$td(style = "border: 1px solid #ccc; padding: 8px; font-weight: 600;", "Gesamt"),
      total_cells
    )
    
    # Assemble table
    tags$div(
      style = "margin-top: 20px;",
      tags$h4("BinÃ¤re Fragen - Gewichtet nach Berufsgruppe"),
      tags$div(
        style = "overflow-x: auto;",
        tags$table(
          class = "binary-questions-table",
          style = "border-collapse: collapse; width: 100%;",
          tags$thead(header_row, subheader_row),
          tags$tbody(data_rows, total_row)
        )
      )
    )
  }
  
  
