  # -------HELPER: Create ggplot2 Radar Plot for Any Topic (Laborleitung)--------
  
  create_ggplot_radar_for_dashboard <- function(project_id,
                                                questions_list,
                                                topic_prefix,
                                                title,
                                                colour = "#003B73",
                                                binary_qnums = integer()) {
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con))
    
    # Filter binary questions
    questions_filtered <- if (length(binary_qnums) > 0) {
      Filter(function(q)
        ! (q$number %in% binary_qnums), questions_list)
    } else {
      questions_list
    }
    
    question_ids <- sapply(questions_filtered, function(q)
      q$id)
    
    # Query responses
    responses <- DBI::dbGetQuery(
      con,
      sprintf(
        "
    SELECT
      question_id,
      response_value::numeric as rv,
      COALESCE(CAST(qd.answers::json->>'group_size' AS INTEGER), 1) as group_size
    FROM responses r
    JOIN users u ON u.id = r.user_id
    LEFT JOIN questionnaire_drafts qd
      ON u.id::text = qd.user_id::text
      AND qd.project_id::text = r.project_id::text
      AND qd.questionnaire_id = 'peer_review'
    WHERE r.project_id = $1
      AND r.assessment_type = 'selbstbewertung'
      AND r.question_id IN (%s)
      AND r.response_value IS NOT NULL
      AND r.response_value != ''
      AND r.response_value != 'N/A'
  ",
        paste0("'", question_ids, "'", collapse = ", ")
      ),
      params = list(as.character(project_id))
    )
    
    if (nrow(responses) == 0) {
      plot.new()
      text(0.5, 0.5, "Keine Daten vorhanden", cex = 1.5)
      return()
    }
    
    # Expand by group_size
    expanded_list <- lapply(1:nrow(responses), function(i) {
      row <- responses[i, ]
      gs <- if (is.na(row$group_size) ||
                row$group_size < 1)
        1
      else
        as.integer(row$group_size)
      
      data.frame(question_id = rep(row$question_id, gs),
                 rv = rep(row$rv, gs))
    })
    
    expanded <- do.call(rbind, expanded_list)
    
    # Calculate means
    means <- aggregate(rv ~ question_id, data = expanded, FUN = mean)
    
    # Map to questions
    values <- sapply(questions_filtered, function(q) {
      row <- means[means$question_id == q$id, ]
      if (nrow(row) > 0)
        row$rv
      else
        0
    })
    
    labels <- sapply(questions_filtered, function(q)
      as.character(q$number))
    
    # Create ggplot2 radar
    library(ggplot2)
    
    n <- length(values)
    angles <- seq(0, 2 * pi, length.out = n + 1)[1:n]
    
    to_cartesian <- function(r, angle) {
      list(x = r * sin(angle), y = r * cos(angle))
    }
    
    # Polygon
    polygon_coords <- lapply(1:n, function(i) {
      coords <- to_cartesian(values[i], angles[i])
      data.frame(x = coords$x, y = coords$y)
    })
    polygon_df <- do.call(rbind, polygon_coords)
    polygon_df <- rbind(polygon_df, polygon_df[1, ])
    
    # Grid
    grid_circles <- lapply(0:5, function(r) {
      angle_seq <- seq(0, 2 * pi, length.out = 100)
      coords <- lapply(angle_seq, function(a)
        to_cartesian(r, a))
      data.frame(
        x = sapply(coords, function(c)
          c$x),
        y = sapply(coords, function(c)
          c$y),
        r = r
      )
    })
    grid_df <- do.call(rbind, grid_circles)
    
    # Axes
    axis_lines <- lapply(1:n, function(i) {
      coords <- to_cartesian(5.5, angles[i])
      data.frame(
        x = 0,
        y = 0,
        xend = coords$x,
        yend = coords$y
      )
    })
    axis_df <- do.call(rbind, axis_lines)
    
    # Labels
    label_coords <- lapply(1:n, function(i) {
      coords <- to_cartesian(6.2, angles[i])
      data.frame(x = coords$x,
                 y = coords$y,
                 label = labels[i])
    })
    label_df <- do.call(rbind, label_coords)
    
    # Plot
    ggplot() +
      geom_path(
        data = grid_df,
        aes(x = x, y = y, group = r),
        color = "grey85",
        linewidth = 0.5
      ) +
      geom_text(
        data = data.frame(
          x = 0,
          y = 0:5,
          label = 0:5
        ),
        aes(x = x, y = y, label = label),
        color = "grey50",
        size = 3,
        hjust = 1.5
      ) +
      geom_segment(
        data = axis_df,
        aes(
          x = x,
          y = y,
          xend = xend,
          yend = yend
        ),
        color = "grey70",
        linewidth = 0.5
      ) +
      geom_polygon(
        data = polygon_df,
        aes(x = x, y = y),
        fill = scales::alpha(colour, 0.3),
        color = colour,
        linewidth = 1.5
      ) +
      geom_point(data = polygon_df[1:n, ],
                 aes(x = x, y = y),
                 color = colour,
                 size = 2.5) +
      geom_text(
        data = label_df,
        aes(x = x, y = y, label = label),
        size = 3.5,
        fontface = "bold"
      ) +
      ggtitle(title) +
      coord_fixed() +
      xlim(c(-7, 7)) +
      ylim(c(-7, 7)) +
      theme_void() +
      theme(plot.title = element_text(
        hjust = 0.5,
        size = 16,
        face = "bold",
        margin = margin(b = 10)
      ))
  }
  
  
  
  #------- SHARED FUNCTION: Render Dashboard Section for Any Topic-------------
  
  render_dashboard_section_html <- function(topic_name,
                                            project_id,
                                            questions_list,
                                            binary_qnums = integer()) {
    if (is.null(project_id) || project_id == "" || is.na(project_id)) {
      return(
        HTML(
          "<p style='text-align:center; color:#999; padding:40px;'>Bitte wÃ¤hlen Sie ein Projekt aus.</p>"
        )
      )
    }
    
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con), add = TRUE)
    
    # Filter binary questions
    questions_filtered <- if (length(binary_qnums) > 0) {
      Filter(function(q)
        ! (q$number %in% binary_qnums), questions_list)
    } else {
      questions_list
    }
    
    question_ids <- sapply(questions_filtered, function(q)
      q$id)
    
    qids_quoted <- paste0("'", question_ids, "'", collapse = ", ")
    
    responses_query <- paste0(
      "
    SELECT
      DISTINCT ON (r.user_id, r.question_id)
      r.question_id,
      r.response_value,
      r.text_value,
      r.user_id,
      u.username,
      COALESCE(r.berufsgruppe, 'Nicht angegeben') as berufsgruppe,
      COALESCE(r.group_size, 1) as group_size
    FROM responses r
    JOIN users u ON u.id = r.user_id
    WHERE r.project_id::text = '",
      project_id,
      "'
      AND r.assessment_type = 'selbstbewertung'
      AND r.question_id IN (",
      qids_quoted,
      ")
      AND r.response_value != ''
    ORDER BY r.user_id, r.question_id, r.created_at DESC NULLS LAST
  "
    )
    
    responses <- tryCatch({
      DBI::dbGetQuery(con, responses_query)
    }, error = function(e) {
      message("Error: ", e$message)
      return(data.frame())
    })
    
    if (nrow(responses) == 0) {
      return(
        HTML(
          "<p style='text-align:center; color:#999; padding:40px;'>Keine Daten vorhanden.</p>"
        )
      )
    }
    
    # âœ… Get total unique users and their group_size ONCE
    unique_users_all <- responses[!duplicated(responses$user_id), ]
    total_unique_users <- nrow(unique_users_all)
    total_group_size_all <- sum(unique_users_all$group_size, na.rm = TRUE)
    
    # Build table rows
    rows_html <- sapply(questions_filtered, function(q) {
      q_data <- responses[responses$question_id == q$id, ]
      
      if (nrow(q_data) == 0) {
        return("")
      }
      
      # === COLUMN 1: Question ===
      question_html <- sprintf('<strong>%d. %s</strong>',
                               q$number,
                               htmltools::htmlEscape(q$label))
      
      # === COLUMN 2: Selbstbewertung ===
      
      # Rating counts - DO NOT sum group_size, just count how many people chose each rating
      valid_ratings <- q_data[q_data$response_value != "N/A" &
                                !is.na(q_data$response_value) &
                                q_data$response_value != "", ]
      
      if (nrow(valid_ratings) > 0) {
        # âœ… FIX: Count DISTINCT users per rating (not weighted)
        rating_summary <- valid_ratings %>%
          dplyr::group_by(response_value) %>%
          dplyr::summarise(n_users = n_distinct(user_id), .groups = "drop") %>%
          dplyr::arrange(as.numeric(response_value))
        
        rating_badges <- sapply(1:nrow(rating_summary), function(i) {
          rating <- rating_summary$response_value[i]
          count <- rating_summary$n_users[i]
          
          if (count > 1) {
            sprintf(
              '<span class="rating-active rating-with-count">%s<sup class="rating-count">Ã—%d</sup></span>',
              rating,
              count
            )
          } else {
            sprintf('<span class="rating-active">%s</span>', rating)
          }
        })
        ratings_html <- paste(rating_badges, collapse = " ")
      } else {
        ratings_html <- '<span class="no-data">â€”</span>'
      }
      
      # âœ… Use the TOTAL unique users and group_size (same for all questions)
      respondent_badge <- sprintf(
        '<span class="respondent-info"><i class="fa fa-users"></i> %d Teilnehmer</span>',
        total_unique_users,
        total_group_size_all
      )
      
      # Text responses - count distinct users per text
      text_data <- q_data[!is.na(q_data$text_value) &
                            q_data$text_value != "", ]
      
      if (nrow(text_data) > 0) {
        # âœ… FIX: Count distinct users per text (not weighted)
        text_summary <- text_data %>%
          dplyr::group_by(text_value) %>%
          dplyr::summarise(n_users = n_distinct(user_id), .groups = "drop")
        
        text_items <- sapply(1:nrow(text_summary), function(i) {
          txt <- text_summary$text_value[i]
          count <- text_summary$n_users[i]
          
          count_badge <- if (count > 1) {
            sprintf('<sup class="text-count">Ã—%d</sup>', count)
          } else {
            ""
          }
          
          sprintf(
            '<div class="selbst-text-item"><i class="fa fa-comment"></i> %s %s</div>',
            htmltools::htmlEscape(txt),
            count_badge
          )
        })
        
        texts_html <- sprintf(
          '<div class="selbst-text-container">%s</div>',
          paste(text_items, collapse = "")
        )
      } else {
        texts_html <- ""
      }
      
      selbst_html <- sprintf(
        '<div class="rating-inline">%s %s</div>%s',
        ratings_html,
        respondent_badge,
        texts_html
      )
      
      # === COLUMN 3: Statistics ===
      
      # âœ… Total n = unique users in this question
      unique_q_users <- q_data[!duplicated(q_data$user_id), ]
      total_n <- nrow(unique_q_users)
      stats_parts <- sprintf(
        '<div class="stat-item"><span class="stat-label">Gesamt:</span> <span class="stat-value">n=%d</span></div>',
        total_n
      )
      
      # Average rating (weighted by group_size, but only for valid numeric ratings)
      if (nrow(valid_ratings) > 0) {
        numeric_values <- as.numeric(valid_ratings$response_value)
        if (any(!is.na(numeric_values))) {
          # âœ… Weighted average (using group_size)
          weighted_sum <- sum(numeric_values * valid_ratings$group_size, na.rm = TRUE)
          weighted_total <- sum(valid_ratings$group_size, na.rm = TRUE)
          avg_rating <- weighted_sum / weighted_total
          
          stats_parts <- paste0(
            stats_parts,
            sprintf(
              '<div class="stat-item"><span class="stat-label">Ã˜ (gewichtet):</span> <span class="stat-value">%.2f</span></div>',
              avg_rating
            )
          )
        }
      }
      
      # Berufsgruppen breakdown
      berufsgruppen <- unique(valid_ratings$berufsgruppe)
      
      if (length(berufsgruppen) > 0) {
        bg_stats <- sapply(berufsgruppen, function(bg) {
          bg_data <- valid_ratings[valid_ratings$berufsgruppe == bg, ]
          # Count DISTINCT users per berufsgruppe
          unique_bg_users <- bg_data[!duplicated(bg_data$user_id), ]
          n_bg <- nrow(unique_bg_users)
          numeric_vals <- as.numeric(bg_data$response_value)
          
          if (any(!is.na(numeric_vals))) {
            weighted_sum_bg <- sum(numeric_vals * bg_data$group_size, na.rm = TRUE)
            weighted_total_bg <- sum(bg_data$group_size, na.rm = TRUE)
            avg_bg <- weighted_sum_bg / weighted_total_bg
            
            sprintf(
              '<div class="stat-item"><span class="stat-label">%s:</span> <span class="stat-value">Ã˜ %.2f (n=%d)</span></div>',
              bg,
              avg_bg,
              n_bg
            )
          } else {
            sprintf(
              '<div class="stat-item"><span class="stat-label">%s:</span> <span class="stat-value">n=%d</span></div>',
              bg,
              n_bg
            )
          }
        })
        
        stats_parts <- paste0(stats_parts, paste(bg_stats, collapse = ""))
      }
      
      # === BUILD ROW ===
      sprintf(
        '
      <tr class="dashboard-row">
        <td class="dashboard-col-question">%s</td>
        <td class="dashboard-col-selbst">%s</td>
        <td class="dashboard-col-stats">%s</td>
      </tr>
    ',
        question_html,
        selbst_html,
        stats_parts
      )
    })
    
    rows_html <- rows_html[rows_html != ""]
    
    if (length(rows_html) == 0) {
      return(
        HTML(
          "<p style='text-align:center; color:#999; padding:40px;'>Keine Daten.</p>"
        )
      )
    }
    
    # Complete table
    table_html <- sprintf(
      '
    <div class="dashboard-wrapper">
      <table class="dashboard-table">
        <thead>
          <tr>
            <th class="dashboard-col-question">Frage</th>
            <th class="dashboard-col-selbst">Selbstbewertung</th>
            <th class="dashboard-col-stats">Statistik</th>
          </tr>
        </thead>
        <tbody>
          %s
        </tbody>
      </table>
    </div>
  ',
      paste(rows_html, collapse = "")
    )
    
    return(HTML(table_html))
  }
  
  
