  #------------------------------load draft -------------------------------------
  attempt_draft_load <- function(retry_count = 0, max_retries = 5) {
    
    message("\n========== DRAFT LOAD ATTEMPT #", retry_count + 1, " ==========")
    
    if (!user_logged_in()) {
      message("âœ— User not logged in")
      loading_active(FALSE)
      return()
    }
    
    if (is.null(user_id())) {
      message("âœ— User ID is NULL")
      loading_active(FALSE)
      return()
    }
    
    ui_ready <- !is.null(input$Berufsgruppe)
    message("UI Ready: ", ui_ready)
    message("Draft Loaded Flag: ", draft_loaded())
    message("User ID: ", user_id())
    message("Project ID: ", current_project_id())
    
    if (!ui_ready) {
      if (retry_count < max_retries) {
        wait_time <- (retry_count + 1) * 500
        message("â†’ UI not ready, retrying in ", wait_time, "ms...")
        
        shinyjs::delay(wait_time, {
          attempt_draft_load(retry_count + 1, max_retries)
        })
      } else {
        message("âœ— Max retries reached, giving up")
        loading_active(FALSE)
        output$draft_status_ui <- renderUI({
          div(
            style = "padding: 10px; background-color: #f8d7da; border: 1px solid #f5c6cb; border-radius: 4px; margin: 20px 0;",
            icon("exclamation-triangle", style = "color: #721c24;"),
            tags$span(
              style = "margin-left: 8px; color: #721c24;",
              "Fehler beim Laden des Entwurfs. Bitte Seite neu laden oder 'Entwurf neu laden' klicken."
            )
          )
        })
      }
      return()
    }
    
    message("âœ“ UI ready, loading draft...")
    
    # âœ… TEMPORARY DIAGNOSTIC: catch any error here too, since a bare error
    # inside a shinyjs::delay() callback can crash the whole session even
    # when a renderUI elsewhere is properly wrapped.
    tryCatch({
      resume_draft_from_db()
    }, error = function(e) {
      msg <- conditionMessage(e)
      message("âŒ DIAGNOSTIC - real error in resume_draft_from_db(): ", msg)
      showNotification(
        paste("DIAGNOSTIC - resume_draft_from_db() error:", msg),
        type = "error",
        duration = NULL
      )
    })
    
    shinyjs::delay(1200, {
      draft_loaded(TRUE)
      loading_active(FALSE)
      qn_answers_changed(FALSE)   # âœ… FIXED (was: answers_changed(FALSE))
      message("âœ“ Draft loading FULLY complete - auto-save now active")
    })
  }
  
