  #--------------Project Selector: Dynamic for each role-------------------------
  
  # Reactive value for triggering refresh after project creation
  project_data_changed <- reactiveVal(0)
  
  get_project_choices <- function(role, user_id) {
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con))
    
    if (role == "admin") {
      projs <- DBI::dbGetQuery(con,
                               "SELECT id, title FROM projects ORDER BY created_at DESC")
    } else if (role == "laborleitung") {
      # âœ… Get project from users table
      projs <- DBI::dbGetQuery(
        con,
        "SELECT p.id, p.title
       FROM projects p
       JOIN users u ON p.id = u.project_id
       WHERE u.id = $1",
        params = list(user_id)
      )
    } else if (role %in% c("leading_peer", "co_peer")) {
      # âœ… FIXED: co_peer was never included here, causing "Keine Projekte
      # verfÃ¼gbar" - co_peer gets their project the same way leading_peer
      # does, via users.project_id.
      projs <- DBI::dbGetQuery(
        con,
        "SELECT p.id, p.title
       FROM projects p
       JOIN users u ON p.id = u.project_id
       WHERE u.id = $1",
        params = list(user_id)
      )
    } else {
      projs <- data.frame(id = character(0), title = character(0))
    }
    
    if (nrow(projs) == 0) {
      return(c("Kein Projekt zugewiesen" = ""))
    }
    
    setNames(projs$id, projs$title)
  }
  
