  get_input_safe <- function(id) {
    val <- input[[id]]
    if (is.null(val) || length(val) == 0)
      return(NA_character_)
    if (is.logical(val) &&
        length(val) == 1 && !is.na(val))
      return(as.character(val))
    if (is.character(val) && length(val) == 1)
      return(val)
    if (is.numeric(val) &&
        length(val) == 1)
      return(as.character(val))
    return(NA_character_)
  }
  
