  audit_refresh <- reactiveVal(0)

  audit_rows <- reactive({
    req(user_logged_in())
    req(user_role() == "admin")
    audit_refresh()
    input$audit_reload

    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con), add = TRUE)

    conds <- c("1=1")
    params <- list()

    if (!is.null(input$audit_range) && length(input$audit_range) == 2) {
      conds <- c(conds, sprintf("ts::date BETWEEN $%d AND $%d", length(params) + 1, length(params) + 2))
      params <- c(params, list(as.character(input$audit_range[1]), as.character(input$audit_range[2])))
    }
    if (!is.null(input$audit_user) && nzchar(trimws(input$audit_user))) {
      conds <- c(conds, sprintf("username ILIKE $%d", length(params) + 1))
      params <- c(params, list(paste0("%", trimws(input$audit_user), "%")))
    }
    if (!is.null(input$audit_action_filter) && nzchar(input$audit_action_filter) && input$audit_action_filter != "(alle)") {
      conds <- c(conds, sprintf("action = $%d", length(params) + 1))
      params <- c(params, list(input$audit_action_filter))
    }
    if (!is.null(input$audit_search) && nzchar(trimws(input$audit_search))) {
      s <- paste0("%", trimws(input$audit_search), "%")
      idx <- length(params) + 1
      conds <- c(conds, sprintf(
        "(entity_id ILIKE $%d OR new_value ILIKE $%d OR old_value ILIKE $%d OR details ILIKE $%d)",
        idx, idx, idx, idx
      ))
      params <- c(params, list(s))
    }

    limit <- suppressWarnings(as.integer(input$audit_limit %||% "500"))
    if (is.na(limit)) limit <- 500

    query <- sprintf("
      SELECT ts, username, user_role, action, entity_type, entity_id, project_id,
             old_value, new_value, details
      FROM pr_app_audit_log
      WHERE %s
      ORDER BY ts DESC
      LIMIT %d
    ", paste(conds, collapse = " AND "), limit)

    tryCatch(DBI::dbGetQuery(con, query, params = params),
             error = function(e) { message("Audit-Abfrage fehlgeschlagen: ", e$message); NULL })
  })

  audit_display <- function(d) {
    if (is.null(d) || !nrow(d)) return(data.frame())
    out <- data.frame(
      Zeitpunkt = format(as.POSIXct(d$ts), "%d.%m.%Y %H:%M:%S"),
      Benutzer  = d$username,
      Rolle     = d$user_role,
      Aktion    = d$action,
      Typ       = d$entity_type,
      Objekt    = d$entity_id,
      Projekt   = d$project_id,
      Vorher    = d$old_value,
      Nachher   = d$new_value,
      Details   = d$details,
      stringsAsFactors = FALSE
    )
    out
  }

