  #-----------------------Save Draft for lab info and  Selbstbewertung----------
  
  
  # â”€â”€ Define once, reuse everywhere â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  all_question_lists <- list(
    list(questions = fuehrung_questions, tag = "fuehrung"),
    list(questions = mit_questions, tag = "mitarbeitende"),
    list(questions = pat_questions, tag = "patienten"),
    list(questions = ein_questions, tag = "einsender"),
    list(questions = qual_questions, tag = "qualitaet"),
    list(questions = qual_mibi_questions, tag = "qualitaet_mibi")
  )
  
  # â”€â”€ 1. Get all question input IDs â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  get_all_question_ids <- function() {
    # âœ… FIXED: this used to also include ALL Lab Info field IDs (name,
    # Internetadresse, Trag, ... and critically Beschreibung, WeitereInfo,
    # Kompetenzschwerpunkte, ErgÃ¤nzung - which are the EXACT SAME input IDs
    # Lab Info uses for its own fields). Since Lab Info is now a fully
    # separate form/pipeline with its own save/load, keeping these here
    # caused two real bugs:
    #   1. Every Lab Info keystroke also triggered a Questionnaire auto-save
    #      (wasteful, and confusing in the console log).
    #   2. Worse: the Questionnaire's own draft-restore logic
    #      (resume_draft_from_db) would update inputs named "Beschreibung",
    #      "WeitereInfo", etc. when loading a QUESTIONNAIRE draft - silently
    #      overwriting whatever was in Lab Info's own same-named fields,
    #      depending on which tab was visited in which order.
    # Only genuinely Questionnaire-specific fields remain below.
    ids <- c(
      "Berufsgruppe",
      "alleine_oder_gruppe",
      "gruppen_groesse"
    )
    
    # Question IDs from all sections
    for (section in all_question_lists) {
      for (q in section$questions) {
        # â† $questions
        ids <- c(ids,
                 paste0("Freitext", q$id),
                 paste0("Freitext_text", q$id))
      }
    }
    
    # Dynamic peer review fields
    n_anmerkungen <- if (!is.null(anmerkungen$counter))
      anmerkungen$counter
    else
      1
    ids <- c(ids, unlist(lapply(seq_len(n_anmerkungen), function(i)
      c(paste0("Beschreibung", i), paste0("Anmerkung", i)))))
    
    ids
  }
  
  # â”€â”€ 2. Collect answers â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  get_qn_answers <- function() {
    ids     <- get_all_question_ids()
    answers <- list()
    for (id in ids) {
      val <- input[[id]]
      if (!is.null(val) && !(is.character(val) && all(val == "")))
        answers[[id]] <- val
    }
    answers
  }
  
  # â”€â”€ 3. Save draft to DB â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  
  
  save_draft_to_db <- function(status = "paused",
                               show_notification = TRUE) {
    uid <- user_id()
    pid <- current_project_id()
    qid <- "peer_review"
    
    message("Saving draft - User: ",
            uid,
            ", Project: ",
            pid,
            ", Status: ",
            status)
    
    if (is.null(uid) || is.na(uid)) {
      if (show_notification)
        showNotification("Bitte melden Sie sich an",
                         type = "error",
                         duration = 3)
      return(FALSE)
    }
    if (is.null(pid) || is.na(pid)) {
      if (show_notification)
        showNotification(
          "Bitte wÃ¤hlen Sie zuerst ein Projekt aus",
          type = "warning",
          duration = 3
        )
      return(FALSE)
    }
    
    tryCatch({
      con <- get_db_con()
      on.exit(DBI::dbDisconnect(con))
      
      # Block overwrite of submitted
      check <- DBI::dbGetQuery(
        con,
        "SELECT status FROM questionnaire_drafts
       WHERE user_id = $1 AND project_id = $2 AND questionnaire_id = $3",
        params = list(as.integer(uid), as.integer(pid), qid)
      )
      
      if (nrow(check) > 0 &&
          check$status[1] == "submitted" &&
          status != "submitted") {
        if (show_notification)
          showNotification(
            "Bereits abgeschickt â€“ keine Ã„nderungen mÃ¶glich.",
            type = "error",
            duration = 5
          )
        return(FALSE)
      }
      
      # Collect answers
      answers_list <- get_qn_answers()
      message("Collected ", length(answers_list), " answers")
      
      if (length(answers_list) == 0) {
        if (show_notification)
          showNotification("Keine Daten zum Speichern!", type = "warning")
        return(FALSE)
      }
      
      answers_json <- jsonlite::toJSON(answers_list, auto_unbox = TRUE)
      
      existing <- DBI::dbGetQuery(
        con,
        "SELECT id FROM questionnaire_drafts
       WHERE user_id = $1 AND project_id = $2 AND questionnaire_id = $3",
        params = list(as.integer(uid), as.integer(pid), qid)
      )
      
      if (nrow(existing) > 0) {
        DBI::dbExecute(
          con,
          "UPDATE questionnaire_drafts
         SET answers = $1, status = $2, last_saved = NOW()
         WHERE id = $3",
          params = list(answers_json, status, existing$id[1])
        )
        message("âœ“ Draft updated - ID: ", existing$id[1])
      } else {
        DBI::dbExecute(
          con,
          "INSERT INTO questionnaire_drafts
         (user_id, project_id, questionnaire_id, answers, status, last_saved)
         VALUES ($1, $2, $3, $4, $5, NOW())",
          params = list(
            as.integer(uid),
            as.integer(pid),
            qid,
            answers_json,
            status
          )
        )
        message("âœ“ New draft created")
      }
      
      if (show_notification) {
        if (status == "submitted") {
          showNotification(
            "Fragebogen erfolgreich abgeschickt! âœ“",
            type = "message",
            duration = 5
          )
        } else {
          showNotification("Entwurf gespeichert âœ“",
                           type = "message",
                           duration = 2)
        }
      }
      
      return(TRUE)
      
    }, error = function(e) {
      message("ERROR saving draft: ", e$message)
      if (show_notification)
        showNotification(paste("Fehler:", e$message),
                         type = "error",
                         duration = 5)
      return(FALSE)
    })
  }
  
  
  # â”€â”€ 4. Save button observers â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  lapply(c(
    "save_draft_btn_fuehrung",
    "save_draft_btn_mit",
    "save_draft_btn_pat",
    "save_draft_btn_ein",
    "save_draft_btn_qual_all"
  ), function(btn_id) {
    observeEvent(input[[btn_id]], {
      message("Button clicked: ", btn_id)
      req(user_logged_in())
      
      if (is_demo_mode()) {
        showNotification(
          "Demo-Modus: Speichern deaktiviert.",
          type = "warning",
          duration = 4
        )
        return()
      }
      
      qn_auto_save_status("Saving...")   
      
      success <- save_draft_to_db(status = "paused", show_notification = TRUE)
      
      if (success) {
        qn_auto_save_status(paste("Saved at", format(Sys.time(), "%H:%M:%S")))
      }
      
    }, ignoreInit = TRUE)
  })
  
  # â”€â”€ 5. Resume draft from DB â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  resume_draft_from_db <- function() {
    req(user_logged_in())
    
    if (is.null(input$Berufsgruppe)) {
      message("âš  UI not ready - aborting draft load")
      return()
    }
    
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con))
    
    uid <- user_id()
    pid <- current_project_id()
    qid <- "peer_review"
    
    message("Loading draft - User: ", uid, ", Project: ", pid)
    
    # Fetch draft
    if (is.null(pid) || pid == "" || is.na(pid)) {
      draft <- DBI::dbGetQuery(
        con,
        "SELECT answers, project_id, status, last_saved
       FROM questionnaire_drafts
       WHERE user_id = $1 AND questionnaire_id = $2
         AND status IN ('draft','paused')
       ORDER BY last_saved DESC LIMIT 1",
        params = list(uid, qid)
      )
      
      if (nrow(draft) > 0) {
        current_project_id(draft$project_id[1])
        pid <- draft$project_id[1]
      }
    } else {
      draft <- DBI::dbGetQuery(
        con,
        "SELECT answers, status, last_saved
       FROM questionnaire_drafts
       WHERE user_id = $1 AND project_id = $2 AND questionnaire_id = $3
         AND status IN ('draft','paused','submitted')
       ORDER BY
         CASE WHEN status='submitted' THEN 1
              WHEN status='paused'    THEN 2
              ELSE 3 END,
         last_saved DESC
       LIMIT 1",
        params = list(uid, pid, qid)
      )
    }
    
    if (nrow(draft) == 0) {
      message("No draft found")
      output$draft_status_ui <- renderUI(div(style = "color:gray", "Kein Entwurf gefunden."))
      return()
    }
    
    answers     <- jsonlite::fromJSON(draft$answers[1])
    draft_status <- draft$status[1]
    draft_date   <- format(as.POSIXct(draft$last_saved[1]), "%d.%m.%Y um %H:%M")
    
    message("Draft status: ", draft_status, " | Keys: ", length(answers))
    
    if (is.null(answers) || length(answers) == 0) {
      message("Draft is empty")
      return()
    }
    
    # â”€â”€ Restore peer review dynamic field counter â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    peer_nums <- as.integer(gsub(
      "[^0-9]",
      "",
      grep(
        "^Beschreibung\\d+$|^Anmerkung\\d+$",
        names(answers),
        value = TRUE
      )
    ))
    if (length(peer_nums) > 0 && !all(is.na(peer_nums)))
      anmerkungen$counter <- max(peer_nums, na.rm = TRUE)
    
    # â”€â”€ Restore Berufsgruppe first â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    if (!is.null(answers[["Berufsgruppe"]]))
      updateRadioButtons(session, "Berufsgruppe", selected = answers[["Berufsgruppe"]])
    
    # â”€â”€ Restore alleine_oder_gruppe â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    restore_gruppe     <- FALSE
    gruppe_size_value  <- NULL
    
    if (!is.null(answers[["alleine_oder_gruppe"]])) {
      updateRadioButtons(session, "alleine_oder_gruppe", selected = answers[["alleine_oder_gruppe"]])
      if (answers[["alleine_oder_gruppe"]] == "gruppe" &&
          !is.null(answers[["gruppen_groesse"]])) {
        restore_gruppe    <- TRUE
        gruppe_size_value <- as.character(answers[["gruppen_groesse"]])
      }
    }
    
    # â”€â”€ Restore all other inputs â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    skip <- c("Berufsgruppe",
              "alleine_oder_gruppe",
              "gruppen_groesse",
              # âœ… ADDED: defensive skip for Lab Info's field names, in case
              # an OLD draft (saved before the get_all_question_ids fix) still
              # has these keys baked into its stored answers JSON. Without
              # this, loading such an old draft could still overwrite Lab
              # Info's own same-named input fields.
              labinfo_field_ids)
    
    numeric_ids <- c(
      "Anzahl_total",
      "Anzahl_mit",
      "davon_Fachaerzte",
      "davon_weiterbildung",
      "Anzahl_Planstellen",
      "davon_unbesetzt",
      "Anzahl_tech",
      "Anzahl_TPlanstellen",
      "davon_Tunbesetzt",
      "Anzahl_natur",
      "Anzahl_NPlanstellen",
      "davon_Nunbesetzt",
      "Anzahl_IT",
      "Anzahl_IPlanstellen",
      "davon_Iunbesetzt"
    )
    
    textarea_ids <- c("Beschreibung",
                      "WeitereInfo",
                      "Kompetenzschwerpunkte",
                      "ErgÃ¤nzung")
    
    checkbox_ids <- c("versorgung", "laborbereiche", "leistungsspektrum")
    
    for (id in names(answers)) {
      if (id %in% skip)
        next
      if (grepl("^Beschreibung\\d+$|^Anmerkung\\d+$", id))
        next  # handled with delay
      
      val <- answers[[id]]
      if (is.null(val) ||
          (is.character(val) && all(val == "")))
        next
      
      tryCatch({
        if (id %in% numeric_ids) {
          updateNumericInput(session, id, value = suppressWarnings(as.numeric(val)))
        } else if (id %in% checkbox_ids) {
          updateCheckboxGroupInput(session, id, selected = val)
        } else if (id %in% textarea_ids || grepl("_text$", id)) {
          updateTextAreaInput(session, id, value = as.character(val))
        } else if (grepl("^Freitext", id)) {
          updateRadioButtons(session, id, selected = as.character(val))
        } else {
          updateTextInput(session, id, value = as.character(val))
        }
      }, error = function(e) {
        message("  Could not restore: ", id, " - ", e$message)
      })
    }
    
    message("âœ“ All inputs restored")
    
    # â”€â”€ Restore dynamic peer fields after short delay â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    shinyjs::delay(400, {
      for (i in seq_len(anmerkungen$counter)) {
        bid <- paste0("Beschreibung", i)
        aid <- paste0("Anmerkung", i)
        if (!is.null(answers[[bid]]))
          updateTextAreaInput(session, bid, value = answers[[bid]])
        if (!is.null(answers[[aid]]))
          updateTextInput(session, aid, value = answers[[aid]])
      }
    })
    
    # â”€â”€ Restore gruppen_groesse with longer delay â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    if (restore_gruppe && !is.null(gruppe_size_value)) {
      shinyjs::delay(800, {
        updateSelectInput(session, "gruppen_groesse", selected = gruppe_size_value)
      })
    }
    
    # â”€â”€ Show status banner â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    output$draft_status_ui <- renderUI({
      if (draft_status == "submitted") {
        div(
          style = "padding:15px;background:#f2dede;border:1px solid #d9534f;border-radius:4px;margin:20px 0;",
          div(
            style = "color:#d9534f;font-weight:bold;font-size:16px;text-align:center;",
            icon("check-circle"),
            tags$br(),
            tags$br(),
            "Fragebogen bereits abgeschickt"
          ),
          tags$hr(style = "border-color:#d9534f;"),
          div(
            style = "color:#a94442;",
            tags$p(
              icon("calendar"),
              " Abgeschickt am: ",
              tags$strong(draft_date)
            ),
            tags$p(
              icon("info-circle"),
              " Keine Ã„nderungen mehr mÃ¶glich."
            )
          )
        )
      } else if (draft_status == "paused") {
        div(
          style = "padding:15px;background:#fcf8e3;border:1px solid #faebcc;border-radius:4px;margin:20px 0;",
          div(style = "color:#8a6d3b;font-weight:bold;", icon("pause-circle"), " Pausierter Entwurf"),
          tags$hr(style = "border-color:#faebcc;"),
          div(
            style = "color:#8a6d3b;",
            tags$p(
              icon("clock"),
              " Zuletzt gespeichert: ",
              tags$strong(draft_date)
            ),
            tags$p(icon("edit"), " Sie kÃ¶nnen weiter bearbeiten.")
          )
        )
      } else {
        div(
          style = "padding:10px;background:#d9edf7;border:1px solid #bce8f1;border-radius:4px;margin:20px 0;",
          div(
            style = "color:#31708f;",
            icon("info-circle"),
            " ",
            tags$strong("Entwurf geladen"),
            tags$br(),
            tags$small("Zuletzt gespeichert: ", draft_date)
          )
        )
      }
    })
    
    if (draft_status == "submitted") {
      showNotification(
        paste0("Abgeschickt am ", draft_date, " â€“ nur Ansicht"),
        type = "warning",
        duration = NULL
      )
      shinyjs::delay(2000, disable_all_questionnaire_inputs())
    } else if (draft_status == "paused") {
      showNotification(
        paste0("Entwurf geladen (", draft_date, ")"),
        type = "message",
        duration = 4
      )
    } else {
      showNotification("Entwurf geladen!",
                       type = "message",
                       duration = 3)
    }
  }
  
  # â”€â”€ 6. Disable all inputs after submit â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  disable_all_questionnaire_inputs <- function() {
    shinyjs::disable("Berufsgruppe")
    shinyjs::disable("alleine_oder_gruppe")
    shinyjs::disable("gruppen_groesse")
    shinyjs::disable("go_to_fuehrung")
    shinyjs::disable("submit_questionnaire")
    
    for (qlist in all_question_lists) {
      for (q in qlist$questions) {
        # â† $questions
        tryCatch({
          shinyjs::disable(paste0("Freitext", q$id))
          shinyjs::disable(paste0("Freitext_text", q$id))
        }, error = function(e) {
          
        })
      }
    }
    message("âœ“ All inputs disabled")
  }
  
  # â”€â”€ 7. Project ID observer â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  current_project_id <- reactiveVal(NULL)
  
  observeEvent(input$selected_project, {
    req(input$selected_project)
    current_project_id(input$selected_project)
    message("âœ“ Project ID set to: ", input$selected_project)
  })
  
  
  
  #-----------------------Save Draft for Fremdbewertung-----------------------
  
  save_fremdbewertung_draft_to_db <- function(show_notification = TRUE) {
    message("\n========== SAVE PEER DRAFT ==========")
    
    req(user_logged_in())
    req(user_role() %in% c("leading_peer", "co_peer"))
    
    current_user_id <- user_id()
    project_id <- current_project_id()
    questionnaire_id <- "peer_fremdbewertung"
    
    message("User ID: ", current_user_id)
    message("Role: ", user_role())
    message("Project ID: ", project_id)
    
    if (is.null(project_id) || project_id == "" || is.na(project_id)) {
      if (show_notification) showNotification("Kein Projekt ausgewÃ¤hlt!", type = "error")
      return(FALSE)
    }
    
    all_answers <- list()
    
    # Save current tab position
    if (!is.null(input$fragebogen_tabs_peer)) {
      all_answers[["current_tab"]] <- input$fragebogen_tabs_peer
      message("  Current tab: ", input$fragebogen_tabs_peer)
    }
    
    # âœ… FIXED: use topic_questions (already includes qualitaet_mibi) instead of
    # the old hardcoded all_question_lists that was missing it
    for (section_key in names(topic_questions)) {
      questions <- topic_questions[[section_key]]
      
      for (q in questions) {
        qid <- q$id
        score_id <- paste0("FremdbewertungNum_", qid)
        text_id <- paste0("FremdbewertungText_", qid)
        
        if (!is.null(input[[score_id]]) && input[[score_id]] != "") {
          all_answers[[score_id]] <- input[[score_id]]
        }
        
        if (!is.null(input[[text_id]]) && input[[text_id]] != "") {
          all_answers[[text_id]] <- input[[text_id]]
        }
      }
    }
    
    message("Total answers: ", length(all_answers))
    
    if (length(all_answers) <= 1) {
      if (show_notification) showNotification("Keine Daten zum Speichern!", type = "warning")
      return(FALSE)
    }
    
    answers_json <- jsonlite::toJSON(all_answers, auto_unbox = TRUE)
    
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con), add = TRUE)
    
    tryCatch({
      existing <- DBI::dbGetQuery(
        con,
        "SELECT id FROM questionnaire_drafts
       WHERE user_id = $1 AND project_id = $2 AND questionnaire_id = $3",
        params = list(current_user_id, project_id, questionnaire_id)
      )
      
      if (nrow(existing) > 0) {
        DBI::dbExecute(
          con,
          "UPDATE questionnaire_drafts
         SET answers = $1, last_saved = NOW(), status = 'draft'
         WHERE id = $2",
          params = list(answers_json, existing$id[1])
        )
        message("âœ“ Draft updated - ID: ", existing$id[1])
      } else {
        DBI::dbExecute(
          con,
          "INSERT INTO questionnaire_drafts (user_id, project_id, questionnaire_id, answers, status, last_saved)
         VALUES ($1, $2, $3, $4, 'draft', NOW())",
          params = list(current_user_id, project_id, questionnaire_id, answers_json)
        )
        message("âœ“ New draft created")
      }
      
      if (show_notification) {
        showNotification("Entwurf gespeichert!", type = "message", duration = 3)
      }
      
      message("=================================\n")
      TRUE
      
    }, error = function(e) {
      message("ERROR: ", e$message)
      if (show_notification) {
        showNotification(paste("Fehler:", e$message), type = "error", duration = 10)
      }
      FALSE
    })
  }
  
  # âœ… ONE observer only - calls the extracted function
  observeEvent(input$save_peer_draft_btn, {
    save_fremdbewertung_draft_to_db(show_notification = TRUE)
  }, ignoreInit = TRUE)
  
  
  # ======================== STEP 2: Auto-save reactive values + observers ========================
  #
  # Add these ONCE, alongside your other auto-save reactiveVals (or in their own
  # section - just make sure they're defined once, at the top level of server,
  # not nested inside any other observer).
  
  fremd_answers_changed           <- reactiveVal(FALSE)
  fremd_answers_changed_debounced <- debounce(fremd_answers_changed, 3000)
  fremd_auto_save_status          <- reactiveVal("Unsaved changes")
  fremd_loading_active            <- reactiveVal(FALSE)
  
  # ============ OBSERVER 1: Watch all Fremdbewertung inputs ============
  #
  # Loops over topic_questions (already includes qualitaet_mibi) so ANY
  # FremdbewertungNum_/FremdbewertungText_ input change is detected,
  # across ALL sections including Mikrobiologie.
  
  observe({
    req(!fremd_loading_active())
    
    for (section_key in names(topic_questions)) {
      questions <- topic_questions[[section_key]]
      for (q in questions) {
        qid <- q$id
        input[[paste0("FremdbewertungNum_", qid)]]
        input[[paste0("FremdbewertungText_", qid)]]
      }
    }
    
    isolate({
      if (!isTRUE(fremd_loading_active())) {
        fremd_answers_changed(TRUE)
      }
    })
  }, priority = 1000)
  
  # ============ OBSERVER 2: Auto-save trigger ============
  
  observe({
    fremd_answers_changed_debounced()
    
    req(user_logged_in())
    req(user_role() %in% c("leading_peer", "co_peer"))
    req(current_project_id())
    req(!fremd_loading_active())
    req(isTRUE(fremd_answers_changed()))   # âœ… FIXED: same missing-check bug as Lab Info/Questionnaire Observer 2 - this ran unconditionally on its own first flush, regardless of whether anything actually changed.
    
    if (is_demo_mode()) {
      fremd_answers_changed(FALSE)
      return()
    }
    
    tryCatch({
      message("â†’ Auto-saving Fremdbewertung responses...")
      fremd_auto_save_status("Saving...")
      
      success <- save_fremdbewertung_draft_to_db(show_notification = FALSE)
      
      fremd_answers_changed(FALSE)
      
      if (isTRUE(success)) {
        fremd_auto_save_status(paste("Gespeichert um", format(Sys.time(), "%H:%M:%S")))
      }
      
    }, error = function(e) {
      message("Fremdbewertung auto-save error: ", e$message)
      fremd_answers_changed(FALSE)
    })
    
  }, priority = 900)
  
  
  # ============ STATUS DISPLAY ============
  #
  # Add uiOutput("fremd_auto_save_status_ui") somewhere visible in the
  # Fremdbewertung UI (e.g. inside fragebogen_ui's tagList, or just once
  # outside the tabsetPanel).
  
  output$fremd_auto_save_status_ui <- renderUI({
    status <- fremd_auto_save_status()
    
    if (grepl("Gespeichert um", status)) {
      div(
        style = "position: fixed; bottom: 20px; right: 20px; padding: 10px 15px; background-color: #d4edda; color: #155724; border: 1px solid #c3e6cb; border-radius: 4px; font-size: 12px; z-index: 999;",
        icon("check-circle", style = "margin-right: 5px;"),
        status
      )
    } else if (grepl("Saving", status)) {
      div(
        style = "position: fixed; bottom: 20px; right: 20px; padding: 10px 15px; background-color: #fff3cd; color: #856404; border: 1px solid #ffeaa7; border-radius: 4px; font-size: 12px; z-index: 999;",
        icon("hourglass", style = "margin-right: 5px;"),
        "Speichere..."
      )
    }
  })
  
  
  # 3. LOAD FREMDBEWERTUNG DRAFT (called when fragebogen_ui renders)
  resume_fremdbewertung_draft <- function() {
    req(user_logged_in())
    req(user_role() %in% c("leading_peer", "co_peer"))
    
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con))
    
    user_id_val <- user_id()
    proj_id_val <- current_project_id()
    qid_val <- "peer_fremdbewertung"
    
    message("\n========== LOAD PEER DRAFT ==========")
    message("User: ", user_id_val)
    message("Project: ", proj_id_val)
    
    if (is.null(proj_id_val) ||
        proj_id_val == "" || is.na(proj_id_val)) {
      message("No project selected")
      return(list())
    }
    
    # Fetch draft
    draft <- DBI::dbGetQuery(
      con,
      "SELECT answers FROM questionnaire_drafts
     WHERE user_id = $1 AND project_id = $2 AND questionnaire_id = $3 AND status = 'draft'
     ORDER BY last_saved DESC LIMIT 1",
      params = list(user_id_val, proj_id_val, qid_val)
    )
    
    if (nrow(draft) == 0) {
      message("No draft found")
      return(list())
    }
    
    answers <- jsonlite::fromJSON(draft$answers[1])
    
    if (is.null(answers) || length(answers) == 0) {
      message("Draft is empty")
      return(list())
    }
    
    message("Loaded ", length(answers), " keys")
    message("âœ“ Restored ", sum(grepl(
      "^FremdbewertungNum_", names(answers)
    )), " inputs")
    message("=================================\n")
    
    return(answers)
  }
  
  # -------------------------ADMIN: View Users & Projects ------------------------
  output$admin_users_table <- DT::renderDataTable({
    req(user_role() == "admin")
    
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con))
    
    users <- DBI::dbGetQuery(
      con,
      "
    SELECT id, username, email, role, project_id, created_at
    FROM users
    ORDER BY id DESC
  "
    )
    
    DT::datatable(users,
                  options = list(pageLength = 25),
                  rownames = FALSE)
  })
  
  #----------------------------ADMIN: View All Projects------------------------
  output$admin_projects_table <- DT::renderDataTable({
    req(user_role() == "admin")
    
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con))
    
    projects <- DBI::dbGetQuery(
      con,
      "
    SELECT p.id, p.title as name, p.status, p.created_at,
           u.username as created_by_user
    FROM projects p
    LEFT JOIN users u ON p.owner_id = u.id
    ORDER BY p.id DESC
  "
    )
    
    DT::datatable(projects,
                  options = list(pageLength = 25),
                  rownames = FALSE)
  })
  
  
  #----------------------------ADMIN sees all the questionnaire drafts-----------
  output$admin_drafts_table <- DT::renderDataTable({
    req(user_role() == "admin")
    
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con))
    
    drafts <- DBI::dbGetQuery(
      con,
      "
    SELECT
      d.id,
      u.username,
      u.role,
      p.title as project,
      d.questionnaire_id,
      d.status,
      d.last_saved,
      (SELECT COUNT(*) FROM jsonb_object_keys(d.answers)) as num_fields
    FROM questionnaire_drafts d
    LEFT JOIN users u ON d.user_id::integer = u.id
    LEFT JOIN projects p ON d.project_id::integer = p.id
    ORDER BY d.last_saved DESC
  "
    )
    
    DT::datatable(
      drafts,
      options = list(
        pageLength = 10,
        order = list(list(6, 'desc'))  # Sort by last_saved descending
      ),
      rownames = FALSE,
      selection = 'single',
      colnames = c(
        'ID',
        'Benutzer',
        'Rolle',
        'Projekt',
        'Fragebogen',
        'Status',
        'Zuletzt gespeichert',
        'Anzahl Felder'
      )
    )
  })
  
  # âœ… NEW: Show Draft Details When Row is Selected
  observeEvent(input$admin_drafts_table_rows_selected, {
    req(user_role() == "admin")
    req(length(input$admin_drafts_table_rows_selected) > 0)
    
    row_selected <- input$admin_drafts_table_rows_selected
    
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con))
    
    # Get all drafts (same order as displayed)
    drafts <- DBI::dbGetQuery(
      con,
      "
    SELECT id, user_id, project_id, answers, last_saved
    FROM questionnaire_drafts
    ORDER BY last_saved DESC
  "
    )
    
    if (row_selected <= nrow(drafts)) {
      draft_id <- drafts$id[row_selected]
      answers_json <- drafts$answers[row_selected]
      
      # Parse JSON
      answers <- jsonlite::fromJSON(answers_json)
      
      # Remove metadata fields
      answers <- answers[!grepl("^_", names(answers))]
      
      # Count non-empty fields
      non_empty <- sum(sapply(answers, function(x)
        ! is.null(x) && x != "" && x != "N/A"))
      
      # Create formatted view
      output$draft_details_view <- renderUI({
        tagList(
          h3(paste("Entwurf ID:", draft_id)),
          h4(
            paste(
              "AusgefÃ¼llte Felder:",
              non_empty,
              "von",
              length(answers)
            )
          ),
          p(
            strong("Zuletzt gespeichert:"),
            format(
              as.POSIXct(drafts$last_saved[row_selected]),
              "%d.%m.%Y %H:%M:%S"
            )
          ),
          
          hr(),
          
          h4("AusgefÃ¼llte Antworten:"),
          tags$div(style = "max-height: 600px; overflow-y: auto;", lapply(names(answers), function(field_name) {
            value <- answers[[field_name]]
            
            # Only show non-empty values
            if (!is.null(value) &&
                value != "" && value != "N/A") {
              tags$div(
                style = "padding: 10px; margin-bottom: 10px; background: #f8f9fa; border-left: 3px solid #007bff; border-radius: 4px;",
                tags$strong(field_name, ":"),
                tags$br(),
                tags$span(style = "color: #495057;", as.character(value))
              )
            }
          })),
          
          hr(),
          
          h4("Rohdaten (JSON):"),
          tags$pre(
