  #--------------Helper Function: Get Berufsgruppe Breakdown-------------------
  
  get_berufsgruppe_breakdown <- function(project_id) {
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con), add = TRUE)
    
    project_id_str <- as.character(project_id)
    
    # âœ… FIXED: Query questionnaire_drafts directly, don't JOIN users
    query <- "
  SELECT
    COALESCE(qd.answers::json->>'Berufsgruppe', 'Sonstiges') as berufsgruppe,
    COUNT(DISTINCT qd.user_id) as n_users,
    SUM(CAST(COALESCE(qd.answers::json->>'group_size', '1') AS INTEGER)) as n_people
  FROM questionnaire_drafts qd
  WHERE qd.project_id::text = $1
    AND qd.questionnaire_id = 'peer_review'
    AND qd.answers IS NOT NULL
  GROUP BY COALESCE(qd.answers::json->>'Berufsgruppe', 'Sonstiges')
  ORDER BY berufsgruppe
  "
    
    breakdown <- DBI::dbGetQuery(con, query, params = list(project_id_str))
    
    # ðŸ” DEBUG
    cat("\n=== get_berufsgruppe_breakdown result ===\n")
    print(breakdown)
    print(paste("Columns:", paste(colnames(breakdown), collapse = ", ")))
    cat("===\n")
    
    return(breakdown)
  }
  
