  #------------------ Invitation Code Table (Admin only) ---------------------------
  all_invitation_codes <- reactive({
    invitation_data_changed()
    req(user_logged_in(), user_role() == "admin")
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con))
    codes <- DBI::dbGetQuery(
      con,
      "SELECT
    ic.code,
    ic.role,
    ic.assessment_type,
    ic.generated_at,
    ic.expires_at,
    CASE
      WHEN ic.used_at IS NOT NULL THEN 'Used'
      WHEN ic.expires_at <= NOW() THEN 'Expired'
      ELSE 'Unused'
    END AS status,
    ic.used_at,
    p.title AS project_name
  FROM invitation_codes ic
  LEFT JOIN projects p ON ic.project_id = p.id
  ORDER BY ic.generated_at DESC"
    )
    
    codes
  })
  
  output$current_invitations_table <- DT::renderDT({
    req(user_logged_in(), user_role() == "admin")
    all_invitation_codes()
  }, options = list(pageLength = 10, autoWidth = TRUE), selection = 'none', rownames = FALSE)
  
  #------------------ Invitation Code Generation (Admin only) ------------------------
  observeEvent(input$generate_codes, {
    req(user_logged_in(), user_role() == "admin")
    
    num_codes <- input$num_codes
    code_type <- input$code_type
    invite_role <- input$invite_role
    project_id <- as.integer(input$dashboard_project_selector_for_codes)
    req(project_id)
    
    if (num_codes <= 0) {
      output$code_generation_status <- renderUI(
        div(
          style = "padding: 10px; background-color: #f8d7da; border: 1px solid #f5c6cb; border-radius: 4px;",
          icon("exclamation-triangle", style = "color: #721c24;"),
          tags$span(style = "margin-left: 8px; color: #721c24;", "Bitte geben Sie eine positive Anzahl ein.")
        )
      )
      return()
    }
    
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con))
    
    generated_codes_list <- c()
    
    for (i in seq_len(num_codes)) {
      code <- uuid::UUIDgenerate()
      tryCatch({
        # âœ… No need to specify expires_at - database default handles it
        DBI::dbExecute(
          con,
          "INSERT INTO invitation_codes (code, role, assessment_type, generated_at, project_id, generated_by)
         VALUES ($1, $2, $3, NOW(), $4, $5)",
          params = list(code, invite_role, code_type, project_id, user_id())
        )
        generated_codes_list <- c(generated_codes_list, code)
      }, error = function(e) {
        warning(sprintf("Failed to insert code: %s; %s", code, e$message))
      })
    }
    
    # âœ… Get project name
    proj_name <- DBI::dbGetQuery(con,
                                 "SELECT title FROM projects WHERE id = $1",
                                 params = list(project_id))$title[1]
    
    # âœ… Calculate expiry date (30 days from now)
    expiry_date <- format(Sys.Date() + 30, "%d.%m.%Y")
    
    # âœ… Show success message with expiry info
    output$code_generation_status <- renderUI({
      div(style = "padding: 15px; background-color: #d4edda; border: 1px solid #c3e6cb; border-radius: 4px; margin-top: 15px;",
          div(
            style = "display: flex; align-items: center;",
            icon("check-circle", style = "color: #155724; font-size: 24px;"),
            div(
              style = "margin-left: 15px; color: #155724;",
              tags$strong(
                style = "font-size: 16px;",
                sprintf(
                  "âœ“ %d Einladungscode(s) erfolgreich generiert!",
                  length(generated_codes_list)
                )
              ),
              tags$div(
                style = "margin-top: 8px; font-size: 14px;",
                icon("clock"),
                sprintf(" GÃ¼ltig bis: %s (30 Tage)", expiry_date)
              ),
              tags$div(
                style = "margin-top: 5px; font-size: 14px;",
                icon("folder"),
                sprintf(" Projekt: %s", proj_name)
              )
            )
          ))
    })
    
    # âœ… Show codes in table with expiry
    output$generated_codes_table <- renderDataTable({
      data.frame(
        "Einladungscode" = generated_codes_list,
        "Rolle" = invite_role,
        "Typ" = code_type,
        "Projekt" = proj_name,
        "GÃ¼ltig bis" = expiry_date,
        stringsAsFactors = FALSE,
        check.names = FALSE
      )
    }, options = list(
      pageLength = 50,
      dom = 't',
      # Just show table (no search/pagination for small list)
      columnDefs = list(
        list(width = '300px', targets = 0),
        # Wide code column
        list(className = 'dt-center', targets = 1:4)  # Center other columns
      )
    ))
    
    # âœ… Trigger refresh of all codes table
    invitation_data_changed(invitation_data_changed() + 1)
    
    message(
      sprintf(
        "âœ“ Generated %d code(s) for project %s (expires: %s)",
        length(generated_codes_list),
        project_id,
        expiry_date
      )
    )
  })
  
  
