  #-------------------------labinfo_form_ui--------------------------------------
  
  output$labinfo_form_ui <- renderUI({
    
    message("ðŸ”µ labinfo_form_ui is EXECUTING NOW") 
    pid <- current_project_id()
    req(pid)
    role <- user_role()
    
    isolate({
      labinfo_ui_rendered(FALSE)
    })
    shinyjs::delay(800, {
      labinfo_ui_rendered(TRUE)
    })
    
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con))
    labinfo <- DBI::dbGetQuery(con,
                               "SELECT * FROM lab_info WHERE project_id = $1",
                               params = list(pid))
    
    # âœ… FIXED: robust helpers that ALWAYS return something usable
    getval <- function(field) {
      if (nrow(labinfo) > 0 && !is.na(labinfo[[field]][1])) labinfo[[field]][1] else ""
    }
    getval_num <- function(field) {
      if (nrow(labinfo) > 0 && !is.na(labinfo[[field]][1])) {
        suppressWarnings(as.numeric(labinfo[[field]][1]))
      } else {
        0
      }
    }
    getval_checkbox <- function(field) {
      if (nrow(labinfo) > 0 && !is.na(labinfo[[field]][1]) && nzchar(labinfo[[field]][1])) {
        strsplit(as.character(labinfo[[field]][1]), ", ")[[1]]
      } else {
        character(0)
      }
    }
    getval_radio <- function(field) {
      if (nrow(labinfo) > 0 && !is.na(labinfo[[field]][1]) && nzchar(labinfo[[field]][1])) {
        as.character(labinfo[[field]][1])
      } else {
        character(0)
      }
    }
    
    isolate({
      raw_anmerkungen <- if (nrow(labinfo) > 0) labinfo$anmerkungen[1] else NA
      parsed_items <- tryCatch({
        if (is.na(raw_anmerkungen) || !nzchar(trimws(as.character(raw_anmerkungen)))) {
          list()
        } else {
          parsed <- jsonlite::fromJSON(as.character(raw_anmerkungen), simplifyVector = FALSE)
          if (is.character(parsed) || is.atomic(parsed)) {
            parsed <- as.character(parsed)
            parsed <- parsed[nzchar(trimws(parsed))]
            lapply(parsed, function(s) list(beschreibung = s, anmerkung = ""))
          } else {
            parsed
          }
        }
      }, error = function(e) {
        message("âš  Could not parse saved anmerkungen: ", e$message)
        list()
      })
      
      if (length(parsed_items) > 0) {
        anmerkungen$counter <- length(parsed_items)
        anmerkungen$saved_items <- parsed_items
      } else if (is.null(anmerkungen$saved_items)) {
        anmerkungen$saved_items <- list()
      }
    })
    
    if (role %in% c("laborleitung", "admin")) {
      
      proj_info <- DBI::dbGetQuery(con,
                                   "SELECT title, einrichtung FROM projects WHERE id = $1",
                                   params = list(pid))
      
