          style = "margin-bottom: 20px; padding: 15px; background-color: #e8f4f8; border-left: 4px solid #003B73; border-radius: 4px;",
          div(
            style = "font-weight: bold; color: #003B73; font-size: 16px;",
            icon("folder", style = "font-size: 20px;"),
            tags$span(
              style = "margin-left: 10px;",
              if (role == "admin") paste0("Aktuelles Projekt: ", proj_title)
              else paste0("Ihr Projekt: ", proj_title)
            )
          ),
          if (nzchar(einrichtung_saved)) {
            tagList(
              tags$hr(style = "border-color: #003B73; opacity: 0.3; margin: 10px 0;"),
              tags$small(
                style = "color: #666;",
                icon("hospital"),
                tags$span(style = "margin-left: 5px;", "Einrichtung: "),
                tags$strong(einrichtung_saved)
              )
            )
          }
        ),
        
        box(
