                    textInput("name", labelMandatory("Name und Anschrift der Einrichtung:"),
                              value = getval("name"), width = "100%"),
                    textInput("Internetadresse", labelMandatory("Internetadresse der Einrichtung:"),
                              value = getval("internetadresse"), width = "100%"),
                    textInput("Trag", labelMandatory("TrÃ¤gerschaft mit ErlÃ¤uterung ob Ã¶ffentlich oder privat:"),
                              value = getval("trag"), width = "100%"),
                    textInput("Zug", "ZugehÃ¶rigkeit zu einem Unternehmensverbund:",
