  # â”€â”€ Shared enable logic â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  observe({
    enable_btn <- !is.null(input$alleine_oder_gruppe) && (
      input$alleine_oder_gruppe == "alleine" ||
        (
          input$alleine_oder_gruppe == "gruppe" &&
            !is.null(input$gruppen_groesse) &&
            input$gruppen_groesse != ""
        )
    )
    
    if (enable_btn) {
      shinyjs::enable("go_to_fuehrung")
      shinyjs::enable("go_to_mikrobiologie")
    } else {
      shinyjs::disable("go_to_fuehrung")
      shinyjs::disable("go_to_mikrobiologie")
    }
  })
  
