  #----------SAVE FREMDBEWERTUNG DRAFT - saves all fremdbewertung answers to DB
  
  
  #-------------- SUBMIT FREMDBEWERTUNG (Convert Draft to Responses) ---------------
  
  submit_all_fremdbewertung <- function() {
    cat("\n")
    cat("====================================================\n")
    cat(">>> SUBMIT_ALL_FREMDBEWERTUNG STARTED <<<\n")
    cat("Time:", as.character(Sys.time()), "\n")
    cat("====================================================\n")
    
    req(user_logged_in())
    cat("âœ“ Step 1: User logged in\n")
    
    req(user_role() %in% c("leading_peer", "co_peer"))
    cat("âœ“ Step 2: User role OK:", user_role(), "\n")
    
    current_user_id <- user_id()
    project_id <- current_project_id()
    submission_id <- uuid::UUIDgenerate()
    questionnaire_id <- "peer_fremdbewertung"
    
    cat("âœ“ Step 3: Variables set\n")
    cat("  - User ID:",
        current_user_id,
        "(class:",
        class(current_user_id),
        ")\n")
    cat("  - Project ID:", project_id, "\n")
    cat("  - Submission ID:", submission_id, "\n")
    
    if (is.null(project_id) ||
        project_id == "" || is.na(project_id)) {
      cat("âŒ FAIL: No project ID\n")
      showNotification("Fehler: Kein Projekt ausgewÃ¤hlt!",
                       type = "error",
                       duration = 5)
      return(invisible(FALSE))
    }
    
    cat("âœ“ Step 4: Project ID validated\n")
    
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con), add = TRUE)
    cat("âœ“ Step 5: Database connected\n")
    
    # Load draft
    cat("\n--- LOADING DRAFT ---\n")
    draft <- DBI::dbGetQuery(
      con,
      "SELECT answers, status FROM questionnaire_drafts
     WHERE user_id::text = $1::text
     AND project_id::text = $2::text
     AND questionnaire_id = $3
     ORDER BY last_saved DESC LIMIT 1",
      params = list(
        as.character(current_user_id),
        as.character(project_id),
        questionnaire_id
      )
    )
    
    cat("Draft query returned:", nrow(draft), "rows\n")
    
    if (nrow(draft) == 0) {
      cat("âŒ FAIL: No draft found\n")
      showNotification("Kein Entwurf gefunden.",
                       type = "warning",
                       duration = 5)
      return(invisible(FALSE))
    }
    
    cat("âœ“ Step 6: Draft found\n")
    cat("  - Status:", draft$status[1], "\n")
    
    if (draft$status[1] == "submitted") {
      cat("âŒ FAIL: Already submitted\n")
      showNotification(
        "Diese Fremdbewertung wurde bereits abgeschickt!",
        type = "warning",
        duration = 5
      )
      return(invisible(FALSE))
    }
    
    cat("âœ“ Step 7: Draft status OK (not submitted yet)\n")
    
    # Parse draft
    cat("\n--- PARSING DRAFT ---\n")
    saved_answers <- jsonlite::fromJSON(draft$answers[1])
    cat("âœ“ Step 8: Draft parsed, total fields:",
        length(saved_answers),
        "\n")
    
    # Convert to responses
    cat("\n--- BUILDING RESPONSE LIST ---\n")
    responses_list <- list()
    
    all_questions <- c(
      fuehrung_questions,
      mit_questions,
      pat_questions,
      ein_questions,
      qual_questions,
      qual_mibi_questions
    )
    
    cat("Total questions to process:",
        length(all_questions),
        "\n")
    
    processed <- 0
    skipped_na <- 0
    skipped_empty <- 0
    
    for (q in all_questions) {
      qid <- q$id
      score_key <- paste0("FremdbewertungNum_", qid)
      
      if (score_key %in% names(saved_answers)) {
        score <- saved_answers[[score_key]]
        
        if (is.null(score) || score == "") {
          skipped_empty <- skipped_empty + 1
          next
        }
        
        if (score == "N/A") {
          skipped_na <- skipped_na + 1
          next
        }
        
        text_key <- paste0("FremdbewertungText_", qid)
        text <- if (text_key %in% names(saved_answers))
          saved_answers[[text_key]]
        else
          ""
        
        responses_list[[length(responses_list) + 1]] <- list(
          user_id = as.integer(current_user_id),
          question_id = qid,
          response_value = as.character(score),
          text_value = if (!is.null(text) &&
                           text != "")
            as.character(text)
          else
            NA_character_,
          tag = NA_character_,
          assessment_type = "fremdbewertung",
          submission_id = submission_id,
          project_id = as.character(project_id),
          group_size = 1L
        )
        
        processed <- processed + 1
        
        # Debug first 3
        if (processed <= 3) {
          cat("  Added:", qid, "=", score, "\n")
        }
      }
    }
    
    cat("âœ“ Step 9: Response list built\n")
    cat("  - Processed:", processed, "\n")
    cat("  - Skipped (empty):", skipped_empty, "\n")
    cat("  - Skipped (N/A):", skipped_na, "\n")
    cat("  - TOTAL TO INSERT:", length(responses_list), "\n")
    
    if (length(responses_list) == 0) {
      cat("âŒ FAIL: No responses to insert\n")
      showNotification(
        "Keine Antworten zum Abschicken gefunden.",
        type = "warning",
        duration = 5
      )
      return(invisible(FALSE))
    }
    
    # Check for existing
    cat("\n--- CHECKING FOR EXISTING RESPONSES ---\n")
    existing <- DBI::dbGetQuery(
      con,
      "SELECT COUNT(*) as count FROM responses
     WHERE user_id = $1
     AND project_id::text = $2::text
     AND assessment_type = 'fremdbewertung'",
      params = list(as.integer(current_user_id), as.character(project_id))
    )
    
    cat("Existing responses for this user+project:",
        existing$count,
        "\n")
    
    if (existing$count > 0) {
      cat("âš  STOP: Showing overwrite confirmation modal\n")
      cat("====================================================\n\n")
      
      showModal(
        modalDialog(
          title = "Fremdbewertung bereits abgegeben",
          paste0(
            "Sie haben bereits ",
            existing$count,
            " Antworten abgegeben. Ãœberschreiben?"
          ),
          footer = tagList(
            modalButton("Abbrechen"),
            actionButton(
              "confirm_overwrite_fremd",
              "Ja, Ã¼berschreiben",
              class = "btn-danger"
            )
          )
        )
      )
      return(invisible(FALSE))
    }
    
    cat("âœ“ Step 10: No existing responses, proceeding to insert\n")
    
    # Insert responses
    cat("\n========== INSERTING RESPONSES ==========\n")
    
    tryCatch({
      sql <- "
      INSERT INTO responses (
        user_id, project_id, question_id, response_value, text_value,
        assessment_type, submission_id, tag, group_size, created_at
      ) VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9, NOW())
    "
      
      inserted <- 0
      
      for (i in 1:length(responses_list)) {
        resp <- responses_list[[i]]
        
        if (i <= 5 || i == length(responses_list)) {
          cat(
            "INSERT [",
            i,
            "/",
            length(responses_list),
            "]:",
            resp$question_id,
            "=",
            resp$response_value,
            "\n"
          )
        }
        
        result <- DBI::dbExecute(
          con,
          sql,
          params = list(
            resp$user_id,
            resp$project_id,
            resp$question_id,
            resp$response_value,
            resp$text_value,
            resp$assessment_type,
            resp$submission_id,
            resp$tag,
            resp$group_size
          )
        )
        
        if (i <= 5) {
          cat("  â†’ Result:", result, "\n")
        }
        
        inserted <- inserted + 1
      }
      
      cat("=========================================\n")
      cat("âœ“âœ“âœ“ INSERTED:", inserted, "RESPONSES âœ“âœ“âœ“\n")
      cat("=========================================\n")
      
      # Verify insertion
      cat("\n--- VERIFYING INSERTION ---\n")
      verify <- DBI::dbGetQuery(
        con,
        "
      SELECT COUNT(*) as count
      FROM responses
      WHERE submission_id = $1
    ",
        params = list(submission_id)
      )
      
      cat("Verification count:", verify$count, "\n")
      
      # Mark draft as submitted
      cat("\n--- MARKING DRAFT AS SUBMITTED ---\n")
      DBI::dbExecute(
        con,
        "UPDATE questionnaire_drafts
       SET status = 'submitted', last_saved = NOW()
       WHERE user_id::text = $1::text
       AND project_id::text = $2::text
       AND questionnaire_id = $3",
        params = list(
          as.character(current_user_id),
          as.character(project_id),
          questionnaire_id
        )
      )
      
      cat("âœ“ Draft status updated to 'submitted'\n")
      cat("\n====================================================\n")
      cat(">>> SUCCESS - FREMDBEWERTUNG SUBMITTED <<<\n")
      cat("====================================================\n\n")
      
      showNotification(
        paste0(
          "âœ… Fremdbewertung erfolgreich abgesendet! (",
          inserted,
          " Antworten)"
        ),
        type = "message",
        duration = 8
      )
      
      return(invisible(TRUE))
      
    }, error = function(e) {
      cat("\n")
      cat("====================================================\n")
      cat("âŒâŒâŒ ERROR DURING INSERT âŒâŒâŒ\n")
      cat("====================================================\n")
      cat("Error message:", e$message, "\n")
      cat("Error class:", class(e), "\n")
      cat("\nFull error object:\n")
      print(e)
      cat("\nTraceback:\n")
      print(traceback())
      cat("====================================================\n\n")
      
      showNotification(paste("âŒ Fehler:", e$message),
                       type = "error",
                       duration = 15)
      
      return(invisible(FALSE))
    })
  }
  
  
  
  #-----------------------Database queries: Responses tables per section----------
  #-FÃ¼hrung
  output$fuehrung_responses_leading_peer <- DT::renderDataTable({
    print(user_role())
    
    req(current_project_id())
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con))
    df <- DBI::dbGetQuery(
      con,
      "
    SELECT u.username, r.question_id, r.response_value, r.text_value
    FROM responses r
    JOIN users u ON u.id = r.user_id
    WHERE r.assessment_type = 'selbstbewertung'
      AND r.project_id = $1
      AND r.question_id LIKE 'F%'
    ORDER BY r.question_id, u.username
  ",
      params = list(current_project_id())
    )
    if (nrow(df) > 0) {
      df$question <- sapply(df$question_id, function(qid)
        get_question_label(fuehrung_questions, qid))
      df <- df[, c("username",
                   "question",
                   "response_value",
                   "text_value")]
    }
    df
  })
  
