      return(NULL)
    }
    
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con), add = TRUE)
    
    tryCatch({
      labinfo <- DBI::dbGetQuery(
        con,
        "SELECT created_at FROM lab_info WHERE project_id = $1",
        params = list(as.integer(project_id))
      )
      
      if (nrow(labinfo) > 0) {
        # âœ… Use proper timezone conversion
        last_saved <- as.POSIXct(labinfo$created_at[1], tz = "UTC")
        
        # Convert to local time
        local_time <- format(last_saved, "%d.%m.%Y %H:%M", tz = Sys.timezone())
        
        div(
          style = "color:#28a745;margin-top:12px;font-size:13px;",
          icon("check-circle"),
          sprintf(" Zuletzt gespeichert: %s", local_time)
        )
      } else {
        div(style = "color:#6c757d;margin-top:12px;font-size:13px;font-style:italic;",
            icon("info-circle"),
            " Noch nicht gespeichert")
      }
      
    }, error = function(e) {
      NULL
    })
  })
  
  # âœ… Main submit button observer (simplified - just calls save function)
  observeEvent(input$submit_labinfo, {
    pid <- current_project_id()
    
    if (is.null(pid) || pid == "") {
      showNotification("Bitte wÃ¤hlen Sie ein Projekt!", type = "error")
      return()
    }
    
    # Call the save function
    result <- save_lab_info_data()
    
    if (result) {
      # Also save einrichtung to projects table
      einrichtung_val <- if (!is.null(input$name) &&
                             nchar(input$name) > 0) {
        as.character(input$name)
      } else {
        NA_character_
      }
      
      if (!is.null(einrichtung_val) &&
          !is.na(einrichtung_val) && nchar(einrichtung_val) > 0) {
        con_temp <- get_db_con()
        on.exit(DBI::dbDisconnect(con_temp), add = TRUE)
        
        tryCatch({
          DBI::dbExecute(
            con_temp,
            "UPDATE projects SET einrichtung = $1 WHERE id = $2",
            params = list(einrichtung_val, as.integer(pid))
          )
          message("âœ“ Einrichtung saved to projects: ", einrichtung_val)
        }, error = function(e) {
          message("âš  Error saving einrichtung: ", e$message)
        })
      }
      
      showNotification(
        "Labordaten erfolgreich gespeichert!",
        type = "message",
        duration = 3
      )
    }
  })
  
  
  
