  # Lab info panel: show read-only for regular users
  output$labinfo_panel <- renderUI({
    req(user_id())
    project_id <- get_labinfo_project_id()
    req(!is.null(project_id) && project_id != "")
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con))
    labinfo <- DBI::dbGetQuery(con,
                               "SELECT * FROM lab_info WHERE project_id = $1",
                               params = list(project_id))
    if (nrow(labinfo) == 0) {
      return(h5("Keine Labordaten fÃ¼r dieses Peer Review hinterlegt."))
    }
    
    # âœ… REDESIGNED: was a single flat <dl> dump of ~40 fields with no
    # grouping or styling - hard to scan. Now grouped into the same
    # sections used elsewhere in the app (Grundlagen und Organisation,
    # Personal, EDV und Kennzahlen, ...) as clean Bootstrap tables, and
    # empty fields show "Keine Angabe" instead of blank/NA. Also drops the
    # two entries that only ever showed NA (PeerReview Beschreibungen /
    # Anmerkungen - never populated by anything).
    gv <- function(field) {
      if (!(field %in% names(labinfo))) return("Keine Angabe")
      v <- labinfo[[field]][1]
      if (is.null(v) || is.na(v) || !nzchar(trimws(as.character(v)))) "Keine Angabe" else as.character(v)
    }
    
    section_table <- function(title, rows) {
      tagList(
        tags$h4(title, style = "color:#003B73; margin-top:22px; border-bottom:2px solid #136377; padding-bottom:6px;"),
        tags$table(
          class = "table table-striped table-bordered",
          style = "background:white;",
          tags$tbody(
            lapply(rows, function(r) {
              tags$tr(
                tags$td(style = "width:35%; font-weight:600; color:#333;", r$label),
                tags$td(gv(r$field))
              )
            })
          )
        )
      )
    }
    
    # "Hauptthema / Anlass fÃ¼r das Peer Review" (Beschreibung + Anmerkung
    # des Peers, stored as JSON in lab_info.anmerkungen) is the most
    # important information for the peers, so it is shown first, highlighted
    # and in bold, above all other lab data. Accepts both the current
    # format (list of {beschreibung, anmerkung}) and a legacy plain vector.
    anlass_items <- tryCatch({
      raw <- if ("anmerkungen" %in% names(labinfo)) labinfo$anmerkungen[1] else NA
      if (is.null(raw) || is.na(raw) || !nzchar(trimws(as.character(raw)))) {
        list()
      } else {
        parsed <- jsonlite::fromJSON(as.character(raw), simplifyVector = FALSE)
        if (is.character(parsed) || (is.atomic(parsed) && length(parsed) > 0)) {
          lapply(as.character(parsed)[nzchar(trimws(as.character(parsed)))],
                 function(s) list(beschreibung = s, anmerkung = ""))
        } else {
          Filter(function(it) {
            nzchar(trimws(as.character(it$beschreibung %||% ""))) ||
              nzchar(trimws(as.character(it$anmerkung %||% "")))
          }, parsed)
        }
      }
    }, error = function(e) {
      message("âš  Could not parse lab_info.anmerkungen: ", e$message)
      list()
    })

    anlass_block <- tags$div(
      style = paste0("background:#fff8e1; border-left:6px solid #003B73; ",
                     "border-radius:4px; padding:14px 18px; margin:10px 0 20px 0; ",
                     "box-shadow:0 2px 6px rgba(0,0,0,0.12);"),
      tags$h3(icon("bullseye"), " Hauptthema / Anlass fÃ¼r das Peer Review",
              style = "color:#003B73; font-weight:800; margin-top:0;"),
      if (length(anlass_items) == 0) {
        tags$p(style = "font-weight:700; color:#666;", "Keine Angaben hinterlegt.")
      } else {
        tags$ol(
          style = "padding-left:20px; margin-bottom:0;",
          lapply(anlass_items, function(it) {
            desc <- trimws(as.character(it$beschreibung %||% ""))
            note <- trimws(as.character(it$anmerkung %||% ""))
            tags$li(
              style = "margin-bottom:12px; font-size:15px;",
              if (nzchar(desc)) tags$div(tags$span("Beschreibung: ", style = "color:#136377; font-weight:800;"),
                                         tags$strong(desc)),
              if (nzchar(note)) tags$div(tags$span("Anmerkung des Peers: ", style = "color:#136377; font-weight:800;"),
                                         tags$strong(note))
            )
          })
        )
      }
    )

    tagList(
      h4("Labordaten (nur lesbar)", style = "color:#003B73;"),

      anlass_block,

      section_table("Grundlagen und Organisation", list(
        list(label = "Name und Anschrift", field = "name"),
        list(label = "Internetadresse", field = "internetadresse"),
        list(label = "TrÃ¤gerschaft", field = "trag"),
        list(label = "ZugehÃ¶rigkeit zu einem Unternehmensverbund", field = "zug"),
        list(label = "Ansprechpartner", field = "ansprechpartner"),
        list(label = "Email", field = "email"),
        list(label = "Telefonnummer", field = "telefonnummer"),
        list(label = "Ã–ffnungszeiten", field = "oeffnungzeiten"),
        list(label = "Weitere Angaben", field = "angaben")
      )),
      
      section_table("Versorgung, Laborbereiche & Leistungsspektrum", list(
        list(label = "Versorgung", field = "versorgung"),
        list(label = "Laborbereiche", field = "laborbereiche"),
        list(label = "Leistungsspektrum", field = "leistungsspektrum"),
        list(label = "Ausstattung", field = "ausstattung"),
        list(label = "Hauptlieferanten", field = "hauptlieferanten")
      )),
      
      section_table("Farbcodesysteme, Studien & Service", list(
        list(label = "Werden Farbcodesysteme einheitlich genutzt?", field = "question_binary_1"),
        list(label = "Welche Farbcodesysteme werden verwendet", field = "farbcodesystem"),
        list(label = "Nimmt Ihr Labor an Studien teil?", field = "question_binary_2"),
        list(label = "Verfahren zur Auftragsgenerierung", field = "auftragsgenerierung"),
        list(label = "Hinweise zur PrÃ¤analytik", field = "praeanalytik"),
        list(label = "BefundÃ¼bermittlung", field = "befunduebermittlung"),
        list(label = "Service- und Beratungsleistungen", field = "beratungsleistungen"),
        list(label = "Werden Hinweise zur DRG Gruppierung ausgegeben?", field = "question_binary_3")
      )),
      
      section_table("Personal", list(
        list(label = "Personal gesamt", field = "anzahl_total"),
        list(label = "Davon mit medizinischer Ausbildung", field = "anzahl_mit"),
        list(label = "Davon FachÃ¤rzte", field = "davon_fachaerzte"),
        list(label = "Davon in Weiterbildung", field = "davon_weiterbildung"),
        list(label = "Planstellen gesamt", field = "anzahl_planstellen"),
