  observeEvent(input$Organigramm, {
    req(input$Organigramm)
    req(current_project_id())
    
    tryCatch({
      file_info  <- input$Organigramm
      project_id <- current_project_id()
      
      # âœ… 1. Check file extension
      if (!grepl("\\.pdf$", tolower(file_info$name))) {
        showNotification("Nur PDF-Dateien sind erlaubt.",
                         type = "error",
                         duration = 5)
        return()
      }
      
      # âœ… 2. Check file size (max 10 MB)
      max_size_bytes <- 10 * 1024 * 1024
      if (file_info$size > max_size_bytes) {
        showNotification("Datei zu groÃŸ. Maximum: 10 MB.",
                         type = "error",
                         duration = 5)
        return()
      }
      
      # âœ… 3. Check PDF magic bytes (real PDF starts with %PDF-)
      con_file <- file(file_info$datapath, "rb")
      header   <- readBin(con_file, "raw", n = 5)
      close(con_file)
      
      expected <- chartr("", "", "%PDF-")
      actual   <- rawToChar(header)
      
      if (!startsWith(actual, "%PDF-")) {
        showNotification(
          "UngÃ¼ltige Datei. Nur echte PDF-Dateien sind erlaubt.",
          type = "error",
          duration = 5
        )
        message("âœ— Invalid PDF header: ", actual)
        return()
      }
      
      # âœ… 4. Use fixed server-side filename â€” NEVER use the user's filename
      # This prevents path traversal attacks
      dest_path <- file.path(UPLOAD_DIR,
                             paste0(
                               "organigramm_project_",
                               as.integer(project_id),
                               ".pdf"
                             ))
      
      copy_ok <- file.copy(file_info$datapath, dest_path, overwrite = TRUE)
      
      if (!copy_ok) {
        showNotification(
          "Datei konnte nicht gespeichert werden.",
          type = "error",
          duration = 8
        )
        return()
      }
      
      con <- get_db_con()
      on.exit(DBI::dbDisconnect(con), add = TRUE)
      
      DBI::dbExecute(
        con,
        "
      INSERT INTO lab_info (project_id, organigramm_filename)
      VALUES ($1, $2)
      ON CONFLICT (project_id) DO UPDATE SET
        organigramm_filename = EXCLUDED.organigramm_filename
    ",
        params = list(as.integer(project_id), dest_path)
      )
      
      showNotification("âœ“ Organigramm gespeichert.",
                       type = "message",
                       duration = 4)
      message("âœ“ Organigramm saved: ", dest_path)
      
    }, error = function(e) {
      message("âœ— Organigramm upload ERROR: ", e$message)
      showNotification(paste("Fehler:", e$message),
                       type = "error",
                       duration = 8)
    })
  })
  
  append_organigramm_if_exists <- function(main_pdf_path, project_id) {
    tryCatch({
      con <- get_db_con()
      on.exit(DBI::dbDisconnect(con), add = TRUE)
      
      result <- DBI::dbGetQuery(
        con,
        "SELECT organigramm_filename FROM lab_info WHERE project_id = $1",
        params = list(as.integer(project_id))
      )
      
      if (nrow(result) == 0 ||
          is.na(result$organigramm_filename[1]) ||
          !nzchar(result$organigramm_filename[1])) {
        message("  No Organigramm in DB â€” skipping")
        return(main_pdf_path)
      }
      
      org_path <- result$organigramm_filename[1]
      message("  Organigramm path: ", org_path)
      
      if (!file.exists(org_path)) {
        message("  âœ— File not found â€” skipping")
        return(main_pdf_path)
      }
      
      message("  âœ“ Found (", file.size(org_path), " bytes) â€” appending")
      
      combined_path <- sub("\\.pdf$", "_with_organigramm.pdf", main_pdf_path)
      pdftools::pdf_combine(input = c(main_pdf_path, org_path),
                            output = combined_path)
      
      if (file.exists(combined_path) &&
          file.size(combined_path) > 0) {
        message("  âœ“ Combined: ", file.size(combined_path), " bytes")
        return(combined_path)
      }
      
      return(main_pdf_path)
      
    }, error = function(e) {
      message("  âœ— ERROR: ", e$message)
      return(main_pdf_path)
    })
  }
  
