  # 3. Download handler for the main report
  output$downloadReport <- downloadHandler(
    filename = function() {
      project_id <- input$report_project_selector
      
      if (is.null(project_id) ||
          project_id == "" || is.na(as.integer(project_id))) {
        showNotification("Bitte wÃ¤hlen Sie ein gÃ¼ltiges Projekt aus.", type = "error")
        return(NULL)
      }
      
      con <- get_db_con()
      on.exit(DBI::dbDisconnect(con))
      proj <- DBI::dbGetQuery(con,
                              "SELECT title FROM projects WHERE id = $1",
                              params = list(as.integer(project_id)))
      project_name <- if (nrow(proj) > 0)
        proj$title[1]
      else
        "projekt"
      
      paste0("Projektabschlussbericht_",
             project_name,
             "_",
             current_username(),
             ".pdf")
    },
    content = function(file) {
      req(input$report_project_selector)
      project_id <- as.integer(input$report_project_selector)
      
      temp_env <- new.env()
      original_wd <- getwd()
      tmpdir <- tempdir()
