            "Keine Labordaten fÃ¼r dieses Projekt. Bericht kann nicht erstellt werden.",
            type = "error"
          )
          file.create(file)
          cat("Keine Labordaten fÃ¼r dieses Projekt.", file = file)
          return(NULL)
        }
        
        responses <- DBI::dbGetQuery(
          con,
          "SELECT r.*, u.username, u.role FROM responses r JOIN users u ON r.user_id = u.id WHERE r.project_id = $1",
          params = list(project_id)
        )
        
        DBI::dbDisconnect(con)
        con <- NULL
        
        # Helper function to get responses for a section, robust to empty data
        get_section_df <- function(question_list, responses_df) {
          qids <- sapply(question_list, function(q)
            q$id)
          qlabels <- setNames(sapply(question_list, function(q)
            q$label), qids)
          
          sub <- responses_df[responses_df$question_id %in% qids, c("question_id", "response_value", "text_value"), drop = FALSE]
          
          if (nrow(sub) == 0) {
            return(
              data.frame(
                Frage = character(0),
                Antwort = character(0),
                BegrÃ¼ndung = character(0),
                stringsAsFactors = FALSE
              )
            )
          }
          
          data.frame(
            Frage = unname(qlabels[as.character(sub$question_id)]),
            Antwort = as.character(sub$response_value),
            BegrÃ¼ndung = as.character(sub$text_value),
            stringsAsFactors = FALSE
          )
        }
        
        fuehrung_df <- get_section_df(fuehrung_questions, responses)
        mitarbeitende_df <- get_section_df(mit_questions, responses)
        pat_df <- get_section_df(pat_questions, responses)
        ein_df <- get_section_df(ein_questions, responses)
        qual_df <- get_section_df(qual_questions, responses)
        
        # Plot generation for the main report
        save_cumulative_spider_plot(
          fuehrung_questions,
          responses,
          file.path(tmpdir, "fuehrung_plot.png"),
          "FÃ¼hrung (Mittelwert)",
          "rgba(51, 160, 255, 0.4)",
          "#3390ff"
        )
        save_cumulative_spider_plot(
          mit_questions,
          responses,
          file.path(tmpdir, "mit_plot.png"),
          "Mitarbeitende (Mittelwert)",
          "rgba(255, 158, 74, 0.4)",
          "#ff9e4a"
        )
        save_cumulative_spider_plot(
          pat_questions,
          responses,
          file.path(tmpdir, "pat_plot.png"),
          "Patienten und AngehÃ¶rige (Mittelwert)",
          "rgba(129, 199, 132, 0.4)",
          "#81c784"
        )
        save_cumulative_spider_plot(
          ein_questions,
          responses,
          file.path(tmpdir, "einsender_plot.png"),
          "Einsender & Kooperationspartner (Mittelwert)",
          "rgba(255, 99, 132, 0.4)",
          "#ff6384"
        )
        save_cumulative_spider_plot(
          qual_questions,
          responses,
          file.path(tmpdir, "plot_qual.png"),
          "QualitÃ¤tsindikatoren (Mittelwert)",
          "rgba(255, 206, 86, 0.4)",
          "#ffce56"
        )
        
        assign("labinfo", labinfo, envir = temp_env)
        assign("fuehrung_responses", fuehrung_df, envir = temp_env)
        assign("mitarbeitende_responses", mitarbeitende_df, envir = temp_env)
        assign("pat_responses", pat_df, envir = temp_env)
        assign("ein_responses", ein_df, envir = temp_env)
        assign("qual_responses", qual_df, envir = temp_env)
        
        input_list <- as.list(labinfo[1, ])
        input_list$username <- current_username()
        proj <- DBI::dbGetQuery(get_db_con(),
                                "SELECT title FROM projects WHERE id = $1",
                                params = list(project_id))
        input_list$project_title <- if (nrow(proj) > 0)
          proj$title[1]
        else
          "Unbekanntes Projekt"
        input_list$Berufsgruppe <- input$Berufsgruppe
        
        assign("input", input_list, envir = temp_env)
        
        rmarkdown::render(
          "report.Rnw",
          output_file = file,
          output_dir = tmpdir,
          envir = temp_env
        )
        
      }, error = function(e) {
        showNotification(
          paste("Fehler beim Erstellen des Berichts:", e$message),
          type = "error",
          duration = NULL
        )
        warning("Error rendering report:", e$message)
        file.create(file)
        cat("Fehler beim Erstellen des Berichts:\n\n",
            e$message,
            file = file)
      }, finally = {
        if (!is.null(con) && DBI::dbIsValid(con)) {
          DBI::dbDisconnect(con)
        }
      })
    },
    contentType = "application/pdf"
  )
  
