  # 4) Build Q/A table safely
  build_question_answer_table <- function(questions, responses_df) {
    question_labels <- sapply(questions, function(q)
      q$label)
    question_ids    <- sapply(questions, function(q)
      q$id)
    if (length(question_ids) == 0) {
      return(data.frame(
        Frage = character(0),
        Antwort = character(0),
        stringsAsFactors = FALSE
      ))
    }
    rows <- lapply(seq_along(question_ids), function(i) {
      qid   <- question_ids[i]
      label <- question_labels[i]
      these <- responses_df[responses_df$question_id == qid, ]
      if (nrow(these) == 0) {
        return(data.frame(
          Frage = label,
          Antwort = "",
          stringsAsFactors = FALSE
        ))
      }
      all_answers <- vapply(seq_len(nrow(these)), function(j) {
        rv  <- as.character(these$response_value[j])
        tv  <- as.character(these$text_value[j])
        ans <- if (!is.na(rv) &&
                   nzchar(rv) && rv != "NA")
          rv
        else
          ""
        txt <- if (!is.na(tv) &&
                   nzchar(tv) && tv != "NA")
          tv
        else
          ""
        if (nzchar(ans) && nzchar(txt))
          paste0(ans, " (", txt, ")")
        else if (nzchar(ans))
          ans
        else if (nzchar(txt))
          txt
        else
          ""
      }, character(1))
      data.frame(
        Frage = label,
        Antwort = paste(all_answers, collapse = "; "),
        stringsAsFactors = FALSE
      )
    })
    ret <- do.call(rbind, rows)
    rownames(ret) <- NULL
    ret
  }
  
  # 5) Plot saving helpers (global)
  save_plot_image <- function(p,
                              file,
                              width = 800,
                              height = 600) {
    ok <- FALSE
    if ("save_image" %in% getNamespaceExports("plotly")) {
      try({
        plotly::save_image(p,
                           file = file,
                           width = width,
                           height = height)
        ok <- TRUE
      }, silent = TRUE)
    }
    if (!ok && requireNamespace("webshot2", quietly = TRUE)) {
      tmp_html <- tempfile(fileext = ".html")
      htmlwidgets::saveWidget(p, tmp_html, selfcontained = TRUE)
      try({
        webshot2::webshot(
          tmp_html,
          file = file,
          vwidth = width,
          vheight = height
        )
        ok <- TRUE
      }, silent = TRUE)
    }
    if (!ok) {
      png(file, width = width, height = height)
      plot.new()
      text(0.5, 0.5, "Plot nicht verfÃ¼gbar", cex = 1.2)
      dev.off()
    }
  }
  
  
  # Helper for extracting numbers from question labels
  get_num <- function(q)
    as.numeric(gsub("\\D", "", q$label))
  
  # Helper to extract all answers as data.frame (section, label, numeric, text)
  gather_answers <- function() {
    all_responses <- list()
    
    for (section_key in names(topic_questions)) {
      questions <- topic_questions[[section_key]]
      
      for (q in questions) {
        qid <- q$id
        score_id <- paste0("Freitext", qid)
        text_id <- paste0("Freitext_text", qid)
        
        score <- input[[score_id]]
        text_val <- input[[text_id]]
        
        if ((is.null(score) || score == "N/A" || score == "") &&
            (is.null(text_val) || text_val == "")) {
          next
        }
        
        all_responses[[length(all_responses) + 1]] <- data.frame(
          Section = section_key,
          # âœ… Use GLOBAL number for report
          Frage = paste0(q$number, ". ", q$label),
          Antwort = ifelse(is.null(score) ||
                             score == "N/A", "", score),
          BegrÃ¼ndung = ifelse(is.null(text_val), "", text_val),
          stringsAsFactors = FALSE
        )
      }
    }
    
    if (length(all_responses) > 0) {
      dplyr::bind_rows(all_responses)
    } else {
      data.frame(
        Section = character(0),
        Frage = character(0),
        Antwort = character(0),
        BegrÃ¼ndung = character(0),
        stringsAsFactors = FALSE
      )
    }
  }
  
  save_plot_image <- function(p,
                              filename,
                              width = 800,
                              height = 600) {
    ok <- FALSE
    # Try kaleido save_image
    if (requireNamespace("plotly", quietly = TRUE)) {
      try({
        plotly::save_image(p, filename, width = width, height = height)
        ok <- file.exists(filename) &&
          file.info(filename)$size > 0
      }, silent = TRUE)
    }
    if (!ok) {
      # Fallback placeholder
      png(filename, width = width, height = height)
      par(mar = c(0, 0, 0, 0))
      plot.new()
      text(
        0.5,
        0.5,
        "Bild konnte nicht erzeugt werden",
        cex = 1.2,
        col = "red"
      )
      dev.off()
    }
  }
  
  # Function building a single-user spider (returns plotly object)
  single_user_spider <- function(question_list,
                                 responses_df,
                                 title,
                                 fill_color,
                                 line_color) {
    qids   <- vapply(question_list, function(q)
      q$id, character(1))
    labels <- vapply(question_list, function(q)
      q$label, character(1))
    vals <- numeric(length(qids))
    for (i in seq_along(qids)) {
      idx <- which(responses_df$question_id == qids[i])
      if (length(idx) == 1) {
        v <- suppressWarnings(as.numeric(responses_df$response_value[idx]))
        vals[i] <- ifelse(is.na(v), NA, v)
      } else {
        vals[i] <- NA
      }
    }
    all_na <- all(is.na(vals))
    plotly::plot_ly(
      type = "scatterpolar",
      mode = "lines+markers",
      r = vals,
      theta = labels,
      fill = "toself",
      fillcolor = fill_color,
      line = list(color = line_color, width = 3),
      marker = list(
        symbol = "circle",
        size = 8,
        color = line_color,
        line = list(color = "white", width = 2)
      )
    ) %>%
      plotly::layout(
        title = list(
          text = if (all_na)
            paste0(title, " (Keine Antworten)")
          else
            title,
          y = 0.95,
          font = list(size = 16, family = "Arial Black")
        ),
        polar = list(
          radialaxis = list(visible = TRUE, range = c(0, 5)),
          angularaxis = list(rotation = 90)
        ),
        showlegend = FALSE
      )
  }
  
  # Helper to extract a section table for the current user
  user_section_table <- function(question_list, responses_df) {
    qids <- vapply(question_list, function(q)
      q$id, character(1))
    labs <- vapply(question_list, function(q)
      q$label, character(1))
    sub <- responses_df[responses_df$question_id %in% qids, , drop = FALSE]
    if (nrow(sub) == 0)
      return(data.frame(
        Frage = labs,
        Antwort = NA,
        BegrÃ¼ndung = NA
      ))
    # Map label
    sub$Frage <- labs[match(sub$question_id, qids)]
    sub$Antwort <- sub$response_value
    sub$BegrÃ¼ndung <- sub$text_value
    out <- sub[, c("Frage", "Antwort", "BegrÃ¼ndung")]
    # Ensure all questions appear (even unanswered)
    missing <- setdiff(labs, out$Frage)
    if (length(missing) > 0) {
      out <- rbind(
        out,
        data.frame(
          Frage = missing,
          Antwort = NA,
          BegrÃ¼ndung = NA,
          stringsAsFactors = FALSE
        )
      )
    }
    out[match(labs, out$Frage), ]
  }
  
  
  # ------------------FMSB Radar Chart Functions----------------------------------
  
  make_radar_df_from_inputs_fmsb <- function(input,
                                             questions,
                                             group_name = "Aktueller Stand",
                                             binary_qnums = integer()) {
    # âœ… Filter out binary questions using GLOBAL number
    non_binary_questions <- if (length(binary_qnums) > 0) {
      Filter(function(q)
        ! (q$number %in% binary_qnums), questions)
    } else {
      questions
    }
    
    # Get values
    vals <- sapply(non_binary_questions, function(q) {
      qid <- q$id
      v <- input[[paste0("Freitext", qid)]]
      
      if (is.null(v) || v == "" || v == "N/A" || is.na(v)) {
        return(0)
      }
      
      val <- suppressWarnings(as.numeric(v))
      return(ifelse(is.na(val), 0, val))
    })
    
    # âœ… Get GLOBAL question numbers for axis labels
    axis_names <- sapply(non_binary_questions, function(q)
      as.character(q$number))
    
    # Debug
    message("  Question IDs: ", paste(sapply(non_binary_questions, function(q)
      q$id), collapse = ", "))
    message("  Global numbers: ", paste(
      sapply(non_binary_questions, function(q)
        q$number),
      collapse = ", "
    ))
    message("  Local numbers (axis): ", paste(axis_names, collapse = ", "))
    message("  Values: ", paste(vals, collapse = ", "))
    
    # Ensure we have data
    if (length(vals) == 0) {
      return(data.frame(
        `1` = c(5, 0, 0),
        check.names = FALSE,
        row.names = c("Max", "Min", group_name)
      ))
    }
    
    # Create max/min
    max_min <- data.frame(matrix(c(5, 0), nrow = 2, ncol = length(vals)), check.names = FALSE)
    colnames(max_min) <- axis_names
    rownames(max_min) <- c("Max", "Min")
    
    # Create data row
    data_row <- data.frame(matrix(vals, nrow = 1), check.names = FALSE)
    colnames(data_row) <- axis_names
    rownames(data_row) <- group_name
    
    # Combine
    df <- rbind(max_min, data_row)
    
    # âœ… ADD THIS
    message("\n=== FINAL RADAR DF: ", group_name, " ===")
    message("Dimensions: ", nrow(df), " x ", ncol(df))
    message("Column names: ", paste(colnames(df), collapse = ", "))
    message("Row 3 (Data): ", paste(df[3, ], collapse = ", "))
    message("=============================\n")
    
    return(df)
  }
  
  
  make_fmsb_radar_png <- function(radar_df,
                                  title,
                                  colour = "#003B73",
                                  filename = "radar_plot.png",
                                  width = 800,
                                  height = 800) {
    # âœ… ADD DEBUG
    message("\n=== make_fmsb_radar_png: ", title, " ===")
    message("Input dimensions: ", nrow(radar_df), " x ", ncol(radar_df))
    if (nrow(radar_df) >= 3) {
      message("Row 3 values: ", paste(as.numeric(radar_df[3, ]), collapse = ", "))
    }
    
    # âœ… Validate input
    if (is.null(radar_df) ||
        nrow(radar_df) < 3 || ncol(radar_df) == 0) {
      message("  âš  Invalid data")
      png(filename,
          width = width,
          height = height,
          res = 120)
      plot.new()
      text(0.5, 0.5, "Keine Daten vorhanden", cex = 1.5)
      dev.off()
      return(filename)
    }
    
    # âœ… CRITICAL FIX: Convert entire data frame to numeric matrix, then back to df
    radar_matrix <- as.matrix(radar_df)
    mode(radar_matrix) <- "numeric"  # Force numeric
    radar_df <- as.data.frame(radar_matrix, stringsAsFactors = FALSE)
    
    message("  After conversion - Row 3: ",
            paste(radar_df[3, ], collapse = ", "))
    message("  Data types: ", paste(sapply(radar_df, class), collapse = ", "))
    
    # Open PNG device
    png(filename,
        width = width,
        height = height,
        res = 120)
    
    # âœ… Simple equal margins
    op <- par(mar = c(1, 1, 3, 1))
    
    tryCatch({
      # âœ… Ensure column names
      if (is.null(colnames(radar_df)) ||
          length(colnames(radar_df)) != ncol(radar_df)) {
        colnames(radar_df) <- paste0("Q", seq_len(ncol(radar_df)))
      }
      
      message("  Calling radarchart()...")
      
      # Call radarchart
      radarchart(
        radar_df,
        axistype = 1,
        
        # Customize the polygon
        pcol = colour,
        pfcol = scales::alpha(colour, 0.5),
        plwd = 2,
        plty = 1,
        
        # Customize the grid
        cglcol = "grey",
        cglty = 1,
        cglwd = 0.8,
        
        # Customize the axis
        axislabcol = "grey",
        
        # Labels
        vlcex = 0.7,
        vlabels = colnames(radar_df),
        
        # Axis labels
        caxislabels = c("0", "1", "2", "3", "4", "5"),
        calcex = 0.7,
        
        # Title
        title = title,
        cex.main = 1.2
      )
      
      message("  âœ“ Plot created")
      
    }, error = function(e) {
      message("  âœ— ERROR: ", e$message)
      plot.new()
      text(0.5, 0.5, paste("Fehler:", e$message), cex = 1.0)
    })
    
    par(op)
    dev.off()
    
    message("=============================\n")
    
    return(filename)
  }
  
  
  # ============================================================================
  # GGPLOT2 RADAR CHART (replaces fmsb)
  # ============================================================================
  
  make_ggplot_radar_png <- function(radar_df,
                                    title,
                                    colour = "#003B73",
                                    filename = "radar_plot.png",
                                    width = 800,
                                    height = 800) {
    library(ggplot2)
    
    message("\n=== make_ggplot_radar_png: ", title, " ===")
    
    # Validate input
    if (is.null(radar_df) ||
        nrow(radar_df) < 3 || ncol(radar_df) == 0) {
      message("  âš  Invalid data")
      png(filename,
          width = width,
          height = height,
          res = 120)
      plot.new()
      text(0.5, 0.5, "Keine Daten vorhanden", cex = 1.5)
      dev.off()
      return(filename)
    }
    
    # Extract data (row 3)
    values <- as.numeric(radar_df[3, ])
    labels <- colnames(radar_df)
    n <- length(values)
    
    message("  Values: ", paste(values, collapse = ", "))
    message("  Labels: ", paste(labels, collapse = ", "))
    
    # Create angles for each axis (starting from top, going clockwise)
    angles <- seq(0, 2 * pi, length.out = n + 1)[1:n]
    
    # Convert polar to cartesian coordinates
    to_cartesian <- function(r, angle) {
      list(x = r * sin(angle), y = r * cos(angle))
    }
    
    # Create polygon data
    polygon_coords <- lapply(1:n, function(i) {
      coords <- to_cartesian(values[i], angles[i])
      data.frame(x = coords$x, y = coords$y)
    })
    polygon_df <- do.call(rbind, polygon_coords)
    polygon_df <- rbind(polygon_df, polygon_df[1, ])  # Close polygon
    
    # Create grid circles
    grid_circles <- lapply(0:5, function(r) {
      angle_seq <- seq(0, 2 * pi, length.out = 100)
      coords <- lapply(angle_seq, function(a)
        to_cartesian(r, a))
      data.frame(
        x = sapply(coords, function(c)
          c$x),
        y = sapply(coords, function(c)
          c$y),
        r = r
      )
    })
    grid_df <- do.call(rbind, grid_circles)
    
    # Create axis lines
    axis_lines <- lapply(1:n, function(i) {
      coords <- to_cartesian(5.5, angles[i])
      data.frame(
        x = 0,
        y = 0,
        xend = coords$x,
        yend = coords$y
      )
    })
    axis_df <- do.call(rbind, axis_lines)
    
    # Create axis labels
    label_coords <- lapply(1:n, function(i) {
      coords <- to_cartesian(6.2, angles[i])
      data.frame(x = coords$x,
                 y = coords$y,
                 label = labels[i])
    })
    label_df <- do.call(rbind, label_coords)
    
    # Create plot
    p <- ggplot() +
      # Grid circles
      geom_path(
        data = grid_df,
        aes(x = x, y = y, group = r),
        color = "grey85",
        linewidth = 0.5
      ) +
      # Grid labels
      geom_text(
        data = data.frame(
          x = 0,
          y = 0:5,
          label = 0:5
        ),
        aes(x = x, y = y, label = label),
        color = "grey50",
        size = 3,
        hjust = 1.5
      ) +
      # Axis lines
      geom_segment(
        data = axis_df,
        aes(
          x = x,
          y = y,
          xend = xend,
          yend = yend
        ),
        color = "grey70",
        linewidth = 0.5
      ) +
      # Data polygon
      geom_polygon(
        data = polygon_df,
        aes(x = x, y = y),
        fill = scales::alpha(colour, 0.3),
        color = colour,
        linewidth = 1.5
      ) +
      # Data points
      geom_point(data = polygon_df[1:n, ],
                 aes(x = x, y = y),
                 color = colour,
                 size = 2.5) +
      # Axis labels
      geom_text(
        data = label_df,
        aes(x = x, y = y, label = label),
        size = 3.5,
        fontface = "bold"
      ) +
      # Title
      ggtitle(title) +
      coord_fixed() +
      xlim(c(-7, 7)) +
      ylim(c(-7, 7)) +
      theme_void() +
      theme(plot.title = element_text(
        hjust = 0.5,
        size = 16,
        face = "bold",
        margin = margin(b = 10)
      ))
    
    # Save
    ggsave(
      filename,
      p,
      width = width / 120,
      height = height / 120,
      dpi = 120
    )
    
    message("  âœ“ Plot saved")
    message("=============================\n")
    
    return(filename)
  }
  
  
  
  
  #--------------------- OVERLAY RADAR CHART BY BERUFSGRUPPE----------------------
  
  
  # Function to get all responses by Berufsgruppe for a topic
  get_berufsgruppe_radar_data <- function(project_id,
                                          questions,
                                          binary_qnums = integer()) {
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con))
    
    # Filter out binary questions using GLOBAL number
    non_binary_questions <- if (length(binary_qnums) > 0) {
      Filter(function(q)
        ! (q$number %in% binary_qnums), questions)
    } else {
      questions
    }
    
    if (length(non_binary_questions) == 0) {
      return(NULL)
    }
    
    # Get question IDs
    question_ids <- sapply(non_binary_questions, function(q)
      q$id)
    axis_names <- sapply(non_binary_questions, function(q)
      as.character(q$number))
    
    # âœ… FIXED: Use assessment_type instead of tag
    query <- "
    SELECT
      r.question_id,
      r.response_value,
      d.answers::json->>'Berufsgruppe' as berufsgruppe
    FROM responses r
    JOIN users u ON r.user_id::integer = u.id
    LEFT JOIN questionnaire_drafts d ON d.user_id::integer = u.id
      AND d.project_id::integer = r.project_id::integer
      AND d.questionnaire_id = 'peer_review'
    WHERE r.project_id::integer = $1
      AND r.assessment_type = 'selbstbewertung'
      AND u.role IN ('laborleitung', 'colleague')
      AND r.response_value ~ '^[0-9]+$'
  "
    
    df <- DBI::dbGetQuery(con, query, params = list(as.integer(project_id)))
    
    if (nrow(df) == 0)
      return(NULL)
    
    # Filter to valid Berufsgruppen and current questions
    valid_groups <- c("MTL", "Wissenschaftler(-in)", "Ã„rzte", "IT")
    df <- df[df$berufsgruppe %in% valid_groups &
               df$question_id %in% question_ids, ]
    
    if (nrow(df) == 0)
      return(NULL)
    
    # Convert to numeric
    df$response_value <- as.numeric(df$response_value)
    
    # Calculate mean per question per Berufsgruppe
    result <- df %>%
      group_by(berufsgruppe, question_id) %>%
      summarise(mean_score = mean(response_value, na.rm = TRUE),
                .groups = "drop")
    
    # Pivot wider
    wide_data <- result %>%
      tidyr::pivot_wider(names_from = question_id, values_from = mean_score)
    
    # Ensure all questions are present (fill with 0 if missing)
    for (qid in question_ids) {
      if (!(qid %in% colnames(wide_data))) {
        wide_data[[qid]] <- 0
      }
    }
    
    # Reorder columns to match question order and rename to global numbers
    wide_data <- wide_data[, c("berufsgruppe", question_ids)]
    colnames(wide_data) <- c("berufsgruppe", axis_names)
    
    return(as.data.frame(wide_data))
  }
  
  
  
  # Function to get Berufsgruppe statistics
  get_berufsgruppe_stats <- function(project_id) {
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con))
    
    # âœ… FIXED: Only count laborleitung and colleagues
    query <- "
    SELECT
      d.answers::json->>'Berufsgruppe' as berufsgruppe,
      COUNT(DISTINCT r.user_id) as anzahl_teilnehmer,
      COUNT(DISTINCT r.question_id) as anzahl_antworten
    FROM responses r
    JOIN users u ON r.user_id = u.id
    LEFT JOIN questionnaire_drafts d ON d.user_id::integer = u.id
      AND d.project_id::integer = r.project_id::integer
      AND d.questionnaire_id = 'peer_review'
    WHERE r.project_id::integer = $1
      AND r.assessment_type = 'selbstbewertung'
      AND u.role IN ('laborleitung', 'colleague')
    GROUP BY d.answers::json->>'Berufsgruppe'
    ORDER BY anzahl_teilnehmer DESC
  "
    
    result <- DBI::dbGetQuery(con, query, params = list(as.integer(project_id)))
    
    return(result)
  }
  
  #------------------------ Create overlaid radar chart for multiple Berufsgruppen
  make_fmsb_overlay_radar <- function(project_id,
                                      questions,
                                      title,
                                      binary_qnums = integer(),
                                      filename = "overlay_radar.png",
                                      width = 800,
                                      height = 600) {
    # Get weighted data by Berufsgruppe
    data <- get_berufsgruppe_radar_data_weighted(project_id, questions, binary_qnums)
    
    # DEBUG: Show what data we're plotting
    cat("\n=== RADAR PLOT DATA DEBUG ===\n")
    cat("Title:", title, "\n")
    print("Data for radar plot:")
    print(data)
    cat("===\n\n")
    
    if (is.null(data) || nrow(data) == 0) {
      # Create empty plot
      png(filename,
          width = width,
          height = height,
          res = 120)
      plot.new()
      text(0.5,
           0.5,
           "Keine Daten verfÃ¼gbar",
           cex = 1.5,
           col = "#666666")
      dev.off()
      return(filename)
    }
    
    # Separate Berufsgruppe column
    berufsgruppen <- data$berufsgruppe
    numeric_data <- data[, -1, drop = FALSE]
    
    # âœ… FIX: Extract question numbers (remove prefix like "F", "M", etc.)
    question_labels <- sapply(questions, function(q)
      as.character(q$number))
    colnames(numeric_data) <- question_labels
    
    # Create max/min rows
    num_questions <- ncol(numeric_data)
    max_row <- rep(5, num_questions)
    min_row <- rep(0, num_questions)
    
    # Combine: max, min, then all Berufsgruppen
    radar_df <- rbind(max_row, min_row, numeric_data)
    colnames(radar_df) <- question_labels  # âœ… Use just numbers
    rownames(radar_df) <- c("Max", "Min", berufsgruppen)
    
    # Color map
    # color_map <- c(
    #   "MTL"                   = "#0072B2",  # Blue
    #   "Wissenschaftler(-in)"  = "#D55E00",  # Vermillion/Orange
    #   "Ã„rzte"                 = "#009E73",  # Bluish Green
    #   "IT"                    = "#CC79A7"   # Reddish Purple
    # )
    #
    color_map <- c(
      "MTL"                  = "#1F77B4",
      # Strong blue
      "Wissenschaftler(-in)" = "#FF7F0E",
      # Orange
      "Ã„rzte"                = "#2CA02C",
      # Green
      "IT"                   = "#9467BD"   # Purple
    )
    
    # color_map <- c(
    #   "MTL"                  = "#2E86AB",
    #   "Wissenschaftler(-in)" = "#F18F01",
    #   "Ã„rzte"                = "#00A676",
    #   "IT"                   = "#B8336A"
    # )
    
    colors <- color_map[berufsgruppen]
    fill_colors <- scales::alpha(colors, 0.18)
    
    # Open PNG device
    png(filename,
        width = width,
        height = height,
        res = 120)
    
    # âœ… FIX: Increase bottom margin for legend
    op <- par(mar = c(4, 1, 3, 1))  # Increased bottom margin from 1 to 4
    
    tryCatch({
      radarchart(
        radar_df,
        axistype = 1,
        
        # Polygon styling
        pcol = colors,
        pfcol = fill_colors,
        plwd = 3,
        plty = 1,
        
        # Grid styling
        cglcol = "#CCCCCC",
        cglty = 1,
        cglwd = 1.2,
        
        # Axis styling
        axislabcol = "#666666",
        
        # âœ… Variable labels (now just numbers: 1, 2, 3...)
        vlcex = 1.2,
        vlabels = colnames(radar_df),
        
        # Axis labels
        caxislabels = c("0", "1", "2", "3", "4", "5"),
        calcex = 1.0,
        
        # No default title
        title = ""
      )
      
      # Add custom title
      title(
        main = paste0(title, " (Gewichtet)"),
        cex.main = 0.9,
        font.main = 2,
        col.main = "#333333"
      )
      
      # âœ… FIX: Legend at bottom with proper positioning
      legend(
        x = "bottom",
        # Position at bottom
        legend = berufsgruppen,
        col = colors,
        lty = 1,
        lwd = 4,
        bty = "n",
        # No box
        cex = 1.1,
        horiz = TRUE,
        # Horizontal layout
        title = "Berufsgruppe",
        title.col = "#333333",
        text.col = "#333333",
        xpd = TRUE,
        # Allow drawing outside plot area
        inset = c(0, -0.15)        # Move down slightly
      )
      
    }, error = function(e) {
      plot.new()
      text(
        0.5,
        0.5,
        paste("Fehler:", e$message),
        cex = 1.0,
        col = "#D32F2F"
      )
    })
    
    par(op)
    dev.off()
    
    return(filename)
  }
  
  #------------------- Get Weighted Radar Data by Berufsgruppe--------------------
  
  get_berufsgruppe_radar_data_weighted <- function(project_id,
                                                   questions,
                                                   binary_qnums = integer()) {
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con), add = TRUE)
    
    qids <- sapply(questions, function(q)
      q$id)
    qids_quoted <- paste0("'", qids, "'", collapse = ", ")
    
    # âœ… FIXED: Define all possible berufsgruppen
    all_possible_bg <- c("Ã„rzte",
                         "IT",
                         "MTL",
                         "Wissenschaftler(-in)",
                         "Sonstiges")
    
    # âœ… STEP 1: Get berufsgruppen that actually exist in this project
    all_bg_query <- paste0(
      "
    SELECT DISTINCT COALESCE(qd.answers::json->>'Berufsgruppe', 'Sonstiges') as berufsgruppe
    FROM users u
    LEFT JOIN questionnaire_drafts qd
      ON u.id::text = qd.user_id::text
      AND qd.project_id::text = '",
      project_id,
      "'
      AND qd.questionnaire_id = 'peer_review'
    WHERE u.project_id::text = '",
      project_id,
      "'
    ORDER BY berufsgruppe
  "
    )
    
    berufsgruppen_in_project <- DBI::dbGetQuery(con, all_bg_query)$berufsgruppe
    
    # âœ… Use all possible berufsgruppen (so they all show in the table)
    all_berufsgruppen <- intersect(all_possible_bg, berufsgruppen_in_project)
    if (length(all_berufsgruppen) == 0) {
      all_berufsgruppen <- all_possible_bg
    }
    all_berufsgruppen <- sort(all_berufsgruppen)
    
    # âœ… STEP 2: Get weighted DATA (only for berufsgruppen WITH numeric responses)
    data_query <- paste0(
      "
    SELECT
      COALESCE(qd.answers::json->>'Berufsgruppe', 'Sonstiges') as berufsgruppe,
      r.question_id,
      SUM(
        CASE
          WHEN r.response_value ~ '^[0-9]+$'
          THEN CAST(r.response_value AS NUMERIC) * COALESCE(CAST(qd.answers::json->>'group_size' AS INTEGER), 1)
          ELSE 0
        END
      ) / NULLIF(SUM(COALESCE(CAST(qd.answers::json->>'group_size' AS INTEGER), 1)), 0) as weighted_mean
    FROM responses r
    JOIN users u ON u.id = r.user_id
    LEFT JOIN questionnaire_drafts qd
      ON u.id::text = qd.user_id::text
      AND qd.project_id::text = r.project_id::text
      AND qd.questionnaire_id = 'peer_review'
    WHERE r.project_id::text = '",
      project_id,
      "'
      AND r.assessment_type = 'selbstbewertung'
      AND r.question_id IN (",
      qids_quoted,
      ")
      AND r.response_value != ''
      AND r.response_value != 'N/A'
    GROUP BY COALESCE(qd.answers::json->>'Berufsgruppe', 'Sonstiges'), r.question_id
    ORDER BY berufsgruppe, r.question_id
  "
    )
    
    result <- DBI::dbGetQuery(con, data_query)
    
    # âœ… STEP 3: Create wide format with ALL 5 berufsgruppen
    all_question_ids <- sapply(questions, function(q)
      q$id)
    
    # Start with ALL 5 berufsgruppen in correct order
    berufsgruppen_ordered <- c("Ã„rzte",
                               "IT",
                               "MTL",
                               "Wissenschaftler(-in)",
                               "Sonstiges")
    wide_data <- data.frame(berufsgruppe = berufsgruppen_ordered, stringsAsFactors = FALSE)
    
    # Add columns for each question ID (initialized with NA)
    for (qid in all_question_ids) {
      wide_data[[qid]] <- NA_real_
    }
    
    # Fill in the data we have
    if (nrow(result) > 0) {
      for (i in 1:nrow(result)) {
        bg <- result[i, "berufsgruppe"]
        qid <- result[i, "question_id"]
        val <- result[i, "weighted_mean"]
        
        bg_idx <- which(wide_data$berufsgruppe == bg)
        if (length(bg_idx) > 0) {
          wide_data[bg_idx, qid] <- val
        }
      }
    }
    
    # ðŸ” DEBUG
    cat("\n=== get_berufsgruppe_radar_data_weighted DEBUG ===\n")
    cat(
      "All berufsgruppen in project:",
      paste(berufsgruppen_in_project, collapse = ", "),
      "\n"
    )
    cat(
      "Returning all 5 berufsgruppen:",
      paste(wide_data$berufsgruppe, collapse = ", "),
      "\n"
    )
    cat("Rows in wide_data:", nrow(wide_data), "\n")
    print("Final wide format (includes all 5 berufsgruppen):")
    print(wide_data)
    cat("===\n\n")
    
    return(wide_data)
  }
  #------------ GGPLOT2 OVERLAY RADAR PLOT (Multiple Berufsgruppen)---------------
  
  
  #----------normalise function-----------
  normalize_berufsgruppe <- function(x) {
    x <- as.character(x)
    x <- trimws(x)
    
    dplyr::case_when(
      is.na(x) | x == "" ~ "Sonstiges",
      x %in% c("MTL") ~ "MTL",
      x %in% c(
        "Wissenschaftler(-in)",
        "Wissenschaftler",
        "Wissenschaftler/in"
      ) ~ "Wissenschaftler(-in)",
      x %in% c("Ã„rzte", "Aerzte", "Arzt", "Ã„rztin", "Arzt/Ã„rztin") ~ "Ã„rzte",
      x %in% c("IT") ~ "IT",
      x %in% c("Sonstiges", "Sonstige", "Other", "Andere") ~ "Sonstiges",
      TRUE ~ "Sonstiges"
    )
  }
  
  
  
  create_ggplot_overlay_radar <- function(project_id,
                                          questions_list,
                                          title,
                                          binary_qnums = integer()) {
    library(ggplot2)
    
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con))
    
    # Filter binary questions
    questions_filtered <- if (length(binary_qnums) > 0) {
      Filter(function(q)
        ! (q$number %in% binary_qnums),
        questions_list)
    } else {
      questions_list
    }
    
    question_ids <- sapply(questions_filtered, function(q)
      q$id)
    
    # Query responses with Berufsgruppe
    responses <- DBI::dbGetQuery(
      con,
      sprintf(
        "
    SELECT
      r.question_id,
      r.response_value::numeric as rv,
      COALESCE(CAST(qd.answers::json->>'Berufsgruppe' AS TEXT), 'Nicht angegeben') as berufsgruppe,
      COALESCE(CAST(qd.answers::json->>'group_size' AS INTEGER), 1) as group_size
    FROM responses r
    JOIN users u ON u.id = r.user_id
    LEFT JOIN questionnaire_drafts qd
      ON u.id::text = qd.user_id::text
      AND qd.project_id::text = r.project_id::text
      AND qd.questionnaire_id = 'peer_review'
    WHERE r.project_id = $1
      AND r.assessment_type = 'selbstbewertung'
      AND r.question_id IN (%s)
      AND r.response_value IS NOT NULL
      AND r.response_value != ''
      AND r.response_value != 'N/A'
      AND r.response_value NOT IN ('Ja', 'Nein')
  ",
        paste0("'", question_ids, "'", collapse = ", ")
      ),
      params = list(as.character(project_id))
    )
    
    if (nrow(responses) == 0) {
      plot.new()
      text(0.5, 0.5, "Keine Daten vorhanden", cex = 1.5)
      return()
    }
    
    # Expand by group_size
    expanded_list <- lapply(1:nrow(responses), function(i) {
      row <- responses[i, ]
      gs <- if (is.na(row$group_size) ||
                row$group_size < 1)
        1
      else
        as.integer(row$group_size)
      
      data.frame(
        question_id = rep(row$question_id, gs),
        rv = rep(row$rv, gs),
        berufsgruppe = rep(row$berufsgruppe, gs),
        stringsAsFactors = FALSE
      )
    })
    
    expanded <- do.call(rbind, expanded_list)
    
    expanded$berufsgruppe <- normalize_berufsgruppe(expanded$berufsgruppe)
    
    # Calculate means per question per berufsgruppe
    means <- aggregate(rv ~ question_id + berufsgruppe,
                       data = expanded,
                       FUN = mean)
    
    # Get unique berufsgruppen
    berufsgruppen <- unique(means$berufsgruppe)
    
    # Define colors for each berufsgruppe
    bg_colors <- c(
      "MTL"                  = "#1f77b4",
      "Wissenschaftler(-in)" = "#ff7f0e",
      "Ã„rzte"                = "#2ca02c",
      "IT"                   = "#d62728",
      "Sonstiges"            = "#17becf",
      "nicht anwendbar"      = "#9467bd",
      "Nicht angegeben"      = "#8c564b"
    )
    
    bg_levels <- names(bg_colors)   # always in sync with bg_colors
    means$berufsgruppe <- factor(means$berufsgruppe, levels = bg_levels)
    
    # Get question labels
    labels <- sapply(questions_filtered, function(q)
      as.character(q$number))
    n <- length(labels)
    angles <- seq(0, 2 * pi, length.out = n + 1)[1:n]
    
    to_cartesian <- function(r, angle) {
      list(x = r * sin(angle), y = r * cos(angle))
    }
    
    # Create polygon data for each berufsgruppe
    all_polygons <- lapply(berufsgruppen, function(bg) {
      # Get values for this berufsgruppe
      bg_data <- means[means$berufsgruppe == bg, ]
      
      values <- sapply(questions_filtered, function(q) {
        row <- bg_data[bg_data$question_id == q$id, ]
        if (nrow(row) > 0)
          row$rv
        else
          0
      })
      
      # Convert to cartesian
      polygon_coords <- lapply(1:n, function(i) {
        coords <- to_cartesian(values[i], angles[i])
        data.frame(x = coords$x, y = coords$y)
      })
      polygon_df <- do.call(rbind, polygon_coords)
      polygon_df <- rbind(polygon_df, polygon_df[1, ])  # Close polygon
      polygon_df$berufsgruppe <- bg
      
      return(polygon_df)
    })
    
    all_polygons_df <- do.call(rbind, all_polygons)
    
    # Grid circles
    grid_circles <- lapply(0:5, function(r) {
      angle_seq <- seq(0, 2 * pi, length.out = 100)
      coords <- lapply(angle_seq, function(a)
        to_cartesian(r, a))
      data.frame(
        x = sapply(coords, function(c)
          c$x),
        y = sapply(coords, function(c)
          c$y),
        r = r
      )
    })
    grid_df <- do.call(rbind, grid_circles)
    
    # Axis lines
    axis_lines <- lapply(1:n, function(i) {
      coords <- to_cartesian(5.5, angles[i])
      data.frame(
        x = 0,
        y = 0,
        xend = coords$x,
        yend = coords$y
      )
    })
    axis_df <- do.call(rbind, axis_lines)
    
    # Labels
    label_coords <- lapply(1:n, function(i) {
      coords <- to_cartesian(6.2, angles[i])
      data.frame(x = coords$x,
                 y = coords$y,
                 label = labels[i])
    })
    label_df <- do.call(rbind, label_coords)
    
    # Create plot
    p <- ggplot() +
      # Grid circles
      geom_path(
        data = grid_df,
        aes(x = x, y = y, group = r),
        color = "grey85",
        linewidth = 0.5
      ) +
      # Grid labels
      geom_text(
        data = data.frame(
          x = 0,
          y = 0:5,
          label = 0:5
        ),
        aes(x = x, y = y, label = label),
        color = "grey50",
        size = 3,
        hjust = 1.5
      ) +
      # Axis lines
      geom_segment(
        data = axis_df,
        aes(
          x = x,
          y = y,
          xend = xend,
          yend = yend
        ),
        color = "grey70",
        linewidth = 0.5
      ) +
      # Polygons for each berufsgruppe
      geom_polygon(
        data = all_polygons_df,
        aes(
          x = x,
          y = y,
          fill = berufsgruppe,
          color = berufsgruppe,
          group = berufsgruppe
        ),
        alpha = 0.2,
        linewidth = 1.2
      ) +
      # Points for each berufsgruppe
      geom_point(data = all_polygons_df[all_polygons_df$x != all_polygons_df$x[c(2:nrow(all_polygons_df), 1)], ],
                 aes(x = x, y = y, color = berufsgruppe),
                 size = 2.5) +
      # Axis labels
      geom_text(
        data = label_df,
        aes(x = x, y = y, label = label),
        size = 3.5,
        fontface = "bold"
      ) +
      # Colors
      scale_fill_manual(
        values = bg_colors,
        breaks = bg_levels,
        drop = FALSE,
        name = "Berufsgruppe"
      ) +
      scale_color_manual(
        values = bg_colors,
        breaks = bg_levels,
        drop = FALSE,
        name = "Berufsgruppe"
      ) +
      # Title
      ggtitle(title) +
      coord_fixed() +
      xlim(c(-7, 7)) +
      ylim(c(-7, 7)) +
      theme_void() +
      theme(
        plot.title = element_text(
          hjust = 0.5,
          size = 16,
          face = "bold",
          margin = margin(b = 10)
        ),
        legend.position = "bottom",
        legend.title = element_text(size = 12, face = "bold"),
        legend.text = element_text(size = 10)
      )
    
    return(p)
  }
  
