  #--------------Download Lab Info as PDF----------------------------
  
  output$download_labinfo_pdf <- downloadHandler(
    filename = function() {
      project_name <- current_project_name()
      if (is.null(project_name) || project_name == "") {
        project_name <- "Labor"
      }
      project_name <- gsub("[^A-Za-z0-9_-]", "_", project_name)
      paste0("Laborinformation_",
             project_name,
             "_",
             format(Sys.Date(), "%Y%m%d"),
             ".pdf")
    },
    
    content = function(file) {
      message("\n=== Lab Info PDF Generation ===")
      
      project_id <- current_project_id()
      
      if (is.null(project_id) || project_id == "") {
        showNotification("Kein Projekt ausgewÃ¤hlt.",
                         type = "error",
                         duration = 5)
        writeLines("ERROR: Kein Projekt ausgewÃ¤hlt.", file)
        return(NULL)
      }
      
      message("Project ID: ", project_id)
      
      template_file <- "labinfo_report.Rmd"
      
      if (!file.exists(template_file)) {
        showNotification("Template nicht gefunden.",
                         type = "error",
                         duration = 10)
        writeLines("Template nicht verfÃ¼gbar.", file)
        return(NULL)
      }
      
      showNotification(
        "PDF wird erstellt... Bitte warten.",
        type = "message",
        duration = NULL,
        id = "pdf_labinfo_progress"
      )
      
      tryCatch({
        message("Step 1: Save current data")
        save_result <- save_lab_info_data()
        
        if (!save_result) {
          message("Warning: Could not save data before generating PDF")
        }
        
        message("Step 2: Setup temp directory")
        template_path <- normalizePath(template_file, mustWork = TRUE)
        tmpdir <- tempdir()
        owd <- setwd(tmpdir)
        on.exit({
          setwd(owd)
          removeNotification("pdf_labinfo_progress")
        }, add = TRUE)
        
        message("  Working in: ", tmpdir)
        
        message("Step 3: Copy template")
        file.copy(template_path,
                  file.path(tmpdir, template_file),
                  overwrite = TRUE)
        
        message("Step 4: Get data from database")
        con <- get_db_con()
        on.exit(DBI::dbDisconnect(con), add = TRUE)
        
        # Get project title
        project_query <- DBI::dbGetQuery(con,
                                         "SELECT title FROM projects WHERE id = $1",
                                         params = list(as.integer(project_id)))
        
        project_title <- if (nrow(project_query) > 0 &&
                             !is.na(project_query$title[1])) {
          project_query$title[1]
        } else {
          "Labor"
        }
        
        message("  Project title: ", project_title)
        
        # Get lab info
        labinfo <- DBI::dbGetQuery(con,
                                   "SELECT * FROM lab_info WHERE project_id = $1",
                                   params = list(as.integer(project_id)))
        
        # Extract Hauptthema/Anlass (stored as JSON in lab_info.anmerkungen)
        anmerkungen <- character()
        
        if (nrow(labinfo) > 0 &&
            "anmerkungen" %in% names(labinfo)) {
          anmerkungen_raw <- labinfo$anmerkungen[1]
          
          anmerkungen <- tryCatch({
            if (is.null(anmerkungen_raw) ||
                is.na(anmerkungen_raw) ||
                !nzchar(anmerkungen_raw)) {
              character()
            } else {
              # anmerkungen_raw is JSON text (jsonb) -> parse to character vector
              out <- jsonlite::fromJSON(anmerkungen_raw)
              out <- as.character(out)
              out[nzchar(trimws(out))]
            }
          }, error = function(e) {
            message("WARNING: Could not parse lab_info.anmerkungen JSON: ",
                    e$message)
            character()
          })
        }
        
        message("  Anlass entries: ", length(anmerkungen))
        
        if (nrow(labinfo) == 0) {
          message("  WARNING: No lab info found, using empty data")
          labinfo <- data.frame(
            project_id = project_id,
            name = "",
            internetadresse = "",
            stringsAsFactors = FALSE
          )
        }
        
        message("  Lab info rows: ", nrow(labinfo))
        
        message("Step 5: Save CSV")
        write.csv(
          labinfo,
          file.path(tmpdir, "labinfo.csv"),
          row.names = FALSE,
          fileEncoding = "UTF-8"
        )
        
        message("Step 6: Render PDF")
        
        output_file <- rmarkdown::render(
          input         = file.path(tmpdir, template_file),
          output_format = "pdf_document",
          output_file   = "labinfo_report.pdf",
          output_dir    = tmpdir,
          params        = list(
            project_title = project_title,
            project_id    = project_id,
            anmerkungen   = anmerkungen
          ),
          envir         = new.env(parent = globalenv()),
          quiet         = FALSE
        )
        
        # Append Organigramm if uploaded
        message("Step 6.5: Appending Organigramm")
        message("  project_id passed to append: ", project_id)
        output_file <- append_organigramm_if_exists(output_file, project_id)
        message("  Final output_file: ", output_file)
        
        
        file.copy(output_file, file, overwrite = TRUE)
        
        message("  âœ“ PDF size: ", file.size(output_file), " bytes")
        
        removeNotification("pdf_labinfo_progress")
        showNotification("PDF erfolgreich erstellt!",
                         type = "message",
                         duration = 5)
        message("=== SUCCESS ===\n")
        
        
      }, error = function(e) {
        message("\n=== ERROR ===")
        message("Error message: ", e$message)
        message("Call stack:")
        print(sys.calls())
        
        removeNotification("pdf_labinfo_progress")
        showNotification(
          paste("Fehler beim Erstellen des PDFs:", e$message),
          type = "error",
          duration = 15
        )
        
        writeLines(paste("Fehler:", e$message), file)
      })
    },
    
    contentType = "application/pdf"
  )
  
  
  
