          con <- get_db_connection()
          on.exit(DBI::dbDisconnect(con), add = TRUE)
          
          result <- DBI::dbGetQuery(
            con,
            "SELECT title FROM projects WHERE id = $1",
            params = list(as.integer(project_id_val))  # âœ… Ensure integer
          )
          
          message("  Query result rows: ", nrow(result))
          
          if (nrow(result) > 0) {
            title <- result$title[1]
            message("  Found title: '", title, "'")
            
            if (!is.null(title) &&
                !is.na(title) && nzchar(title)) {
              return(title)
            }
          }
          
          message("  No title found, using default")
          return("Projekt")
          
        } else {
          message("  Invalid project_id: ", project_id_val)
          return("Projekt")
