        }
        
        # Get group size
        gruppen_groesse <- if (!is.null(input$alleine_oder_gruppe) &&
                               input$alleine_oder_gruppe == "gruppe" &&
                               !is.null(input$gruppen_groesse)) {
          as.character(input$gruppen_groesse)
        } else {
          "1"  # Default to 1 if filling alone
        }
        
        
        message("Step 7: Rendering PDF")
        message("  Berufsgruppe: ", berufsgruppe)
        message("  Alleine oder Gruppe: ", alleine_oder_gruppe)
        
        anzahl_personen <- if (alleine_oder_gruppe == "gruppe") gruppen_groesse else "1 (Einzelperson)"
        
        section_defs <- list(
          list(key = "fuehrung",       heading = "FÃ¼hrung",                               plot = "plot_fuehrung.png"),
          list(key = "mitarbeitende",  heading = "Mitarbeitende",                              plot = "plot_mit.png"),
          list(key = "patienten",      heading = "Patient und AngehÃ¶rige",                 plot = "plot_pat.png"),
          list(key = "einsender",      heading = "Einsender und Kooperationspartner",          plot = "plot_ein.png"),
          list(key = "qualitaet",      heading = "QualitÃ¤tsindikatoren und Validation",    plot = "plot_qual.png"),
          list(key = "qualitaet_mibi", heading = "QualitÃ¤tsindikatoren und Validation - Mikrobiologie", plot = "plot_qual_mibi.png")
        )
        sections <- lapply(section_defs, function(sd) {
          sec_data <- subset(user_responses, Section == sd$key)
          if (nrow(sec_data) > 0) sec_data <- sec_data[!duplicated(sec_data$Frage), , drop = FALSE]
          list(heading = sd$heading, plot_file = file.path(tmpdir, sd$plot), data = sec_data)
        })
        
        render_qa_report_pdf(
          file = file,
          title = "Peer Review Bericht",
          report_type = "Selbstbewertung",
          project_title = project_title,
          meta_lines = c(
            paste0("Berufsgruppe: ", berufsgruppe),
            paste0("AusfÃ¼llen: ", alleine_oder_gruppe, "   Anzahl Personen: ", anzahl_personen),
            paste0("Erstellt: ", format(Sys.Date(), "%d. %B %Y"))
          ),
          sections = sections,
          footer_text = PDFREPORT_FOOTER_TEXT,
          intro_lines = PDFREPORT_CONSENT_TEXT
        )
        
        message("=== Download completed successfully ===")
        
        showNotification("Bericht erfolgreich erstellt!",
                         type = "message",
                         duration = 5)
        
      }, error = function(e) {
        message("=== ERROR ===")
        message(paste("  Message:", e$message))
        message(paste("  Traceback:", paste(sys.calls(), collapse = "\n")))
        
        showNotification(
          paste("Fehler beim Erstellen des Berichts:", e$message),
          type = "error",
          duration = 15
        )
        
        writeLines(paste("Fehler:", e$message), file)
      })
    }
  )
  
  
