          message("ERROR in gather_mibi_answers: ", e$message)
          data.frame(
            Frage = character(),
            Antwort = character(),
            BegrÃ¼ndung = character(),
            stringsAsFactors = FALSE
          )
        })
        
        message("Gathered ", nrow(mibi_responses), " MiBi responses")
        
        # â”€â”€ Create MiBi radar plot â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
        plot_file <- file.path(tmpdir, "plot_mibi.png")
        if (file.exists(plot_file))
          file.remove(plot_file)
        
        tryCatch({
          make_ggplot_radar_png(
            radar_df = make_radar_df_from_inputs_fmsb(input, qual_mibi_questions),
            title    = "QualitÃ¤tsindikatoren Mikrobiologie",
            colour   = "#CA9161",
            filename = plot_file,
            width    = 800,
            height   = 800
          )
          if (file.exists(plot_file))
            message("âœ“ MiBi plot saved: ", file.size(plot_file), " bytes")
          else
            message("âœ— MiBi plot not created")
        }, error = function(e) {
