        # â”€â”€ User metadata â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
        berufsgruppe <- if (!is.null(input$Berufsgruppe) &&
                            nzchar(input$Berufsgruppe))
          as.character(input$Berufsgruppe)
        else
          "Nicht angegeben"
        
        alleine_oder_gruppe <- if (!is.null(input$alleine_oder_gruppe) &&
                                   nzchar(input$alleine_oder_gruppe))
