        gruppen_groesse <- if (!is.null(input$alleine_oder_gruppe) &&
                               input$alleine_oder_gruppe == "gruppe" &&
                               !is.null(input$gruppen_groesse))
          as.character(input$gruppen_groesse)
        else
          "1"
        
        # â”€â”€ Render PDF â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
        message("Rendering Mikrobiologie PDF...")
        
        anzahl_personen <- if (alleine_oder_gruppe == "gruppe") gruppen_groesse else "1 (Einzelperson)"
        mibi_data <- subset(mibi_responses, Section == "mikrobiologie")
        if (nrow(mibi_data) > 0) mibi_data <- mibi_data[!duplicated(mibi_data$Frage), , drop = FALSE]
        
        render_qa_report_pdf(
          file = file,
          title = "Peer Review Bericht",
          report_type = "Mikrobiologie-Selbstbewertung",
          project_title = project_title_val,
          meta_lines = c(
            paste0("Berufsgruppe: ", berufsgruppe),
            paste0("AusfÃ¼llen: ", alleine_oder_gruppe, "   Anzahl Personen: ", anzahl_personen),
            paste0("Erstellt: ", format(Sys.Date(), "%d. %B %Y"))
