  # â”€â”€ Helper: collect only MiBi answers â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  gather_mibi_answers <- function() {
    rows <- lapply(qual_mibi_questions, function(q) {
      qid        <- q$id
      score_id   <- paste0("Freitext", qid)
      text_id    <- paste0("Freitext_text", qid)
      
      antwort    <- input[[score_id]]
      begruendung <- input[[text_id]]
      
      antwort     <- if (is.null(antwort)     ||
                         antwort     == "")
        "N/A"
      else
        as.character(antwort)
      begruendung <- if (is.null(begruendung) ||
                         begruendung == "")
        ""
      else
        as.character(begruendung)
      
      data.frame(
        Section    = "mikrobiologie",
        Frage      = paste0(q$number, ". ", q$label),
        Antwort    = antwort,
        BegrÃ¼ndung = begruendung,
        stringsAsFactors = FALSE
      )
    })
    
    do.call(rbind, rows)
  }
  
  #---------------------------------download handler------------------------------
  #---------------------------------download handler------------------------------
  #--------------------Zusammenfassung Selbstbewertung + labinfo------------------
  
  output$downloadZusammenfassung <- downloadHandler(
    filename = function() {
      paste0("Zusammenfassung_", format(Sys.Date(), "%Y%m%d"), ".pdf")
    },
    
    content = function(file) {
      message("\n###############################################")
      message("### ZUSAMMENFASSUNG PDF GENERATION ###")
      message("###############################################\n")
      
      # Get project ID
      project_id <- isolate(current_project_id())
      
      # Validate
      if (is.null(project_id) ||
          project_id == "" || is.na(project_id)) {
        showNotification(
          "Bitte wÃ¤hlen Sie ein Projekt aus der Dropdown-Liste aus.",
          type = "error",
          duration = 10
        )
        writeLines("FEHLER: Kein Projekt ausgewÃ¤hlt.", file)
        return(NULL)
      }
      
      message("âœ“ Project ID: ", project_id)
      
      # Check for template
      template_file <- "zusammenfassung_report.Rmd"
      
      if (!file.exists(template_file)) {
        message("ERROR: Template not found: ", template_file)
        message("Working directory: ", getwd())
        message("Files: ", paste(list.files(pattern = "\\.Rmd$"), collapse = ", "))
        
        showNotification(
          paste0("Template nicht gefunden: ", template_file),
          type = "error",
          duration = 10
        )
        writeLines("FEHLER: Template nicht gefunden.", file)
        return(NULL)
      }
      
      message("âœ“ Template found")
      
      # Show progress
      showNotification(
        "PDF wird erstellt... Bitte warten.",
        type = "message",
        duration = NULL,
        id = "pdf_progress"
      )
      
      tryCatch({
        # Setup temp directory
        message("\nStep 1: Setup temp directory")
        tmpdir <- tempdir()
        original_wd <- getwd()
        setwd(tmpdir)
        on.exit({
          setwd(original_wd)
        }, add = TRUE)
        
        message("  Working dir: ", getwd())
        
        # Copy template
        message("\nStep 2: Copy template")
        template_path <- file.path(original_wd, template_file)
        file.copy(template_path,
                  file.path(tmpdir, template_file),
                  overwrite = TRUE)
        message("  âœ“ Template copied")
        
        # Database connection
        message("\nStep 3: Database connection")
        con <- get_db_con()
        on.exit(DBI::dbDisconnect(con), add = TRUE)
        
        # Get project info
        project_query <- DBI::dbGetQuery(con,
                                         "SELECT title FROM projects WHERE id = $1",
                                         params = list(project_id))
        project_title <- if (nrow(project_query) > 0)
          project_query$title[1]
        else
          "Projekt"
        message("  âœ“ Project: ", project_title)
        
        # ===== LAB INFO =====
        message("\nStep 4: Lab info")
        labinfo_raw <- DBI::dbGetQuery(con,
                                       "SELECT * FROM lab_info WHERE project_id = $1",
                                       params = list(project_id))
        
        # âœ… FIXED: the Rmd template (zusammenfassung_report.Rmd) reads fields
        # by their RAW database column names directly - "name",
        # "internetadresse", "trag", "anzahl_total", etc (see its print_val()
        # calls). The previous code here built a completely different, unused
        # schema ("lab_name", "street", "phone", "num_employees"...) that
        # never matched anything the Rmd actually looked for - so
        # field %in% names(labinfo) was always FALSE and every Lab Info
        # section silently printed nothing. Just write labinfo_raw directly,
        # replacing NA with "" so the Rmd's nchar()/nzchar() checks behave
        # the same way they do everywhere else.
        if (nrow(labinfo_raw) == 0) {
          message("  âš  No lab info found for this project")
          labinfo <- data.frame()
        } else {
          labinfo <- labinfo_raw
          labinfo[] <- lapply(labinfo, function(col) {
            if (is.character(col)) ifelse(is.na(col), "", col) else col
          })
        }
        
        # âœ… ADDED: parse the "Hauptthema / Anlass fÃ¼r das Peer Review"
        # (anmerkungen) JSON from lab_info, same as the labinfo_form_ui does.
        # This was previously never extracted or passed to the report at all.
        anmerkungen_items <- tryCatch({
          if (nrow(labinfo_raw) == 0) {
            list()
          } else {
            raw <- labinfo_raw$anmerkungen[1]
            if (is.null(raw) || is.na(raw) || !nzchar(trimws(as.character(raw)))) {
              list()
            } else {
              parsed <- jsonlite::fromJSON(as.character(raw), simplifyVector = FALSE)
              if (is.character(parsed) || is.atomic(parsed)) {
                parsed <- as.character(parsed)
                parsed <- parsed[nzchar(trimws(parsed))]
                lapply(parsed, function(s) list(beschreibung = s, anmerkung = ""))
              } else {
                parsed
              }
            }
          }
        }, error = function(e) {
          message("  âš  Could not parse anmerkungen: ", e$message)
          list()
        })
        message("  âœ“ anmerkungen parsed: ", length(anmerkungen_items), " item(s)")
        
        write.csv(labinfo,
                  "labinfo.csv",
                  row.names = FALSE,
                  fileEncoding = "UTF-8")
        message("  âœ“ labinfo.csv")
        
        # ===== RESPONSES =====
        message("\nStep 5: Responses")
        
        get_topic_responses <- function(prefix, questions, topic_name) {
          df <- DBI::dbGetQuery(
            con,
            sprintf(
              "SELECT u.username, r.question_id, r.response_value, r.text_value
     FROM responses r
     JOIN users u ON u.id = r.user_id
     WHERE r.assessment_type = 'selbstbewertung'
       AND r.project_id = $1 AND r.question_id ~ '^%s[0-9]'
     ORDER BY r.question_id, u.username",
              prefix
            ),
            params = list(project_id)
          )
          
          message("  ", topic_name, ": ", nrow(df), " rows")
          
          if (nrow(df) > 0) {
            df$question <- sapply(df$question_id, function(qid) {
              q <- Find(function(x)
                x$id == qid, questions)
              if (!is.null(q)) {
                paste0(q$number, ". ", q$label)   # prepend question number, e.g. "1. Welche Strategie..."
              } else {
                qid
              }
            })
            df <- df[, c("question_id",
                         "username",
                         "question",
                         "response_value",
                         "text_value")]  # âœ… Keep question_id
            colnames(df) <- c("question_id",
                              "Nutzer",
                              "Frage",
                              "Bewertung",
                              "BegrÃ¼ndung")
          } else {
            df <- data.frame(
              question_id = character(0),
              Nutzer = character(0),
              Frage = character(0),
              Bewertung = character(0),
              BegrÃ¼ndung = character(0),
              stringsAsFactors = FALSE
            )
          }
          df
        }
        
        fuehrung_responses_result <- get_topic_responses("F", fuehrung_questions, "FÃ¼hrung")
        write.csv(fuehrung_responses_result, "fuehrung_responses.csv", row.names = FALSE, fileEncoding = "UTF-8")
        
        mitarbeitende_responses_result <- get_topic_responses("M", mit_questions, "Mitarbeitende")
        write.csv(mitarbeitende_responses_result, "mitarbeitende_responses.csv", row.names = FALSE, fileEncoding = "UTF-8")
        
        pat_responses_result <- get_topic_responses("P", pat_questions, "Patienten")
        write.csv(pat_responses_result, "pat_responses.csv", row.names = FALSE, fileEncoding = "UTF-8")
        
        ein_responses_result <- get_topic_responses("E", ein_questions, "Einsender")
        write.csv(ein_responses_result, "ein_responses.csv", row.names = FALSE, fileEncoding = "UTF-8")
        
        qual_responses_result <- get_topic_responses("Q", qual_questions, "QualitÃ¤t")
        write.csv(qual_responses_result, "qual_responses.csv", row.names = FALSE, fileEncoding = "UTF-8")
        
        qual_mibi_responses_result <- get_topic_responses("QM", qual_mibi_questions, "QualitÃ¤t Mikrobiologie")
        write.csv(qual_mibi_responses_result, "qual_mibi_responses.csv", row.names = FALSE, fileEncoding = "UTF-8")
        
        message("  âœ“ All response CSVs")
        
        # ===== ENHANCED STATISTICS (with group_size weighting) =====
        message("\nStep 6: Enhanced Statistics with Berufsgruppe Breakdown")
        
        get_enhanced_stats <- function(topic_prefix, questions) {
          # Get responses with group_size and berufsgruppe
          stats_query <- "
        SELECT
          r.question_id,
          r.response_value::numeric as rv,
          COALESCE(CAST(qd.answers::json->>'Berufsgruppe' AS TEXT), 'Nicht angegeben') as berufsgruppe,
          COALESCE(CAST(qd.answers::json->>'group_size' AS INTEGER), 1) as group_size
        FROM responses r
        JOIN users u ON u.id = r.user_id
        LEFT JOIN questionnaire_drafts qd
          ON u.id::text = qd.user_id::text
          AND qd.project_id::text = r.project_id::text
          AND qd.questionnaire_id = 'peer_review'
        WHERE r.project_id = $1
          AND r.assessment_type = 'selbstbewertung'
          AND r.question_id ~ $2
          AND r.response_value IS NOT NULL
          AND r.response_value != ''
          AND r.response_value != 'N/A'
          AND r.response_value NOT IN ('Ja', 'Nein')
      "
          
          # âœ… FIXED: was LIKE 'Q%' which also matched 'QM62' etc (same bug
          # class fixed in get_topic_responses above). Regex requires the
          # prefix to be immediately followed by a digit.
          stats_data <- DBI::dbGetQuery(con, stats_query, params = list(project_id, paste0("^", topic_prefix, "[0-9]")))
          
          if (nrow(stats_data) == 0) {
            return(
              data.frame(
                Frage = character(0),
                n_gesamt = numeric(0),
                Mittelwert = numeric(0),
                Min = numeric(0),
                Max = numeric(0),
                Berufsgruppen = character(0)
              )
            )
          }
          
          # âœ… ADDED: id -> global number lookup, so "Frage" shows the
          # question's continuous number across ALL sections (e.g. 62-71 for
          # Mikrobiologie, continuing from QualitÃ¤t's own numbers) instead of
          # the raw prefixed id (e.g. "QM62").
          id_to_number <- setNames(
            sapply(questions, function(q) q$number),
            sapply(questions, function(q) q$id)
          )
          
          # Expand by group_size
          expanded_list <- lapply(1:nrow(stats_data), function(i) {
            row <- stats_data[i, ]
            gs <- if (is.na(row$group_size) ||
                      row$group_size < 1)
              1
            else
              as.integer(row$group_size)
            data.frame(
              question_id = rep(row$question_id, gs),
              rv = rep(row$rv, gs),
              berufsgruppe = rep(row$berufsgruppe, gs),
              stringsAsFactors = FALSE
            )
          })
          
          expanded <- do.call(rbind, expanded_list)
          
          # Get unique questions, sorted by local_number (not alphabetically
          # by raw id, which would sort "F10" before "F2")
          unique_questions <- unique(expanded$question_id)
          sort_key <- sapply(unique_questions, function(qid) {
            if (qid %in% names(id_to_number)) id_to_number[[qid]] else Inf
          })
          unique_questions <- unique_questions[order(sort_key)]
          
          # Calculate statistics per question
          result <- lapply(unique_questions, function(qid) {
            q_data <- expanded[expanded$question_id == qid, ]
            
            # Overall stats
            n_total <- nrow(q_data)
            mean_val <- mean(q_data$rv, na.rm = TRUE)
            min_val <- min(q_data$rv, na.rm = TRUE)
            max_val <- max(q_data$rv, na.rm = TRUE)
            
            # Berufsgruppe breakdown
            bg_stats <- aggregate(
              rv ~ berufsgruppe,
              data = q_data,
              FUN = function(x) {
                sprintf("Ã˜ %.1f (n=%d)", mean(x), length(x))
              }
            )
            
            bg_text <- paste(paste0(bg_stats$berufsgruppe, ": ", bg_stats$rv),
                             collapse = "; ")
            
            # âœ… ADDED: display just the local number instead of the raw id
            frage_display <- if (qid %in% names(id_to_number)) {
              as.character(id_to_number[[qid]])
            } else {
              qid
            }
            
            data.frame(
              Frage = frage_display,
              n_gesamt = n_total,
              Mittelwert = round(mean_val, 2),
              Min = min_val,
              Max = max_val,
              Berufsgruppen = bg_text,
              stringsAsFactors = FALSE
            )
          })
          
          do.call(rbind, result)
        }
        
        # Generate all stats
        message("  Generating enhanced statistics...")
        
        fuehrung_stats_result <- get_enhanced_stats("F", fuehrung_questions)
        write.csv(
          fuehrung_stats_result,
          "fuehrung_stats.csv",
          row.names = FALSE,
          fileEncoding = "UTF-8"
        )
        
        mitarbeitende_stats_result <- get_enhanced_stats("M", mit_questions)
        write.csv(
          mitarbeitende_stats_result,
          "mitarbeitende_stats.csv",
          row.names = FALSE,
          fileEncoding = "UTF-8"
        )
        
        pat_stats_result <- get_enhanced_stats("P", pat_questions)
        write.csv(
          pat_stats_result,
          "pat_stats.csv",
          row.names = FALSE,
          fileEncoding = "UTF-8"
        )
        
        ein_stats_result <- get_enhanced_stats("E", ein_questions)
        write.csv(
          ein_stats_result,
          "ein_stats.csv",
          row.names = FALSE,
          fileEncoding = "UTF-8"
        )
        
        qual_stats_result <- get_enhanced_stats("Q", qual_questions)
        write.csv(
          qual_stats_result,
          "qual_stats.csv",
          row.names = FALSE,
          fileEncoding = "UTF-8"
        )
        
        qual_mibi_stats_result <- get_enhanced_stats("QM", qual_mibi_questions)
        write.csv(
          qual_mibi_stats_result,
          "qual_mibi_stats.csv",
          row.names = FALSE,
          fileEncoding = "UTF-8"
        )
        message("  âœ“ qual_mibi_stats.csv")
        
        # Summary
        total_questions <- nrow(fuehrung_stats_result) + nrow(mitarbeitende_stats_result) +
          nrow(pat_stats_result) + nrow(ein_stats_result) + nrow(qual_stats_result)
        
        message("  âœ“ Enhanced stats created for ",
                total_questions,
                " questions across 5 topics")
        
        # ===== PLOTS =====
        message("\nStep 7: Plots (Single Average + Overlay by Berufsgruppe)")
        
        mit_binary_global_qnums <- c(10, 20, 24)
        
        # âœ… FUNCTION 1: Create single average plot (existing)
        create_single_plot <- function(name,
                                       questions,
                                       title,
                                       colour,
                                       binary_qnums = integer(0)) {
          plot_file <- paste0("plot_", name, ".png")
          
          tryCatch({
            message("  Creating single plot: ", title)
            
            questions_filtered <- if (length(binary_qnums) > 0) {
              Filter(function(q)
                ! (q$number %in% binary_qnums),
                questions)
            } else {
              questions
            }
            
            question_ids <- sapply(questions_filtered, function(q)
              q$id)
            
            if (length(question_ids) == 0) {
              message("    âš  No questions")
              png(plot_file, width = 800, height = 800)
              plot.new()
              text(0.5, 0.5, "Keine Fragen", cex = 1.5)
              dev.off()
              return()
            }
            
            # Get weighted responses
            responses <- DBI::dbGetQuery(
              con,
              sprintf(
                "SELECT
        r.question_id,
        r.response_value::numeric as rv,
        COALESCE(CAST(qd.answers::json->>'group_size' AS INTEGER), 1) as group_size
      FROM responses r
      JOIN users u ON u.id = r.user_id
      LEFT JOIN questionnaire_drafts qd
        ON u.id::text = qd.user_id::text
        AND qd.project_id::text = r.project_id::text
        AND qd.questionnaire_id = 'peer_review'
      WHERE r.project_id = $1
        AND r.assessment_type = 'selbstbewertung'
        AND r.question_id IN (%s)
        AND r.response_value IS NOT NULL
        AND r.response_value != ''
        AND r.response_value != 'N/A'
        AND r.response_value NOT IN ('Ja', 'Nein')"
                ,
                paste0("'", question_ids, "'", collapse = ", ")
              ),
              params = list(project_id)
            )
            
            if (nrow(responses) == 0) {
              message("    âš  No data")
              png(plot_file, width = 800, height = 800)
              plot.new()
              text(0.5, 0.5, "Keine Daten", cex = 1.5)
              dev.off()
              return()
            }
            
            # Expand by group_size
            expanded_list <- lapply(1:nrow(responses), function(i) {
              row <- responses[i, ]
              gs <- if (is.na(row$group_size) ||
                        row$group_size < 1)
                1
              else
                as.integer(row$group_size)
              data.frame(
                question_id = rep(row$question_id, gs),
                rv = rep(row$rv, gs)
              )
            })
            expanded <- do.call(rbind, expanded_list)
            
            # Calculate means
            means <- aggregate(rv ~ question_id, data = expanded, FUN = mean)
            
            values <- sapply(questions_filtered, function(q) {
              row <- means[means$question_id == q$id, ]
              if (nrow(row) > 0)
                row$rv
              else
                0
            })
            
            labels <- sapply(questions_filtered, function(q)
              as.character(q$number))
            
            # Build radar data frame
            radar_df <- data.frame(matrix(nrow = 3, ncol = length(values)))
            radar_df[1, ] <- 5
            radar_df[2, ] <- 0
            radar_df[3, ] <- values
            colnames(radar_df) <- labels
            
            # Use ggplot2 radar
            make_ggplot_radar_png(radar_df, title, colour, plot_file, 800, 800)
            message("  âœ“ ", title)
            
          }, error = function(e) {
            message("  âœ— ", title, " ERROR: ", e$message)
            png(plot_file, width = 800, height = 800)
            plot.new()
            text(0.5, 0.5, "Fehler", cex = 1.5)
            dev.off()
          })
        }
        
        # âœ… FUNCTION 2: Create overlay plot (by Berufsgruppe)
        create_overlay_plot <- function(name,
                                        questions,
                                        title,
                                        binary_qnums = integer(0)) {
          plot_file <- paste0("plot_overlay_", name, ".png")
          
          tryCatch({
            message("  Creating overlay plot: ", title)
            
            questions_filtered <- if (length(binary_qnums) > 0) {
              Filter(function(q)
                ! (q$number %in% binary_qnums),
                questions)
            } else {
              questions
            }
            
            question_ids <- sapply(questions_filtered, function(q)
              q$id)
            
            if (length(question_ids) == 0) {
              message("    âš  No questions")
              png(plot_file, width = 800, height = 800)
              plot.new()
              text(0.5, 0.5, "Keine Fragen", cex = 1.5)
              dev.off()
              return()
            }
            
            # Get responses with Berufsgruppe
            responses <- DBI::dbGetQuery(
              con,
              sprintf(
                "SELECT
        r.question_id,
        r.response_value::numeric as rv,
        COALESCE(CAST(qd.answers::json->>'Berufsgruppe' AS TEXT), 'Nicht angegeben') as berufsgruppe,
        COALESCE(CAST(qd.answers::json->>'group_size' AS INTEGER), 1) as group_size
      FROM responses r
      JOIN users u ON u.id = r.user_id
      LEFT JOIN questionnaire_drafts qd
        ON u.id::text = qd.user_id::text
        AND qd.project_id::text = r.project_id::text
        AND qd.questionnaire_id = 'peer_review'
      WHERE r.project_id = $1
        AND r.assessment_type = 'selbstbewertung'
        AND r.question_id IN (%s)
        AND r.response_value IS NOT NULL
        AND r.response_value != ''
        AND r.response_value != 'N/A'
        AND r.response_value NOT IN ('Ja', 'Nein')

              ",
                paste0("'", question_ids, "'", collapse = ", ")
              ),
              params = list(project_id)
            )
            
            if (nrow(responses) == 0) {
              message("No data")
              png(plot_file, width = 800, height = 800)
              plot.new()
              text(0.5, 0.5, "Keine Daten", cex = 1.5)
              dev.off()
              return()
            }
            
            # Expand by group_size
            expanded_list <- lapply(1:nrow(responses), function(i) {
              row <- responses[i, ]
              gs <- if (is.na(row$group_size) ||
                        row$group_size < 1)
                1
              else
                as.integer(row$group_size)
              data.frame(
                question_id = rep(row$question_id, gs),
                rv = rep(row$rv, gs),
                berufsgruppe = rep(row$berufsgruppe, gs),
                stringsAsFactors = FALSE
              )
            })
            expanded <- do.call(rbind, expanded_list)
            
            # Calculate means per question per berufsgruppe
            means <- aggregate(rv ~ question_id + berufsgruppe,
                               data = expanded,
                               FUN = mean)
            
            # Get unique berufsgruppen
            berufsgruppen <- unique(means$berufsgruppe)
            
            if (length(berufsgruppen) == 0) {
              message("    âš  No berufsgruppen")
              png(plot_file, width = 800, height = 800)
              plot.new()
              text(0.5, 0.5, "Keine Berufsgruppen", cex = 1.5)
              dev.off()
              return()
            }
            
            # Colors
            bg_colors <- c(
              "MTL" = "#1f77b4",
              "Wissenschaftler(-in)" = "#ff7f0e",
              "Ã„rzte" = "#2ca02c",
              "IT" = "#d62728",
              "Sonstiges" = "#17becf",
              "nicht anwendbar" = "#9467bd",
              "Nicht angegeben" = "#8c564b"
            )
            bg_levels <- names(bg_colors)
            
            # Create ggplot2 overlay
            library(ggplot2)
            
            labels <- sapply(questions_filtered, function(q)
              as.character(q$number))
            n <- length(labels)
            angles <- seq(0, 2 * pi, length.out = n + 1)[1:n]
            
            to_cartesian <- function(r, angle) {
              list(x = r * sin(angle),
                   y = r * cos(angle))
            }
            
            # Create polygons for each berufsgruppe
            all_polygons <- lapply(berufsgruppen, function(bg) {
              bg_data <- means[means$berufsgruppe == bg, ]
              
              values <- sapply(questions_filtered, function(q) {
                row <- bg_data[bg_data$question_id == q$id, ]
                if (nrow(row) > 0)
                  row$rv
                else
                  0
              })
              
              polygon_coords <- lapply(1:n, function(i) {
                coords <- to_cartesian(values[i], angles[i])
                data.frame(x = coords$x, y = coords$y)
              })
              polygon_df <- do.call(rbind, polygon_coords)
              polygon_df <- rbind(polygon_df, polygon_df[1, ])
              polygon_df$berufsgruppe <- bg
              
              return(polygon_df)
            })
            
            all_polygons_df <- do.call(rbind, all_polygons)
            
            # Grid circles
            grid_circles <- lapply(0:5, function(r) {
              angle_seq <- seq(0, 2 * pi, length.out = 100)
              coords <- lapply(angle_seq, function(a)
                to_cartesian(r, a))
              data.frame(
                x = sapply(coords, function(c)
                  c$x),
                y = sapply(coords, function(c)
                  c$y),
                r = r
              )
            })
            grid_df <- do.call(rbind, grid_circles)
            
            # Axis lines
            axis_lines <- lapply(1:n, function(i) {
              coords <- to_cartesian(5.5, angles[i])
              data.frame(
                x = 0,
                y = 0,
                xend = coords$x,
                yend = coords$y
              )
            })
            axis_df <- do.call(rbind, axis_lines)
            
            # Labels
            label_coords <- lapply(1:n, function(i) {
              coords <- to_cartesian(6.2, angles[i])
              data.frame(x = coords$x,
                         y = coords$y,
                         label = labels[i])
            })
            label_df <- do.call(rbind, label_coords)
            
            # Create plot
            p <- ggplot() +
              geom_path(
                data = grid_df,
                aes(
                  x = x,
                  y = y,
                  group = r
                ),
                color = "grey85",
                linewidth = 0.5
              ) +
              geom_text(
                data = data.frame(
                  x = 0,
                  y = 0:5,
                  label = 0:5
                ),
                aes(
                  x = x,
                  y = y,
                  label = label
                ),
                color = "grey50",
                size = 3,
                hjust = 1.5
              ) +
              geom_segment(
                data = axis_df,
                aes(
                  x = x,
                  y = y,
                  xend = xend,
                  yend = yend
                ),
                color = "grey70",
                linewidth = 0.5
              ) +
              geom_polygon(
                data = all_polygons_df,
                aes(
                  x = x,
                  y = y,
                  fill = berufsgruppe,
                  color = berufsgruppe,
                  group = berufsgruppe
                ),
                alpha = 0.2,
                linewidth = 1.2
              ) +
              geom_point(data = all_polygons_df[!duplicated(
                paste(
                  all_polygons_df$berufsgruppe,
                  all_polygons_df$x,
                  all_polygons_df$y
                )
              ), ],
              aes(
                x = x,
                y = y,
                color = berufsgruppe
              ),
              size = 2.5) +
              geom_text(
                data = label_df,
                aes(
                  x = x,
                  y = y,
                  label = label
                ),
                size = 3.5,
                fontface = "bold"
              ) +
              scale_fill_manual(
                values = bg_colors,
                breaks = bg_levels,
                drop = FALSE,
                name = "Berufsgruppe"
              ) +
              scale_color_manual(
                values = bg_colors,
                breaks = bg_levels,
                drop = FALSE,
                name = "Berufsgruppe"
              ) +
              ggtitle(title) +
              coord_fixed() +
              xlim(c(-7, 7)) +
              ylim(c(-7, 7)) +
              theme_void() +
              theme(
                plot.title = element_text(
                  hjust = 0.5,
                  size = 16,
                  face = "bold",
                  margin = margin(b = 10)
                ),
                legend.position = "bottom",
                legend.title = element_text(size = 12, face = "bold"),
                legend.text = element_text(size = 10)
              )
            
            ggsave(
              plot_file,
              p,
              width = 800 / 120,
              height = 800 / 120,
              dpi = 120
            )
            message("  âœ“ ", title, " (Overlay)")
            
          }, error = function(e) {
            message("  âœ— ", title, " (Overlay) ERROR: ", e$message)
            png(plot_file, width = 800, height = 800)
            plot.new()
            text(0.5, 0.5, "Fehler", cex = 1.5)
            dev.off()
          })
