  # âœ… ADD: Load report field from database
  load_report_field <- function(field_name) {
    project_id <- current_project_id()
    
    if (is.null(project_id) || project_id == "") {
      return("")
    }
    
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con), add = TRUE)
    
    tryCatch({
      # Check if report_data table exists
      table_exists <- DBI::dbExistsTable(con, "report_data")
      
      if (!table_exists) {
        message("  report_data table does not exist")
        return("")
      }
      
      # Get field value
      result <- DBI::dbGetQuery(
        con,
        "
      SELECT field_value
      FROM report_data
      WHERE project_id = $1
        AND field_name = $2
      LIMIT 1
    ",
        params = list(as.character(project_id), field_name)
      )
      
      if (nrow(result) > 0 && !is.na(result$field_value[1])) {
        return(as.character(result$field_value[1]))
      } else {
        return("")
      }
      
    }, error = function(e) {
      message("  Error loading field '", field_name, "': ", e$message)
      return("")
    })
  }
  
  #============================================================================
  # HELPER: Get Fremdbewertung for a specific user
  #============================================================================
  
  # â”€â”€ Shared mapping logic: raw question_id/response_value/text_value rows
  # -> the Section/Frage/Antwort/BegrÃ¼ndung structure the reports expect.
  # Used by BOTH functions below, so the Q/QM fix and Mikrobiologie
  # inclusion only need to live in one place. â”€â”€
  .map_fremd_raw_to_df <- function(fremd_raw) {
    if (nrow(fremd_raw) == 0) {
      return(
        data.frame(
          Section = character(0),
          question_id = character(0),
          Frage = character(0),
          Antwort = character(0),
          BegrÃ¼ndung = character(0),
          stringsAsFactors = FALSE
        )
      )
    }
    
    all_questions <- c(
      fuehrung_questions,
      mit_questions,
      pat_questions,
      ein_questions,
      qual_questions,
      qual_mibi_questions
    )
    
    q_lookup <- list()
    for (q in all_questions) {
      section <- if (startsWith(q$id, "QM")) {
        "qualitaet_mibi"
      } else {
        prefix <- substr(q$id, 1, 1)
        switch(
          prefix,
          "F" = "fuehrung",
          "M" = "mitarbeitende",
          "P" = "patienten",
          "E" = "einsender",
          "Q" = "qualitaet",
          "unknown"
        )
      }
      
      q_lookup[[q$id]] <- list(section = section, label = q$label, number = q$number)
    }
    
    result <- lapply(1:nrow(fremd_raw), function(i) {
      row <- fremd_raw[i, ]
      qid <- row$question_id
      
      q_info <- q_lookup[[qid]]
      
      data.frame(
        Section = if (!is.null(q_info))
          q_info$section
        else
          "unknown",
        question_id = qid,
        Frage = if (!is.null(q_info))
          paste0(q_info$number, ". ", q_info$label)
        else
          qid,
        Antwort = if (!is.na(row$response_value))
          as.character(row$response_value)
        else
          "",
        BegrÃ¼ndung = if (!is.na(row$text_value))
          as.character(row$text_value)
        else
          "",
        stringsAsFactors = FALSE
      )
    })
    
    do.call(rbind, result)
  }
  
  # â”€â”€ Submitted responses ONLY - no draft fallback. Used by the Gesamtbericht
  # (aggregates every reviewer), which should only ever reflect official,
  # finalized reviews - not depend on parsing every reviewer's in-progress
  # draft JSON, which is inherently less stable and could break the shared
  # report for everyone if even one reviewer's draft has an unexpected shape. â”€â”€
  get_fremdbewertung_for_user <- function(project_id, user_id) {
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con), add = TRUE)
    
    message("  get_fremdbewertung_for_user called")
    message("    project_id: ", project_id)
    message("    user_id: ", user_id)
    
    query <- "
    SELECT
      r.question_id,
      r.response_value,
      r.text_value
    FROM responses r
    WHERE r.project_id = $1
      AND r.user_id = $2
      AND r.assessment_type = 'fremdbewertung'
    ORDER BY r.question_id
  "
    
    fremd_raw <- DBI::dbGetQuery(con, query, params = list(as.character(project_id), as.integer(user_id)))
    
    message("    Found ", nrow(fremd_raw), " fremdbewertung responses")
    
    final_df <- .map_fremd_raw_to_df(fremd_raw)
    message("    Returning ", nrow(final_df), " rows")
    final_df
  }
  
  # â”€â”€ Always reads straight from the live draft in questionnaire_drafts -
  # the same JSON blob the autosave keeps up to date as the user types, and
  # which survives final submission untouched (submit only flips
  # draft$status, it never clears draft$answers). Used ONLY by personal/
  # colleague downloads ("download my own answers"), so what's shown always
  # matches what's currently filled in - never by the Gesamtbericht.
  #
  # Previously this only consulted the draft when zero rows existed yet in
  # the 'responses' table, so any old row left over in 'responses' (e.g.
  # from an earlier test submission) was shown verbatim and the current
  # draft was never even looked at - that's what caused already-typed
  # answers to be silently replaced by stale/test data in the PDF. â”€â”€
  get_fremdbewertung_for_user_including_draft <- function(project_id, user_id) {
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con), add = TRUE)
    
    message("  get_fremdbewertung_for_user_including_draft called")
    message("    project_id: ", project_id)
    message("    user_id: ", user_id)
    
    fremd_raw <- data.frame(
      question_id = character(0),
      response_value = character(0),
      text_value = character(0),
      stringsAsFactors = FALSE
    )
    
    draft_row <- DBI::dbGetQuery(
      con,
      "SELECT answers FROM questionnaire_drafts
       WHERE user_id = $1 AND project_id = $2 AND questionnaire_id = 'peer_fremdbewertung'
       ORDER BY last_saved DESC LIMIT 1",
      params = list(as.integer(user_id), as.character(project_id))
    )
    
    if (nrow(draft_row) == 0) {
      message("    No draft found")
    } else {
      answers <- tryCatch(
        jsonlite::fromJSON(draft_row$answers[1]),
        error = function(e) {
          message("    Error parsing draft JSON: ", e$message)
          list()
        }
      )
      
      qids <- unique(gsub("^Fremdbewertung(Num|Text)_", "", grep("^Fremdbewertung", names(answers), value = TRUE)))
      
      if (length(qids) > 0) {
        fremd_raw <- do.call(rbind, lapply(qids, function(qid) {
          num_val <- answers[[paste0("FremdbewertungNum_", qid)]]
          text_val <- answers[[paste0("FremdbewertungText_", qid)]]
          data.frame(
            question_id = qid,
            response_value = if (!is.null(num_val) && length(num_val) > 0 && num_val != "") as.character(num_val)[1] else NA,
            text_value = if (!is.null(text_val) && length(text_val) > 0) as.character(text_val)[1] else NA,
            stringsAsFactors = FALSE
          )
        }))
        # Drop questions that were never actually answered in the draft.
        fremd_raw <- fremd_raw[!is.na(fremd_raw$response_value), , drop = FALSE]
      }
      
      message("    Found ", nrow(fremd_raw), " answers in draft")
    }
    
    final_df <- .map_fremd_raw_to_df(fremd_raw)
    message("    Returning ", nrow(final_df), " rows")
    final_df
  }
  
  # Helper function
  get_fremdbewertung_section <- function(questions) {
    data.frame(
      Frage     = sapply(questions, function(q)
        q$label),
      Bewertung = sapply(questions, function(q) {
        val <- input[[paste0("FremdbewertungNum_", q$id)]]
        if (is.null(val) ||
            length(val) == 0)
          ""
        else
          as.character(val)
      }),
      Kommentar = sapply(questions, function(q) {
        val <- input[[paste0("FremdbewertungText_", q$id)]]
        if (is.null(val) ||
            length(val) == 0)
          ""
        else
          as.character(val)
      }),
      stringsAsFactors = FALSE
    )
  }
  
  #---------------------fremdbewertung download handler (leading peer)----------
  
  output$downloadFremdbewertung <- downloadHandler(
    filename = function()
      paste0("fremdbewertung_", format(Sys.Date(), "%Y%m%d"), ".pdf"),
    content  = function(file) {
      message("=== Fremdbewertung Download started ===")
      
      tryCatch({
        message("Step 1: Getting project ID and user ID")
        project_id <- current_project_id()
        user_id <- user_id()
        
        if (is.null(project_id) || is.null(user_id)) {
          showNotification("Kein Projekt oder Benutzer gefunden.", type = "error")
          return(NULL)
        }
        message("  Project ID: ", project_id)
        message("  User ID: ", user_id)
        
        project_title <- tryCatch({
          con <- get_db_con()
          on.exit(DBI::dbDisconnect(con), add = TRUE)
          res <- DBI::dbGetQuery(con, "SELECT title FROM projects WHERE id = $1", params = list(as.integer(project_id)))
          if (nrow(res) > 0 && nzchar(res$title[1])) res$title[1] else "Projekt"
        }, error = function(e) "Projekt")
        
        message("Step 2: Getting Fremdbewertung from database")
        
        # Get ONLY this user's Fremdbewertung, straight from their draft
        fremd_data <- get_fremdbewertung_for_user_including_draft(project_id, user_id)
        
        message("  Found ", nrow(fremd_data), " responses")
        
        if (nrow(fremd_data) == 0) {
          showNotification(
            "Sie haben noch keine Fremdbewertung abgegeben.",
            type = "warning",
            duration = 5
          )
          writeLines("Keine Fremdbewertung vorhanden.", file)
          return(NULL)
        }
        
        message("Step 3: Rendering PDF")
        
        section_defs <- list(
          list(key = "fuehrung",       heading = "FÃ¼hrung"),
          list(key = "mitarbeitende",  heading = "Mitarbeitende"),
          list(key = "patienten",      heading = "Patient und AngehÃ¶rige"),
          list(key = "einsender",      heading = "Einsender und Kooperationspartner"),
          list(key = "qualitaet",      heading = "QualitÃ¤tsindikatoren und Technische und Medizinische Validation"),
          list(key = "qualitaet_mibi", heading = "QualitÃ¤tsindikatoren - Mikrobiologie")
        )
        sections <- lapply(section_defs, function(sd) {
          list(heading = sd$heading, data = subset(fremd_data, Section == sd$key))
        })
        
        render_qa_report_pdf(
          file = file,
          title = "Peer Review Bericht",
          report_type = "Fremdbewertung",
          project_title = project_title,
          meta_lines = c(paste0("Erstellt: ", format(Sys.Date(), "%d. %B %Y"))),
          sections = sections,
          footer_text = PDFREPORT_FOOTER_TEXT,
          intro_lines = PDFREPORT_CONSENT_TEXT
        )
        
        message("=== Fremdbewertung Download completed successfully ===")
        
        showNotification(
          "Fremdbewertung Bericht erfolgreich erstellt!",
          type = "message",
          duration = 5
        )
        
      }, error = function(e) {
        message("=== ERROR ===")
        message(paste("  Message:", e$message))
        
        showNotification(
          paste("Fehler beim Erstellen des Berichts:", e$message),
          type = "error",
          duration = 15
        )
        
        writeLines(paste("Fehler:", e$message), file)
      })
    }
  )
  
  
  #------- FREMDBEWERTUNG SUBMISSION OBSERVERS (For Leading Peer & Co-Peer)-------
  
  
  #-------------- FREMDBEWERTUNG SUBMISSION SYSTEM ---------------
  
  submit_fremdbewertung_topic <- function(topic_prefix,
                                          questions_list,
                                          topic_name,
                                          status_output) {
    req(user_logged_in())
    req(user_role() %in% c("leading_peer", "co_peer"))
    
    current_user_id <- user_id()
    project_id <- current_project_id()
    submission_id <- uuid::UUIDgenerate()
    
    message("\n=== SUBMIT FREMDBEWERTUNG: ", topic_name, " ===")
    message("User: ", current_user_id, " (", user_role(), ")")
    message("Project: ", project_id)
    
    if (is.null(project_id) ||
        project_id == "" || is.na(project_id)) {
      showNotification("Fehler: Kein Projekt ausgewÃ¤hlt!", type = "error")
      return(invisible(FALSE))
    }
    
    tag_value <- get_submission_tag()
    
    # Collect responses for this topic
    responses_list <- list()
    
    for (q in questions_list) {
      qid <- q$id
      score_id <- paste0("FremdbewertungNum_", qid)
      text_id <- paste0("FremdbewertungText_", qid)
      
      score <- input[[score_id]]
      text <- input[[text_id]]
      
      if (!is.null(score) && score != "" && score != "N/A") {
        responses_list[[length(responses_list) + 1]] <- list(
          user_id = as.integer(current_user_id),
          # âœ… FIX: INTEGER
          question_id = qid,
          response_value = as.character(score),
          text_value = if (!is.null(text) &&
                           text != "")
            as.character(text)
          else
            NA_character_,
          tag = tag_value,
          assessment_type = "fremdbewertung",
          submission_id = submission_id,
          project_id = as.character(project_id),
          group_size = 1L
        )
      }
    }
    
    if (length(responses_list) == 0) {
      showNotification("Keine Antworten zum Speichern gefunden.", type = "warning")
      output[[status_output]] <- renderUI(div(style = "color:orange;margin-top:12px;", "âš  Keine Antworten gefunden."))
      return(invisible(FALSE))
    }
    
    message("Collected ",
            length(responses_list),
            " responses for ",
            topic_name)
    
    # Save to database
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con), add = TRUE)
    
    tryCatch({
      sql <- "
      INSERT INTO responses (
        user_id, project_id, question_id, response_value, text_value,
        tag, assessment_type, submission_id, group_size, created_at
      ) VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9, NOW())
    "
      
      inserted <- 0
      
      for (resp in responses_list) {
        DBI::dbExecute(
          con,
          sql,
          params = list(
            resp$user_id,
            # INTEGER
            resp$project_id,
            resp$question_id,
            resp$response_value,
            resp$text_value,
            resp$tag,
            resp$assessment_type,
            resp$submission_id,
            resp$group_size
          )
        )
        inserted <- inserted + 1
      }
      
      message("âœ“ Saved ", inserted, " responses for ", topic_name)
      message("âœ“ Submission ID: ", submission_id)
      message("=== SUCCESS ===\n")
      
      showNotification(
        paste0(
          topic_name,
          " Fremdbewertung erfolgreich abgesendet! (",
          inserted,
          " Antworten)"
        ),
        type = "message",
        duration = 5
      )
      
      output[[status_output]] <- renderUI(
        div(
          style = "color:green;margin-top:12px;font-weight:bold;",
          icon("check-circle"),
          " Erfolgreich abgesendet!"
        )
      )
      
      return(invisible(TRUE))
      
    }, error = function(e) {
      message("ERROR: ", e$message)
      showNotification(
        paste("Fehler beim Speichern:", e$message),
        type = "error",
        duration = 10
      )
      
      output[[status_output]] <- renderUI(div(style = "color:red;margin-top:12px;", "âœ— Fehler beim Speichern!"))
      
      return(invisible(FALSE))
    })
  }
  
  submit_all_fremdbewertung <- function() {
    req(user_logged_in())
    req(user_role() %in% c("leading_peer", "co_peer"))
    
    current_user_id <- user_id()
    project_id <- current_project_id()
    submission_id <- uuid::UUIDgenerate()
    questionnaire_id <- "peer_fremdbewertung"
    
    message("\n========== SUBMIT ALL FREMDBEWERTUNG ==========")
    message("User: ", current_user_id, " (", user_role(), ")")
    message("Project: ", project_id)
    message("Submission ID: ", submission_id)
    
    if (is.null(project_id) ||
        project_id == "" || is.na(project_id)) {
      showNotification("Fehler: Kein Projekt ausgewÃ¤hlt!",
                       type = "error",
                       duration = 5)
      return(invisible(FALSE))
    }
    
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con), add = TRUE)
    
    # Load draft
    draft <- DBI::dbGetQuery(
      con,
      "SELECT answers, status FROM questionnaire_drafts
     WHERE user_id::text = $1::text
     AND project_id::text = $2::text
     AND questionnaire_id = $3
     ORDER BY last_saved DESC LIMIT 1",
      params = list(
        as.character(current_user_id),
        as.character(project_id),
        questionnaire_id
      )
    )
    
    if (nrow(draft) == 0) {
      message("âŒ No draft found")
      showNotification("Kein Entwurf gefunden.",
                       type = "warning",
                       duration = 5)
      return(invisible(FALSE))
    }
    
    if (draft$status[1] == "submitted") {
      message("âŒ Already submitted")
      showNotification(
        "Diese Fremdbewertung wurde bereits abgeschickt!",
        type = "warning",
        duration = 5
      )
      return(invisible(FALSE))
    }
    
    # Parse draft
    saved_answers <- jsonlite::fromJSON(draft$answers[1])
    message("âœ“ Loaded draft with ", length(saved_answers), " fields")
    
    # Convert to responses
    responses_list <- list()
    
    # âœ… FIXED: qual_mibi_questions (QualitÃ¤tsindikatoren - Mikrobiologie)
    # was missing from this list. That tab's own "Weiter" button IS the
    # final "Fragebogen abschicken" button (see peer_next_button_qual_mibi),
    # so there is no other path that submits it - any Mikrobiologie answers
    # a user typed were saved to the draft by autosave, but this loop never
    # looked at their keys, so they were silently never written to the
    # responses table on submit.
    all_questions <- c(
      fuehrung_questions,
      mit_questions,
      pat_questions,
      ein_questions,
      qual_questions,
      qual_mibi_questions
    )
    
    message("Processing ", length(all_questions), " questions...")
    
    processed <- 0
    skipped_na <- 0
    skipped_empty <- 0
    
    for (q in all_questions) {
      qid <- q$id
      score_key <- paste0("FremdbewertungNum_", qid)
      text_key <- paste0("FremdbewertungText_", qid)
      
      if (score_key %in% names(saved_answers)) {
        score <- saved_answers[[score_key]]
        text <- if (text_key %in% names(saved_answers))
          saved_answers[[text_key]]
        else
          ""
        
        # Debug first few
        if (processed < 5) {
          message("  ",
                  qid,
                  ": score=",
                  score,
                  ", text=",
                  if (!is.null(text) && nchar(text) > 0)
                    "yes"
                  else
                    "no")
        }
        
        if (is.null(score) || score == "") {
          skipped_empty <- skipped_empty + 1
          next
        }
        
        if (score == "N/A") {
          skipped_na <- skipped_na + 1
          next
        }
        
        responses_list[[length(responses_list) + 1]] <- list(
          user_id = as.integer(current_user_id),
          # âœ… FIX: Convert to INTEGER
          question_id = qid,
          response_value = as.character(score),
          text_value = if (!is.null(text) &&
                           text != "")
            as.character(text)
          else
            NA_character_,
          tag = NA_character_,
          assessment_type = "fremdbewertung",
          submission_id = submission_id,
          project_id = as.character(project_id),
          group_size = 1L
        )
        
        processed <- processed + 1
      }
    }
    
    message("âœ“ Processed: ", processed)
    message("  Skipped (empty): ", skipped_empty)
    message("  Skipped (N/A): ", skipped_na)
    message("  Total to insert: ", length(responses_list))
    
    if (length(responses_list) == 0) {
      message("âŒ No responses to insert")
      showNotification(
        "Keine Antworten zum Abschicken gefunden.",
        type = "warning",
        duration = 5
      )
      return(invisible(FALSE))
    }
    
    # Check for existing
    existing <- DBI::dbGetQuery(
      con,
      "SELECT COUNT(*) as count FROM responses
     WHERE user_id = $1
     AND project_id::text = $2::text
     AND assessment_type = 'fremdbewertung'",
      params = list(as.integer(current_user_id), as.character(project_id))
    )
    
    if (existing$count > 0) {
      message("âš  User already has ", existing$count, " responses")
      showModal(
        modalDialog(
          title = "Fremdbewertung bereits abgegeben",
          paste0(
            "Sie haben bereits ",
            existing$count,
            " Antworten abgegeben. Ãœberschreiben?"
          ),
          footer = tagList(
            modalButton("Abbrechen"),
            actionButton(
              "confirm_overwrite_fremd",
              "Ja, Ã¼berschreiben",
              class = "btn-danger"
            )
          )
        )
      )
      return(invisible(FALSE))
    }
    
    # Insert responses
    message("\n--- STARTING INSERT ---")
    
    tryCatch({
      sql <- "
      INSERT INTO responses (
        user_id, project_id, question_id, response_value, text_value,
        assessment_type, submission_id, tag, group_size, created_at
      ) VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9, NOW())
    "
      
      inserted <- 0
      
      for (i in 1:length(responses_list)) {
        resp <- responses_list[[i]]
        
        DBI::dbExecute(
          con,
          sql,
          params = list(
            resp$user_id,
            # INTEGER
            resp$project_id,
            # TEXT
            resp$question_id,
            # TEXT
            resp$response_value,
            # TEXT
            resp$text_value,
            # TEXT
            resp$assessment_type,
            # TEXT
            resp$submission_id,
            # TEXT
            resp$tag,
            # TEXT
            resp$group_size        # INTEGER
          )
        )
        
        inserted <- inserted + 1
        
        if (inserted <= 5 || inserted == length(responses_list)) {
          message("  âœ“ Inserted ",
                  resp$question_id,
                  ": ",
                  resp$response_value)
        }
      }
      
      message("--- INSERT COMPLETE ---")
      message("âœ“ Total inserted: ", inserted, " responses")
      
      # Mark draft as submitted
      DBI::dbExecute(
        con,
        "UPDATE questionnaire_drafts
       SET status = 'submitted', last_saved = NOW()
       WHERE user_id::text = $1::text
       AND project_id::text = $2::text
       AND questionnaire_id = $3",
        params = list(
          as.character(current_user_id),
          as.character(project_id),
          questionnaire_id
        )
      )
      
      message("âœ“ Draft marked as submitted")
      message("========== SUCCESS ==========\n")

      log_event(con, "fremdbewertung.abgesendet", entity_type = "fremdbewertung",
                entity_id = submission_id, project_id = as.character(project_id),
                new_value = paste0(inserted, " Antworten"),
                who = current_username(), role = user_role(), session_id = session$token)

      showNotification(
        paste0(
          "âœ… Fremdbewertung erfolgreich abgesendet! (",
          inserted,
          " Antworten)"
        ),
        type = "message",
        duration = 8
      )
      
      return(invisible(TRUE))
      
    }, error = function(e) {
      message("âŒâŒâŒ ERROR during INSERT:")
      message(e$message)
      print(e)
      
      showNotification(paste("âŒ Fehler:", e$message),
                       type = "error",
                       duration = 15)
      
      return(invisible(FALSE))
    })
  }
  
  # âœ… Overwrite confirmation handler
  observeEvent(input$confirm_overwrite_fremd, {
    removeModal()
    
    current_user_id <- user_id()
    project_id <- current_project_id()
    
    message("\n=== OVERWRITING EXISTING FREMDBEWERTUNG ===")
    
    con <- get_db_con()
    on.exit(DBI::dbDisconnect(con))
    
    tryCatch({
      # Delete old responses
      deleted <- DBI::dbExecute(
        con,
        "DELETE FROM responses
       WHERE user_id = $1
       AND project_id::text = $2::text
       AND assessment_type = 'fremdbewertung'",
        params = list(
          as.integer(current_user_id),
          as.character(project_id)
        )
      )
      
      message("âœ“ Deleted ", deleted, " old responses")
      
      # Reset draft to allow resubmission
      DBI::dbExecute(
        con,
        "UPDATE questionnaire_drafts
       SET status = 'draft'
       WHERE user_id::text = $1::text
       AND project_id::text = $2::text
       AND questionnaire_id = 'peer_fremdbewertung'",
        params = list(
          as.character(current_user_id),
          as.character(project_id)
        )
      )
      
      # Now submit new responses
      submit_all_fremdbewertung()
      
    }, error = function(e) {
      message("âŒ ERROR during overwrite: ", e$message)
      showNotification(
        paste("Fehler beim Ãœberschreiben:", e$message),
        type = "error",
        duration = 10
      )
    })
  }, ignoreInit = TRUE)
  
  
  
