      get_topic_responses <- function(prefix, questions, topic_name) {
        # âœ… FIXED: was LIKE 'prefix%' (via sprintf) - for prefix="Q" this
        # also matched "QM..." (Mikrobiologie), same class of bug fixed
        # elsewhere this session. Regex requires the prefix to be
        # immediately followed by a digit.
        df <- DBI::dbGetQuery(
          con,
          "SELECT u.username, r.question_id, r.response_value, r.text_value
         FROM responses r
         JOIN users u ON u.id = r.user_id
         WHERE r.assessment_type = 'selbstbewertung'
           AND r.project_id = $1 AND r.question_id ~ $2
         ORDER BY r.question_id, u.username",
          params = list(as.character(project_id), paste0("^", prefix, "[0-9]"))
        )
        
        if (nrow(df) > 0) {
          df$question <- sapply(df$question_id, function(qid) {
            q <- Find(function(x)
              x$id == qid, questions)
            if (!is.null(q))
              q$label
            else
              qid
          })
          df <- df[, c("question_id",
                       "username",
                       "question",
                       "response_value",
                       "text_value")]
          colnames(df) <- c("question_id",
                            "Nutzer",
                            "Frage",
                            "Bewertung",
                            "BegrÃ¼ndung")
        } else {
          df <- data.frame(
            question_id = character(0),
            Nutzer = character(0),
            Frage = character(0),
            Bewertung = character(0),
            BegrÃ¼ndung = character(0),
            stringsAsFactors = FALSE
          )
        }
        df
      }
      
