      pat_resp <- get_topic_responses("P", pat_questions, "Patienten")
      ein_resp <- get_topic_responses("E", ein_questions, "Einsender")
      qual_resp <- get_topic_responses("Q", qual_questions, "QualitÃ¤t")
      qual_mibi_resp <- get_topic_responses("QM", qual_mibi_questions, "QualitÃ¤t Mikrobiologie")
      
      write.csv(
