  output$downloadCoPeerFremdbewertung <- downloadHandler(
    filename = function() {
      paste0("meine_fremdbewertung_",
             format(Sys.Date(), "%Y%m%d"),
             ".pdf")
    },
    
    content = function(file) {
      message("=== Co-Peer Fremdbewertung Download started ===")
      
      user_id <- user_id()
      project_id <- current_project_id()
      
      if (is.null(user_id) || is.null(project_id)) {
        showNotification("Fehler: Kein Benutzer oder Projekt", type = "error")
        return(NULL)
      }
      
      tryCatch({
        message("Step 1: Getting user's Fremdbewertung from database")
        
        project_title <- tryCatch({
          con <- get_db_con()
          on.exit(DBI::dbDisconnect(con), add = TRUE)
          res <- DBI::dbGetQuery(con, "SELECT title FROM projects WHERE id = $1", params = list(as.integer(project_id)))
          if (nrow(res) > 0 && nzchar(res$title[1])) res$title[1] else "Projekt"
        }, error = function(e) "Projekt")
        
        # Get ONLY this co-peer's Fremdbewertung, straight from their draft
        fremd_data <- get_fremdbewertung_for_user_including_draft(project_id, user_id)
        
        message("  Found ", nrow(fremd_data), " responses")
        
