          return(NULL)
        }
        
        message("Step 2: Rendering PDF")
        
        section_defs <- list(
          list(key = "fuehrung",       heading = "FÃ¼hrung"),
          list(key = "mitarbeitende",  heading = "Mitarbeitende"),
          list(key = "patienten",      heading = "Patient und AngehÃ¶rige"),
          list(key = "einsender",      heading = "Einsender und Kooperationspartner"),
          list(key = "qualitaet",      heading = "QualitÃ¤tsindikatoren und Technische und Medizinische Validation"),
          list(key = "qualitaet_mibi", heading = "QualitÃ¤tsindikatoren - Mikrobiologie")
        )
        sections <- lapply(section_defs, function(sd) {
          list(heading = sd$heading, data = subset(fremd_data, Section == sd$key))
        })
        
        render_qa_report_pdf(
          file = file,
          title = "Peer Review Bericht",
          report_type = "Fremdbewertung",
          project_title = project_title,
          meta_lines = c(paste0("Erstellt: ", format(Sys.Date(), "%d. %B %Y"))),
          sections = sections,
          footer_text = PDFREPORT_FOOTER_TEXT,
          intro_lines = PDFREPORT_CONSENT_TEXT
        )
        
        message("=== Co-Peer Fremdbewertung Download completed ===")
        
        showNotification(
          "Ihre Fremdbewertung wurde erfolgreich heruntergeladen!",
          type = "message",
          duration = 5
