  # Selbstbewertung spider plot matching create_ggplot_overlay_radar style
  create_spider_plot_selbst <- function(project_id,
                                        section_name,
                                        topic_prefix,
                                        topic_label) {
    tryCatch({
      library(ggplot2)
      library(dplyr)
      
      con <- get_db_con()
      on.exit(DBI::dbDisconnect(con), add = TRUE)
      
      # Get Selbstbewertung with Berufsgruppe
      query <- "
      SELECT
        r.question_id,
        COALESCE(CAST(qd.answers::json->>'Berufsgruppe' AS TEXT), 'Nicht angegeben') as berufsgruppe,
        r.response_value::numeric as rv,
        COALESCE(CAST(qd.answers::json->>'group_size' AS INTEGER), 1) as group_size
      FROM responses r
      LEFT JOIN questionnaire_drafts qd
        ON r.user_id::text = qd.user_id::text
        AND r.project_id::text = qd.project_id::text
        AND qd.questionnaire_id = 'peer_review'
      WHERE r.project_id = $1
        AND r.assessment_type = 'selbstbewertung'
        AND r.question_id LIKE $2
        AND r.response_value ~ '^[0-9]+$'
    "
      
      responses <- DBI::dbGetQuery(con, query, params = list(as.character(project_id), paste0(topic_prefix, "%")))
      
      if (nrow(responses) == 0) {
        message("  No Selbstbewertung data for ", section_name)
        return(invisible(NULL))
      }
      
      # Expand by group_size
      expanded_list <- lapply(1:nrow(responses), function(i) {
        row <- responses[i, ]
        gs <- if (is.na(row$group_size) ||
                  row$group_size < 1)
          1
        else
          as.integer(row$group_size)
        
        data.frame(
          question_id = rep(row$question_id, gs),
          rv = rep(row$rv, gs),
          berufsgruppe = rep(row$berufsgruppe, gs),
          stringsAsFactors = FALSE
        )
      })
      
      expanded <- do.call(rbind, expanded_list)
      
      expanded$berufsgruppe <- normalize_berufsgruppe(expanded$berufsgruppe)
      means <- aggregate(rv ~ question_id + berufsgruppe,
                         data = expanded,
                         FUN = mean)
      
      # Calculate means per question per berufsgruppe
      means <- aggregate(rv ~ question_id + berufsgruppe,
                         data = expanded,
                         FUN = mean)
      
      # Get unique berufsgruppen
      berufsgruppen <- unique(means$berufsgruppe)
      
      
      bg_colors <- c(
        "MTL" = "#1f77b4",
        "Wissenschaftler(-in)" = "#ff7f0e",
        "Ã„rzte" = "#2ca02c",
        "IT" = "#d62728",
        "Sonstiges" = "#17becf",
        "nicht anwendbar" = "#9467bd",
        "Nicht angegeben" = "#8c564b"
      )
      
      # Extract question numbers
      means$question_num <- as.integer(gsub("\\D", "", means$question_id))
      
      # Get question list for ordering
      all_qnums <- sort(unique(means$question_num))
      n <- length(all_qnums)
      angles <- seq(0, 2 * pi, length.out = n + 1)[1:n]
      
      to_cartesian <- function(r, angle) {
        list(x = r * sin(angle), y = r * cos(angle))
      }
      
      # Create polygon data for each berufsgruppe
      all_polygons <- lapply(berufsgruppen, function(bg) {
        bg_data <- means[means$berufsgruppe == bg, ]
        
        # Match to all question numbers
        values <- sapply(all_qnums, function(qnum) {
          row <- bg_data[bg_data$question_num == qnum, ]
          if (nrow(row) > 0)
            row$rv[1]
          else
            0
        })
        
        # Convert to cartesian
        polygon_coords <- lapply(1:n, function(i) {
          coords <- to_cartesian(values[i], angles[i])
          data.frame(x = coords$x, y = coords$y)
        })
        polygon_df <- do.call(rbind, polygon_coords)
        polygon_df <- rbind(polygon_df, polygon_df[1, ])
        polygon_df$berufsgruppe <- bg
        
        return(polygon_df)
      })
      
      all_polygons_df <- do.call(rbind, all_polygons)
      
      # Grid circles
      grid_circles <- lapply(0:5, function(r) {
        angle_seq <- seq(0, 2 * pi, length.out = 100)
        coords <- lapply(angle_seq, function(a)
          to_cartesian(r, a))
        data.frame(
          x = sapply(coords, function(c)
            c$x),
          y = sapply(coords, function(c)
            c$y),
          r = r
        )
      })
      grid_df <- do.call(rbind, grid_circles)
      
      # Axis lines
      axis_lines <- lapply(1:n, function(i) {
        coords <- to_cartesian(5.5, angles[i])
        data.frame(
          x = 0,
          y = 0,
          xend = coords$x,
          yend = coords$y
        )
      })
      axis_df <- do.call(rbind, axis_lines)
      
      # Labels (question numbers only)
      labels <- as.character(all_qnums)
      label_coords <- lapply(1:n, function(i) {
        coords <- to_cartesian(6.2, angles[i])
        data.frame(x = coords$x,
                   y = coords$y,
                   label = labels[i])
      })
      label_df <- do.call(rbind, label_coords)
      
      # Create plot
      filename <- paste0("spider_selbst_", section_name, ".png")
      
      png(filename,
          width = 900,
          height = 950,
          res = 120)
      
      p <- ggplot() +
        # Grid circles
        geom_path(
          data = grid_df,
          aes(
            x = x,
            y = y,
            group = r
          ),
          color = "grey85",
          linewidth = 0.5
        ) +
        # Grid labels
        geom_text(
          data = data.frame(
            x = 0,
            y = 0:5,
            label = 0:5
          ),
          aes(
            x = x,
            y = y,
            label = label
          ),
          color = "grey50",
          size = 3,
          hjust = 1.5
        ) +
        # Axis lines
        geom_segment(
          data = axis_df,
          aes(
            x = x,
            y = y,
            xend = xend,
            yend = yend
          ),
          color = "grey70",
          linewidth = 0.5
        ) +
        # Polygons for each berufsgruppe
        geom_polygon(
          data = all_polygons_df,
          aes(
            x = x,
            y = y,
            fill = berufsgruppe,
            color = berufsgruppe,
            group = berufsgruppe
          ),
          alpha = 0.2,
          linewidth = 1.2
        ) +
        # Axis labels
        geom_text(
          data = label_df,
          aes(
            x = x,
            y = y,
            label = label
          ),
          size = 3.5,
          fontface = "bold"
        ) +
        scale_fill_manual(
          values = bg_colors,
          breaks = names(bg_colors),
          drop   = FALSE,
          name   = "Berufsgruppe"
        ) +
        scale_color_manual(
          values = bg_colors,
          breaks = names(bg_colors),
          drop   = FALSE,
          name   = "Berufsgruppe"
        ) +
        # Title
        ggtitle(paste("Selbstbewertung -", topic_label)) +
        coord_fixed() +
        xlim(c(-7, 7)) +
        ylim(c(-7.5, 7)) +
        theme_void() +
        theme(
          plot.title = element_text(
            hjust = 0.5,
            size = 16,
            face = "bold",
            margin = margin(b = 10)
          ),
          legend.position = "bottom",
          legend.title = element_text(size = 12, face = "bold"),
          legend.text = element_text(size = 10),
          plot.margin = margin(10, 10, 40, 10)
        )
      
      print(p)
      
      dev.off()
      
      message("  âœ“ Created spider_selbst_", section_name, ".png")
      
    }, error = function(e) {
      message("  ERROR creating Selbstbewertung spider plot: ",
              e$message)
    })
  }
  
  
  create_spider_plot_fremd <- function(project_id,
                                       section_name,
                                       topic_prefix,
                                       topic_label) {
    tryCatch({
      library(ggplot2)
      library(dplyr)
      
      con <- get_db_con()
      on.exit(DBI::dbDisconnect(con), add = TRUE)
      
      query <- "
      SELECT
        r.question_id,
        u.username as reviewer,
        AVG(r.response_value::numeric) as avg_rating
      FROM responses r
      JOIN users u ON u.id = r.user_id
      WHERE r.project_id = $1
        AND r.assessment_type = 'fremdbewertung'
        AND r.question_id LIKE $2
        AND r.response_value ~ '^[0-9]+$'
      GROUP BY r.question_id, u.username
      ORDER BY r.question_id, u.username
    "
      
      data <- DBI::dbGetQuery(con, query, params = list(as.character(project_id), paste0(topic_prefix, "%")))
      
      if (nrow(data) == 0) {
        message("  No Fremdbewertung data for ", section_name)
        return(invisible(NULL))
      }
      
      data$question_num <- as.integer(gsub("\\D", "", data$question_id))
      
      reviewers <- sort(unique(data$reviewer))
      
      peer_labels <- setNames(paste0("Peer ", seq_along(reviewers)), reviewers)
      
      data$peer_label <- peer_labels[data$reviewer]
      
      # âœ… Use new peer colors
      peer_colors <- SPIDER_COLORS$peers
      
      all_qnums <- sort(unique(data$question_num))
      n_questions <- length(all_qnums)
      
      angles <- seq(0, 2 * pi, length.out = n_questions + 1)[1:n_questions]
      
      to_cartesian <- function(r, angle) {
        list(x = r * sin(angle), y = r * cos(angle))
      }
      
      # Grid circles
      grid_circles <- lapply(0:5, function(r) {
        angle_seq <- seq(0, 2 * pi, length.out = 100)
        coords <- lapply(angle_seq, function(a)
          to_cartesian(r, a))
        data.frame(
          x = sapply(coords, function(c)
            c$x),
          y = sapply(coords, function(c)
            c$y),
          r = r
        )
      })
      grid_df <- do.call(rbind, grid_circles)
      
      # Axes
      axis_lines <- lapply(1:n_questions, function(i) {
        coords <- to_cartesian(5.5, angles[i])
        data.frame(
          x = 0,
          y = 0,
          xend = coords$x,
          yend = coords$y
        )
      })
      axis_df <- do.call(rbind, axis_lines)
      
      # Labels
      labels <- as.character(all_qnums)
      label_coords <- lapply(1:n_questions, function(i) {
        coords <- to_cartesian(6.2, angles[i])
        data.frame(x = coords$x,
                   y = coords$y,
                   label = labels[i])
      })
      label_df <- do.call(rbind, label_coords)
      
      # Create polygons for EACH peer
      polygon_list <- list()
      
      unique_peers <- unique(data$peer_label)
      
      for (peer in unique_peers) {
        peer_data <- data[data$peer_label == peer, ]
        
        values <- sapply(all_qnums, function(qnum) {
          row <- peer_data[peer_data$question_num == qnum, ]
          if (nrow(row) > 0)
            row$avg_rating[1]
          else
            NA
        })
        
        if (all(is.na(values)))
          next
        
        polygon_coords <- lapply(1:n_questions, function(i) {
          if (!is.na(values[i])) {
            coords <- to_cartesian(values[i], angles[i])
            data.frame(x = coords$x,
                       y = coords$y,
                       peer = peer)
          } else {
            NULL
          }
        })
        
        polygon_coords <- Filter(Negate(is.null), polygon_coords)
        
        if (length(polygon_coords) > 0) {
          polygon_df <- do.call(rbind, polygon_coords)
          polygon_df <- rbind(polygon_df, polygon_df[1, ])
          polygon_list[[length(polygon_list) + 1]] <- polygon_df
        }
      }
      
      all_polygons <- do.call(rbind, polygon_list)
      
      filename <- paste0("spider_fremd_", section_name, ".png")
      
      png(filename,
          width = 900,
          height = 950,
          res = 120)
      
      p <- ggplot() +
        geom_path(
          data = grid_df,
          aes(
            x = x,
            y = y,
            group = r
          ),
          color = "grey85",
          linewidth = 0.5
        ) +
        geom_text(
          data = data.frame(
            x = 0,
            y = 0:5,
            label = 0:5
          ),
          aes(
            x = x,
            y = y,
            label = label
          ),
          color = "grey50",
          size = 3,
          hjust = 1.5
        ) +
        geom_segment(
          data = axis_df,
          aes(
            x = x,
            y = y,
            xend = xend,
            yend = yend
          ),
          color = "grey70",
          linewidth = 0.5
        ) +
        geom_polygon(
          data = all_polygons,
          aes(
            x = x,
            y = y,
            fill = peer,
            color = peer,
            group = peer
          ),
          alpha = 0.2,
          linewidth = 1.2
        ) +
        geom_text(
          data = label_df,
          aes(
            x = x,
            y = y,
            label = label
          ),
          size = 3.5,
          fontface = "bold"
        ) +
        scale_fill_manual(values = peer_colors) +
        scale_color_manual(values = peer_colors) +
        ggtitle(paste("Fremdbewertung -", topic_label)) +
        coord_fixed() +
        xlim(c(-7, 7)) +
        ylim(c(-7.5, 7)) +
        theme_void() +
        theme(
          plot.title = element_text(
            hjust = 0.5,
            size = 16,
            face = "bold",
            margin = margin(b = 10)
          ),
          legend.position = "bottom",
          legend.direction = "horizontal",
          legend.title = element_blank(),
          legend.text = element_text(size = 10),
          plot.margin = margin(10, 10, 40, 10)
        )
      
      print(p)
      
      dev.off()
      
      message("  âœ“ Created spider_fremd_", section_name, ".png")
      
    }, error = function(e) {
      message("  ERROR creating Fremdbewertung spider plot: ", e$message)
    })
  }
  
  
  create_spider_plot_overlay <- function(project_id,
                                         section_name,
                                         topic_prefix,
                                         topic_label) {
    tryCatch({
      con <- get_db_con()
      on.exit(DBI::dbDisconnect(con), add = TRUE)
      
      # â”€â”€ Ã˜ Selbstbewertung per question (simple average, no berufsgruppe) â”€â”€â”€â”€â”€â”€â”€
      selbst_data <- DBI::dbGetQuery(
        con,
        "
      SELECT
        r.question_id,
        AVG(r.response_value::numeric) as avg_rating
      FROM responses r
      WHERE r.project_id = $1
        AND r.assessment_type = 'selbstbewertung'
        AND r.question_id LIKE $2
        AND r.response_value ~ '^[0-9]+$'
      GROUP BY r.question_id
      ORDER BY r.question_id
    ",
        params = list(as.character(project_id), paste0(topic_prefix, "%"))
      )
      
      # â”€â”€ Ã˜ Fremdbewertung per question (avg across ALL peers combined) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
      fremd_data <- DBI::dbGetQuery(
        con,
        "
      SELECT
        r.question_id,
        AVG(r.response_value::numeric) as avg_rating
      FROM responses r
      JOIN users u ON u.id = r.user_id
      WHERE r.project_id = $1
        AND r.assessment_type = 'fremdbewertung'
        AND r.question_id LIKE $2
        AND r.response_value ~ '^[0-9]+$'
      GROUP BY r.question_id
      ORDER BY r.question_id
    ",
        params = list(as.character(project_id), paste0(topic_prefix, "%"))
      )
      
      if (nrow(selbst_data) == 0 && nrow(fremd_data) == 0) {
        message("  No data for overlay plot for ", section_name)
        return(invisible(NULL))
      }
      
      selbst_data$question_num <- as.integer(gsub("\\D", "", selbst_data$question_id))
      fremd_data$question_num  <- as.integer(gsub("\\D", "", fremd_data$question_id))
      
      all_qnums   <- sort(unique(
        c(selbst_data$question_num, fremd_data$question_num)
      ))
      n_questions <- length(all_qnums)
      angles      <- seq(0, 2 * pi, length.out = n_questions + 1)[1:n_questions]
      
      to_cartesian <- function(r, angle)
        list(x = r * sin(angle), y = r * cos(angle))
      
      # Grid circles
      grid_df <- do.call(rbind, lapply(0:5, function(r) {
        angle_seq <- seq(0, 2 * pi, length.out = 100)
        data.frame(
          x = sapply(angle_seq, function(a)
            r * sin(a)),
          y = sapply(angle_seq, function(a)
            r * cos(a)),
          r = r
        )
      }))
      
      # Axis lines
      axis_df <- do.call(rbind, lapply(1:n_questions, function(i) {
        coords <- to_cartesian(5.5, angles[i])
        data.frame(
          x = 0,
          y = 0,
          xend = coords$x,
          yend = coords$y
        )
      }))
      
      # Axis labels
      label_df <- do.call(rbind, lapply(1:n_questions, function(i) {
        coords <- to_cartesian(6.2, angles[i])
        data.frame(x = coords$x,
                   y = coords$y,
                   label = as.character(all_qnums[i]))
      }))
      
      # Fixed two-line colors
      overlay_colors <- c(
        "Ã˜ Selbstbewertung" = "#2980B9",
        # blue
        "Ã˜ Fremdbewertung"  = "#E74C3C"   # red
      )
      
      # Helper: build one polygon from avg data
      build_polygon <- function(source_data, type_label) {
        values <- sapply(all_qnums, function(qnum) {
          row <- source_data[source_data$question_num == qnum, ]
          if (nrow(row) > 0)
            row$avg_rating[1]
          else
            NA
        })
        
        coords <- do.call(rbind, Filter(Negate(is.null), lapply(1:n_questions, function(i) {
          if (!is.na(values[i])) {
            c <- to_cartesian(values[i], angles[i])
            data.frame(x = c$x,
                       y = c$y,
                       type = type_label)
          } else
            NULL
        })))
        
        if (is.null(coords) || nrow(coords) == 0)
          return(NULL)
        rbind(coords, coords[1, ])
      }
      
      # Build only the two polygons
      polygons <- Filter(
        Negate(is.null),
        list(
          if (nrow(selbst_data) > 0)
            build_polygon(selbst_data, "Ã˜ Selbstbewertung")
          else
            NULL,
          if (nrow(fremd_data)  > 0)
            build_polygon(fremd_data, "Ã˜ Fremdbewertung")
          else
            NULL
        )
      )
      
      if (length(polygons) == 0) {
        message("  No polygons to draw for overlay ", section_name)
        return(invisible(NULL))
      }
      
      all_polygons_df <- do.call(rbind, polygons)
      # Lock factor levels so legend always shows both in correct order
      all_polygons_df$type <- factor(all_polygons_df$type,
                                     levels = c("Ã˜ Selbstbewertung", "Ã˜ Fremdbewertung"))
      
      filename <- paste0("spider_overlay_", section_name, ".png")
      png(filename,
          width = 900,
          height = 950,
          res = 120)
      
      p <- ggplot() +
        geom_path(
          data = grid_df,
          aes(
            x = x,
            y = y,
            group = r
          ),
          color = "grey85",
          linewidth = 0.5
        ) +
        geom_text(
          data = data.frame(
            x = 0,
            y = 0:5,
            label = 0:5
          ),
          aes(
            x = x,
            y = y,
            label = label
          ),
          color = "grey50",
          size = 3,
          hjust = 1.5
        ) +
        geom_segment(
          data = axis_df,
          aes(
            x = x,
            y = y,
            xend = xend,
            yend = yend
          ),
          color = "grey70",
          linewidth = 0.5
        ) +
        geom_polygon(
          data = all_polygons_df,
          aes(
            x = x,
            y = y,
            fill = type,
            color = type,
            group = type
          ),
          alpha = 0.25,
          linewidth = 1.4
        ) +
        geom_text(
          data = label_df,
          aes(
            x = x,
            y = y,
            label = label
          ),
          size = 3.5,
          fontface = "bold"
        ) +
        scale_fill_manual(
          values = overlay_colors,
          labels = c("Ã˜ Selbstbewertung", "Ã˜ Fremdbewertung"),
          drop   = FALSE
        ) +
        scale_color_manual(
          values = overlay_colors,
          labels = c("Ã˜ Selbstbewertung", "Ã˜ Fremdbewertung"),
          drop   = FALSE
        ) +
        ggtitle(paste("Ã˜ Selbst vs. Ã˜ Fremd -", topic_label)) +
        coord_fixed() +
        xlim(c(-7, 7)) + ylim(c(-7.5, 7)) +
        theme_void() +
        theme(
          plot.title       = element_text(
            hjust = 0.5,
            size = 16,
            face = "bold",
            margin = margin(b = 10)
          ),
          legend.position  = "bottom",
          legend.direction = "horizontal",
          legend.title     = element_blank(),
          legend.text      = element_text(size = 11),
          plot.margin      = margin(10, 10, 40, 10)
        )
      
      print(p)
      dev.off()
      
      message("  âœ“ Created spider_overlay_", section_name, ".png")
      
    }, error = function(e) {
      message("  ERROR creating overlay spider plot: ", e$message)
    })
  }
  
  # Generate comparison PDF function
  generate_comparison_pdf <- function(file, project_id, user_role = "leading_peer") {
    message("=== Comparison Table Download started ===")
    message("  Project ID: ", project_id)
    
    template_file <- "vergleichstabelle_template.Rmd"
    
    if (!file.exists(template_file)) {
      showNotification("Template nicht gefunden.",
                       type = "error",
                       duration = 10)
      writeLines("Template nicht verfÃ¼gbar.", file)
      return(NULL)
    }
    
    tryCatch({
      template_path <- normalizePath(template_file, mustWork = TRUE)
      # A private directory per download. tempdir() is shared by every session
      # in the same R process, so concurrent downloads used to overwrite each
      # other's comparison_table.csv, spider plots and comparison.tex.
      tmpdir        <- file.path(tempdir(),
                                 paste0("cmp_", as.integer(Sys.time()), "_",
                                        sample.int(1e6, 1)))
      dir.create(tmpdir, recursive = TRUE, showWarnings = FALSE)
      owd           <- setwd(tmpdir)
      on.exit(setwd(owd), add = TRUE)
      message("  Arbeitsverzeichnis: ", tmpdir)
      
      file.copy(template_path,
                file.path(tmpdir, template_file),
                overwrite = TRUE)
      
      con <- get_db_con()
      on.exit(DBI::dbDisconnect(con), add = TRUE)
      
      # â”€â”€ Step 1: Project title â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
      message("Step 1: Getting project title")
      project_title <- tryCatch({
        result <- DBI::dbGetQuery(con,
                                  "SELECT title FROM projects WHERE id = $1",
                                  params = list(as.integer(project_id)))
        if (nrow(result) > 0 &&
            !is.null(result$title[1]) &&
            nzchar(result$title[1])) {
          result$title[1]
        } else {
          "Projekt"
        }
      }, error = function(e)
        "Projekt")
      message("  Project Title: ", project_title)
      
      # â”€â”€ Step 2: Report metadata â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
      message("Step 2: Loading report metadata from database")
      report_metadata <- DBI::dbGetQuery(
        con,
        "SELECT * FROM report_metadata
       WHERE project_id = $1
       ORDER BY last_saved DESC
       LIMIT 1",
        params = list(as.integer(project_id))
      )
      
      if (nrow(report_metadata) > 0) {
        message("  âœ“ Found report metadata")
        
        report_meta <- data.frame(
          teilnehmende = if (!is.na(report_metadata$teilnehmende[1]))
            report_metadata$teilnehmende[1]
          else
            "",
          aekn         = if (!is.na(report_metadata$aekn[1]))
            report_metadata$aekn[1]
          else
            "",
          peer_team    = if (!is.na(report_metadata$peer_team[1]))
            report_metadata$peer_team[1]
          else
            "",
          ort          = if (!is.na(report_metadata$ort[1]))
            report_metadata$ort[1]
          else
            "",
          datum        = if (!is.na(report_metadata$datum[1]))
            report_metadata$datum[1]
          else
            "",
          stringsAsFactors = FALSE
        )
        zusammenfassung_besuch <- if (!is.na(report_metadata$zusammenfassung_besuch[1]))
          report_metadata$zusammenfassung_besuch[1]
        else
          ""
        swot_data <- data.frame(
          strengths     = if (!is.na(report_metadata$swot_strengths[1]))
            report_metadata$swot_strengths[1]
          else
            "",
          weaknesses    = if (!is.na(report_metadata$swot_weaknesses[1]))
            report_metadata$swot_weaknesses[1]
          else
            "",
          opportunities = if (!is.na(report_metadata$swot_opportunities[1]))
            report_metadata$swot_opportunities[1]
          else
            "",
          threats       = if (!is.na(report_metadata$swot_threats[1]))
            report_metadata$swot_threats[1]
          else
            "",
          stringsAsFactors = FALSE
        )
        best_practices_text <- if (!is.na(report_metadata$best_practices[1]))
          report_metadata$best_practices[1]
        else
          ""
        massnahmen_text     <- if (!is.na(report_metadata$massnahmen[1]))
          report_metadata$massnahmen[1]
        else
          ""
        final_remarks_text  <- if (!is.na(report_metadata$final_remarks[1]))
          report_metadata$final_remarks[1]
        else
          ""
        
      } else {
        message("  âš  No report metadata found - using defaults")
        report_meta <- data.frame(
          teilnehmende = "",
          aekn = "",
          peer_team = "",
          ort = "",
          datum = "",
          stringsAsFactors = FALSE
        )
        zusammenfassung_besuch <- ""
        swot_data <- data.frame(
          strengths = "",
          weaknesses = "",
          opportunities = "",
          threats = "",
          stringsAsFactors = FALSE
        )
        best_practices_text <- ""
        massnahmen_text     <- ""
        final_remarks_text  <- ""
      }
      
      write.csv(
        report_meta,
        file.path(tmpdir, "report_meta.csv"),
        row.names = FALSE,
        fileEncoding = "UTF-8"
      )
      write.csv(
        swot_data,
        file.path(tmpdir, "swot_data.csv"),
        row.names = FALSE,
        fileEncoding = "UTF-8"
      )
      writeLines(zusammenfassung_besuch,
                 file.path(tmpdir, "zusammenfassung_besuch.txt"))
      writeLines(best_practices_text,
                 file.path(tmpdir, "best_practices.txt"))
      writeLines(massnahmen_text, file.path(tmpdir, "massnahmen.txt"))
      writeLines(final_remarks_text,
                 file.path(tmpdir, "final_remarks.txt"))
      message("  âœ“ Report metadata saved")
      message("  âœ“ SWOT + text sections saved")
      
      # â”€â”€ Step 3: Lab info â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
      message("Step 3: Getting lab info")
      
      labinfo <- DBI::dbGetQuery(con,
                                 "SELECT * FROM lab_info WHERE project_id = $1",
                                 params = list(as.integer(project_id)))
      
      # Extract Hauptthema/Anlass (JSON in lab_info.anmerkungen)
      anmerkungen <- character()
      
      if (nrow(labinfo) > 0 &&
          "anmerkungen" %in% names(labinfo)) {
        anmerkungen_raw <- labinfo$anmerkungen[1]
        
        anmerkungen <- tryCatch({
          if (is.null(anmerkungen_raw) ||
              is.na(anmerkungen_raw) ||
              !nzchar(anmerkungen_raw)) {
            character()
          } else {
            out <- jsonlite::fromJSON(anmerkungen_raw)
            out <- as.character(out)
            out[nzchar(trimws(out))]
          }
        }, error = function(e) {
          message("WARNING: Could not parse lab_info.anmerkungen JSON: ",
                  e$message)
          character()
        })
      }
      
      message("  Anlass entries: ", length(anmerkungen))
      
      if (nrow(labinfo) == 0) {
        labinfo <- data.frame(
          name = "",
          trag = "",
          telefonnummer = "",
          email = "",
          internetadresse = "",
          ansprechpartner = "",
          anzahl_total = "",
          anzahl_mit = "",
          anzahl_tech = "",
          stringsAsFactors = FALSE
        )
      }
      
      write.csv(
        labinfo,
        file.path(tmpdir, "labinfo.csv"),
        row.names = FALSE,
        fileEncoding = "UTF-8"
      )
      message("  Lab info rows: ", nrow(labinfo))
      
      # â”€â”€ Step 4: Question lists â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
      message("Step 4: Exporting question lists")
      export_questions <- function(questions, filename) {
        df <- data.frame(
          id    = sapply(questions, function(q)
            q$id),
          label = sapply(questions, function(q)
            q$label),
          stringsAsFactors = FALSE
        )
        write.csv(
          df,
          file.path(tmpdir, filename),
          row.names = FALSE,
          fileEncoding = "UTF-8"
        )
      }
      export_questions(fuehrung_questions, "fuehrung_questions.csv")
      export_questions(mit_questions, "mitarbeitende_questions.csv")
      export_questions(pat_questions, "patienten_questions.csv")
      export_questions(ein_questions, "einsender_questions.csv")
      export_questions(qual_questions, "qualitaet_questions.csv")
      write.csv(
        data.frame(project_id = project_id),
        file.path(tmpdir, "project_info.csv"),
        row.names = FALSE
      )
      message("  âœ“ Question lists exported")
      
      # â”€â”€ Step 5: Comparison table â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
      message("Step 5: Building comparison table")
      selbst_avg <- DBI::dbGetQuery(
        con,
        "
      SELECT r.question_id, AVG(r.response_value::numeric) as selbst_avg
      FROM responses r
      WHERE r.project_id = $1
        AND r.assessment_type = 'selbstbewertung'
        AND r.response_value ~ '^[0-9]+$'
      GROUP BY r.question_id ORDER BY r.question_id",
        params = list(as.character(project_id))
      )
      
      fremd_avg <- DBI::dbGetQuery(
        con,
        "
      SELECT r.question_id, AVG(r.response_value::numeric) as fremd_avg
      FROM responses r
      JOIN users u ON u.id = r.user_id
      WHERE r.project_id = $1
        AND r.assessment_type = 'fremdbewertung'
        AND r.response_value ~ '^[0-9]+$'
      GROUP BY r.question_id ORDER BY r.question_id",
        params = list(as.character(project_id))
      )
      
      all_questions   <- c(
        fuehrung_questions,
        mit_questions,
        pat_questions,
        ein_questions,
        qual_questions
      )
      question_labels <- setNames(
        sapply(all_questions, function(q)
          q$label),
        sapply(all_questions, function(q)
          q$id)
      )
      comparison_table <- merge(selbst_avg, fremd_avg, by = "question_id", all = TRUE)
      comparison_table$Frage <- question_labels[comparison_table$question_id]
      comparison_table$Frage[is.na(comparison_table$Frage)] <- comparison_table$question_id[is.na(comparison_table$Frage)]
      comparison_table$Selbstbewertung <- ifelse(
        is.na(comparison_table$selbst_avg),
        "-",
        round(comparison_table$selbst_avg, 2)
      )
      comparison_table$Fremdbewertung  <- ifelse(
        is.na(comparison_table$fremd_avg),
        "-",
        round(comparison_table$fremd_avg, 2)
      )
      topic_order <- sapply(comparison_table$question_id, function(qid) {
        q <- Find(function(x)
          x$id == qid, all_questions)
        if (!is.null(q))
          q$number
        else
          999
      })
      comparison_table <- comparison_table[order(topic_order), c("Frage", "Selbstbewertung", "Fremdbewertung")]
      write.csv(
        comparison_table,
        file.path(tmpdir, "comparison_table.csv"),
        row.names = FALSE,
        fileEncoding = "UTF-8"
      )
      message("  âœ“ Comparison table saved (",
              nrow(comparison_table),
              " rows)")
      
      # â”€â”€ Step 6: Spider plots â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
      message("Step 6: Generating spider plots")
      topics <- list(
        list(
          section = "fuehrung",
          prefix = "F",
          label = "FÃ¼hrung"
        ),
        list(
          section = "mitarbeitende",
          prefix = "M",
          label = "Mitarbeitende"
        ),
        list(
          section = "patienten",
          prefix = "P",
          label = "Patienten"
        ),
        list(
          section = "einsender",
          prefix = "E",
          label = "Einsender"
        ),
        list(
          section = "qualitaet",
          prefix = "Q",
          label = "QualitÃ¤t"
        ),
        # âœ… ADDED: was missing from this list even though the report has a
        # Mikrobiologie topic and questions for it (QM...) - its spider
        # plots were silently never generated as a result.
        list(
          section = "qualitaet_mibi",
          prefix = "QM",
          label = "Mikrobiologie"
        )
      )
      for (t in topics) {
        create_spider_plot_selbst(project_id, t$section, t$prefix, t$label)
        create_spider_plot_fremd(project_id, t$section, t$prefix, t$label)
        create_spider_plot_overlay(project_id, t$section, t$prefix, t$label)
      }
      message("  âœ“ All spider plots created")
      
      # â”€â”€ Step 7: Render PDF â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
      message("Step 7: Rendering PDF")
      
      # Builds one Frage|Selbstbewertung|Fremdbewertung row per question, with
      # the Selbst-/Fremdbewertung cells written using the app's own
      # **bold**/++underline++/"- " bullet markup (not LaTeX) - the exact
      # same markup .pdfreport_layout_text() already parses, so no new
      # rendering logic is needed for what used to be a hand-built LaTeX
      # "card" per cell.
      build_comparison_rows <- function(questions, topic_prefix) {
        selbst_data <- DBI::dbGetQuery(con, "
          SELECT r.question_id, r.response_value AS rating, r.text_value AS comment,
                 COALESCE(CAST(qd.answers::json->>'group_size' AS INTEGER), 1) AS group_size
          FROM responses r
          LEFT JOIN questionnaire_drafts qd
            ON r.user_id::text = qd.user_id::text
           AND r.project_id::text = qd.project_id::text
           AND qd.questionnaire_id = 'peer_review'
          WHERE r.project_id = $1
            AND r.assessment_type = 'selbstbewertung'
            AND r.question_id ~ $2
            AND (r.response_value IS NOT NULL OR r.text_value IS NOT NULL)
          ORDER BY r.question_id
        ", params = list(as.character(project_id), paste0("^", topic_prefix, "[0-9]")))
        
        fremd_data <- DBI::dbGetQuery(con, "
          SELECT r.question_id, r.response_value AS rating, r.text_value AS comment
          FROM responses r
          WHERE r.project_id = $1
            AND r.assessment_type = 'fremdbewertung'
            AND r.question_id ~ $2
            AND (r.response_value IS NOT NULL OR r.text_value IS NOT NULL)
          ORDER BY r.question_id
        ", params = list(as.character(project_id), paste0("^", topic_prefix, "[0-9]")))
        
        build_side <- function(rows, who_label) {
          if (!nrow(rows)) return("-")
          
          # âœ… group_size is how many real people filled out that ONE
          # submission (alone = 1, or together as a group). "Teilnehmer: N"
          # must be the SUM of group_size across submissions, not the raw
          # row/submission count - otherwise 2 submissions where one was
          # filled by a group of 2 shows "Teilnehmer: 2" while the bulleted
          # comments below (their own [x1]/[x2] tags) add up to 3 real
          # people, which is exactly the mismatch reported.
          gs <- if ("group_size" %in% names(rows)) {
            g <- suppressWarnings(as.numeric(rows$group_size))
            g[is.na(g) | g < 1] <- 1
            g
          } else {
            rep(1, nrow(rows))
          }
          total <- sum(gs)
          
          ratings <- rows$rating
          ratings[is.na(ratings) | !nzchar(ratings)] <- "N/A"
          # Weight each rating by its row's group_size too, so "4 (x2)"
          # means 2 real people rated 4 - not 2 submissions (which might
          # themselves represent more or fewer real people).
          rtbl <- tapply(gs, ratings, sum)
          rdist <- paste(sapply(names(rtbl), function(r) {
            cnt <- as.integer(rtbl[[r]])
            if (cnt == 1) r else paste0(r, " (x", cnt, ")")
          }), collapse = ", ")
          
          valid_idx <- !is.na(rows$rating) & nzchar(rows$rating) &
            !is.na(suppressWarnings(as.numeric(rows$rating)))
          
          lines <- if (any(valid_idx)) {
            valid_r  <- as.numeric(rows$rating[valid_idx])
            valid_gs <- gs[valid_idx]
            avg <- sum(valid_r * valid_gs) / sum(valid_gs)
            sprintf("**%s: %d | Durchschnitt: %.2f**", who_label, total, avg)
          } else {
            sprintf("**%s: %d**", who_label, total)
          }
          lines <- c(lines, sprintf("**Verteilung: %s**", rdist))
          
          text_idx <- which(!is.na(rows$comment) & nzchar(trimws(rows$comment)))
          for (i in text_idx) {
            lines <- c(lines, paste0("- [x", gs[i], "] ", trimws(rows$comment[i])))
          }
          paste(lines, collapse = "\n")
        }
        
        sorted_questions <- questions[order(sapply(questions, function(q) q$number))]
        rows <- lapply(sorted_questions, function(q) {
          sr <- selbst_data[selbst_data$question_id == q$id, ]
          fr <- fremd_data[fremd_data$question_id == q$id, ]
          data.frame(
            Frage = paste0(q$number, ". ", q$label),
            Selbstbewertung = build_side(sr, "Teilnehmer"),
            Fremdbewertung = build_side(fr, "Reviewer"),
            stringsAsFactors = FALSE
          )
        })
        do.call(rbind, rows)
      }
      
      comparison_columns <- list(
        list(field = "Frage",           label = "Frage",           width = 0.24, align = "left"),
        list(field = "Selbstbewertung", label = "Selbstbewertung", width = 0.38, align = "left", richtext = TRUE),
        list(field = "Fremdbewertung",  label = "Fremdbewertung",  width = 0.38, align = "left", richtext = TRUE)
      )
      
      comparison_topic_defs <- list(
        list(prefix = "F",  heading = "FÃ¼hrung",       questions = fuehrung_questions, section = "fuehrung"),
        list(prefix = "M",  heading = "Mitarbeitende",     questions = mit_questions,       section = "mitarbeitende"),
        list(prefix = "P",  heading = "Patient und AngehÃ¶rige", questions = pat_questions, section = "patienten"),
        list(prefix = "E",  heading = "Einsender und Kooperationspartner", questions = ein_questions, section = "einsender"),
        list(prefix = "Q",  heading = "QualitÃ¤tsindikatoren und Validation", questions = qual_questions, section = "qualitaet"),
        list(prefix = "QM", heading = "QualitÃ¤tsindikatoren - Mikrobiologie", questions = qual_mibi_questions, section = "qualitaet_mibi")
      )
      
      comparison_sections <- lapply(seq_along(comparison_topic_defs), function(i) {
        td <- comparison_topic_defs[[i]]
        list(
          heading = paste0("4.", i, " ", td$heading),
          toc_level = 2,
          toc_parent = if (i == 1) "4. Vergleich Selbst- und Fremdbewertung" else NULL,
          pieces = list(
            list(type = "image", files = c(
              paste0("spider_selbst_", td$section, ".png"),
              paste0("spider_overlay_", td$section, ".png")
            )),
            list(type = "table", columns = comparison_columns,
                 data = build_comparison_rows(td$questions, td$prefix))
          )
        )
      })
      
      lv <- function(field) {
        if (nrow(labinfo) == 0 || !(field %in% names(labinfo))) return("Keine Angabe")
        v <- labinfo[[field]][1]
        if (is.null(v) || is.na(v) || !nzchar(trimws(as.character(v)))) "Keine Angabe" else as.character(v)
      }
      kv_item <- function(label, field) list(label = label, value = lv(field))
      fmt_binary <- function(field) {
        v <- lv(field)
        if (v %in% c("Ja", "Nein")) v else "Keine Angabe"
      }
      personal_rows <- data.frame(
        Kategorie = c("Gesamt", "Ã„rztliches Personal", "  - davon FachÃ¤rzte", "  - davon in Weiterbildung",
                      "  - Planstellen", "  - davon unbesetzt", "Technisches Personal", "  - Planstellen",
                      "  - davon unbesetzt", "Naturwissenschaftliches Personal", "  - Planstellen",
                      "  - davon unbesetzt", "IT-Mitarbeitende", "  - Planstellen", "  - davon unbesetzt"),
        Anzahl = c(lv("anzahl_total"), lv("anzahl_mit"), lv("davon_fachaerzte"), lv("davon_weiterbildung"),
                   lv("anzahl_planstellen"), lv("davon_unbesetzt"), lv("anzahl_tech"), lv("anzahl_tplanstellen"),
                   lv("davon_tunbesetzt"), lv("anzahl_natur"), lv("anzahl_nplanstellen"), lv("davon_nunbesetzt"),
                   lv("anzahl_it"), lv("anzahl_iplanstellen"), lv("davon_iunbesetzt")),
        stringsAsFactors = FALSE
      )
      edv_rows <- data.frame(
        Feld = c("Anbieter Laborinformationssystem", "Anbieter Order-Entry", "Anbieter Middleware", "Weitere IT-Systeme"),
        Wert = c(lv("anbieterinfo"), lv("anbieterorder"), lv("anbietermiddleware"), lv("weitereit")),
        stringsAsFactors = FALSE
      )
      kennzahlen_rows <- data.frame(
        Zeitraum = c("Laufendes Jahr", "Vorjahr"),
        Wert = c(lv("laufendenjahres"), lv("vorjahres")),
        stringsAsFactors = FALSE
      )
      
      anmerkungen_text <- if (!length(anmerkungen)) character(0) else paste0(seq_along(anmerkungen), ". ", anmerkungen)
      
      sections <- c(
        list(
          list(heading = "1. Zusammenfassung des Besuchs",
               pieces = list(list(type = "text", text = if (nzchar(zusammenfassung_besuch)) zusammenfassung_besuch else "Keine Angaben vorhanden."))),
          list(heading = "2. Teilnehmende",
               pieces = list(list(type = "kv", items = list(
                 list(label = "Teilnehmende", value = report_meta$teilnehmende[1]),
                 list(label = "Ã„KN", value = report_meta$aekn[1]),
                 list(label = "Peer-Team", value = report_meta$peer_team[1]),
                 list(label = "Ort", value = report_meta$ort[1]),
                 list(label = "Datum", value = report_meta$datum[1])
               )))),
          list(heading = "3. Laborinformationen",
               pieces = list(
                 list(type = "heading", level = 2, text = "Grundlagen und Organisation"),
                 list(type = "kv", items = list(
                   kv_item("Name und Anschrift der Einrichtung", "name"),
                   kv_item("Internetadresse", "internetadresse"),
                   kv_item("TrÃ¤gerschaft", "trag"),
                   kv_item("ZugehÃ¶rigkeit zu einem Unternehmensverbund", "zug"),
                   kv_item("Ansprechpartner", "ansprechpartner"),
                   kv_item("Email-Adresse", "email"),
                   kv_item("Telefonnummer", "telefonnummer"),
                   kv_item("Ã–ffnungszeiten", "oeffnungzeiten")
                 )),
                 list(type = "heading", level = 3, text = "Versorgung / Einsender"),
                 list(type = "kv", items = list(
                   kv_item("Versorgung", "versorgung"),
                   kv_item("Sonstiges (Versorgung)", "sonstiges_versorgung")
                 )),
                 list(type = "heading", level = 3, text = "Laborbereiche"),
                 list(type = "kv", items = list(
                   kv_item("Laborbereiche", "laborbereiche"),
                   kv_item("Sonstiges (Laborbereiche)", "sonstiges_laborbereiche")
                 )),
                 list(type = "heading", level = 3, text = "Leistungsspektrum / Methoden"),
                 list(type = "kv", items = list(
                   kv_item("Leistungsspektrum", "leistungsspektrum"),
                   kv_item("Sonstiges (Leistungsspektrum)", "sonstiges_leistungsspektrum")
                 )),
                 list(type = "heading", level = 3, text = "Ausstattung und Lieferanten"),
                 list(type = "kv", items = list(
                   kv_item("Ausstattung", "ausstattung"),
                   kv_item("Hauptlieferanten", "hauptlieferanten")
                 )),
                 list(type = "heading", level = 3, text = "Farbcodesysteme"),
                 list(type = "kv", items = list(
                   list(label = "Werden Farbcodesysteme einheitlich genutzt?", value = fmt_binary("question_binary_1")),
                   kv_item("Welche Farbcodesysteme werden verwendet", "farbcodesystem")
                 )),
                 list(type = "heading", level = 3, text = "Studienteilnahme"),
                 list(type = "kv", items = list(
                   list(label = "Nimmt Ihr Labor an Studien teil?", value = fmt_binary("question_binary_2"))
                 )),
                 list(type = "heading", level = 3, text = "Service und BefundÃ¼bermittlung"),
                 list(type = "kv", items = list(
                   kv_item("Verfahren zur Auftragsgenerierung", "auftragsgenerierung"),
                   kv_item("Hinweise zur PrÃ¤analytik", "praeanalytik"),
                   kv_item("BefundÃ¼bermittlung", "befunduebermittlung"),
                   kv_item("Service- und Beratungsleistungen", "beratungsleistungen"),
                   list(label = "Werden Hinweise zur DRG Gruppierung ausgegeben?", value = fmt_binary("question_binary_3"))
                 )),
                 list(type = "heading", level = 2, text = "Personal"),
                 list(type = "table", columns = list(
                   list(field = "Kategorie", label = "Kategorie", width = 0.6, align = "left"),
                   list(field = "Anzahl", label = "Anzahl", width = 0.4, align = "center")
                 ), data = personal_rows),
                 list(type = "kv", items = list(
                   kv_item("IT-UnterstÃ¼tzung", "beschreibung_it"),
                   kv_item("Weitere Informationen zu Personal", "weitereinfo_personal")
                 ))
               )),
          list(heading = "EDV und Kennzahlen",
               pieces = list(
                 list(type = "heading", level = 2, text = "System Informationen"),
                 list(type = "table", columns = list(
                   list(field = "Feld", label = "Feld", width = 0.4, align = "left"),
                   list(field = "Wert", label = "Wert", width = 0.6, align = "left")
                 ), data = edv_rows),
