                 list(type = "table", columns = list(
                   list(field = "Zeitraum", label = "Zeitraum", width = 0.3, align = "left"),
                   list(field = "Wert", label = "Analysenanzahlen / GOÃ„-Punkte / Mengenkennzahlen", width = 0.7, align = "left")
                 ), data = kennzahlen_rows),
                 list(type = "heading", level = 2, text = "ErgÃ¤nzungen"),
                 list(type = "kv", items = list(
                   kv_item("Kompetenzschwerpunkte und Alleinstellungsmerkmale", "kompetenzschwerpunkte"),
