          row.names = FALSE,
          fileEncoding = "UTF-8"
        )
        write.csv(
          ein_stats,
          file.path(tmpdir, "ein_stats.csv"),
          row.names = FALSE,
          fileEncoding = "UTF-8"
        )
        write.csv(
          qual_stats,
          file.path(tmpdir, "qual_stats.csv"),
          row.names = FALSE,
          fileEncoding = "UTF-8"
        )
        
        # Step 5: Create ggradar plots
        message("Step 5: Creating radar plots")
        
        mit_binary_global_qnums <- c(10, 20, 24)
        
        plot_configs <- list(
          list(
            name = "fuehrung",
            questions = fuehrung_questions,
            title = "FÃ¼hrung",
            colour = "#003B73",
            binary_qnums = integer(0)
          ),
          list(
            name = "mit",
