          ),
          list(
            name = "pat",
            questions = pat_questions,
            title = "Patienten",
            colour = "#b23a48",
            binary_qnums = integer(0)
          ),
          list(
            name = "ein",
            questions = ein_questions,
            title = "Einsender",
            colour = "#4b61d1",
            binary_qnums = integer(0)
          ),
          list(
            name = "qual",
            questions = qual_questions,
            title = "QualitÃ¤t",
            colour = "#c58f00",
            binary_qnums = integer(0)
          )
        )
        
        for (config in plot_configs) {
          plot_file <- file.path(tmpdir, paste0("plot_", config$name, ".png"))
          message(paste("  Creating plot:", config$title))
          
          tryCatch({
            # Get average responses for radar plot
            question_ids <- sapply(if (length(config$binary_qnums) > 0) {
              Filter(function(q)
                ! (q$number %in% config$binary_qnums),
                config$questions)
            } else {
              config$questions
            }, function(q)
              q$id)
            
            responses <- DBI::dbGetQuery(
              con,
              sprintf(
                "SELECT question_id, AVG(response_value::numeric) as avg_value
               FROM responses
               WHERE project_id = $1
                 AND assessment_type = 'selbstbewertung'
                 AND question_id IN (%s)
                 AND response_value IS NOT NULL
                 AND response_value != ''
               GROUP BY question_id",
                paste0("'", question_ids, "'", collapse = ", ")
              ),
              params = list(project_id)
            )
            
            if (nrow(responses) > 0) {
              # Create radar data frame for ggradar
              values <- sapply(question_ids, function(qid) {
                row <- responses[responses$question_id == qid, ]
                if (nrow(row) > 0)
                  row$avg_value
                else
                  0
              })
              
              radar_df <- data.frame(group = config$title, t(values))
              colnames(radar_df) <- c("group", paste0("Q", seq_along(values)))
              
              # Add min/max rows
              max_row <- radar_df
              max_row$group <- "Max"
              max_row[, -1] <- 5
              
              min_row <- radar_df
              min_row$group <- "Min"
              min_row[, -1] <- 0
              
              radar_df_full <- rbind(max_row, min_row, radar_df)
              
              # Create plot using fmsb-style function
              make_fmsb_radar_png(
                radar_df = radar_df_full[3, -1],
                # Just the data row
                title = config$title,
                colour = config$colour,
                filename = plot_file,
                width = 900,
                height = 700
              )
            } else {
              # Create placeholder
              png(plot_file, width = 800, height = 600)
              plot.new()
              text(0.5, 0.5, "Keine Daten verfÃ¼gbar", cex = 1.5)
              dev.off()
            }
          }, error = function(e) {
            message(paste("    ERROR:", e$message))
            png(plot_file, width = 800, height = 600)
            plot.new()
            text(0.5, 0.5, paste("Fehler:\n", config$title), cex = 1.5)
            dev.off()
          })
        }
        
        # Step 6: Render PDF
        message("Step 6: Rendering PDF")
        
        output_file <- rmarkdown::render(
          input = file.path(tmpdir, template_file),
          output_format = "pdf_document",
          output_file = "report.pdf",
          output_dir = tmpdir,
          params = list(project_title = project_name, project_id = project_id),
          envir = new.env(),
          quiet = FALSE
        )
        
        # Step 7: Copy to destination
        message("Step 7: Copying PDF")
        file.copy(output_file, file, overwrite = TRUE)
        
        removeNotification("pdf_progress")
        showNotification("PDF erfolgreich erstellt!",
                         type = "message",
                         duration = 5)
        
        message("=== PDF completed successfully ===")
        
      }, error = function(e) {
        message("=== ERROR ===")
        message(paste("Message:", e$message))
        
        removeNotification("pdf_progress")
        showNotification(
          paste("Fehler beim Erstellen des PDFs:", e$message),
          type = "error",
          duration = 15
        )
        
        writeLines(paste("Fehler:", e$message), file)
      })
    }
  )
  
  
}


shinyApp(ui = ui, server = server)